CREATE OR REPLACE FUNCTION "public"."get_broadcast_group_role"("p_group_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_group_org_id uuid;
  v_group_dept_id uuid;
  v_group_sub_dept_id uuid;
  v_user_org_id uuid;
  v_user_dept_id uuid;
  v_user_sub_dept_id uuid;
BEGIN
  -- A. Check for system management permissions first
  IF public.is_zeta() THEN  -- was the legacy admin/manager flag, retired 20261011
    RETURN 'admin';
  END IF;

  -- B. Check explicit participation in the group
  SELECT role INTO v_role
  FROM group_participants
  WHERE group_id = p_group_id
    AND employee_id = auth.uid()
  LIMIT 1;

  IF v_role IS NOT NULL THEN
    RETURN v_role;
  END IF;

  -- C. Check hierarchy inheritance
  SELECT organization_id, department_id, sub_department_id 
  INTO v_group_org_id, v_group_dept_id, v_group_sub_dept_id
  FROM broadcast_groups
  WHERE id = p_group_id;

  -- Get user's active contract
  SELECT organization_id, department_id, sub_department_id
  INTO v_user_org_id, v_user_dept_id, v_user_sub_dept_id
  FROM user_contracts
  WHERE user_id = auth.uid() AND status = 'Active'
  LIMIT 1;

  -- Match logic:
  -- If sub_dept is specified, must match exactly
  -- If only dept is specified, must match dept
  -- If only org is specified, must match org
  
  IF v_group_sub_dept_id IS NOT NULL THEN
    IF v_group_sub_dept_id = v_user_sub_dept_id THEN
      RETURN 'member';
    END IF;
  ELSIF v_group_dept_id IS NOT NULL THEN
    IF v_group_dept_id = v_user_dept_id THEN
      RETURN 'member';
    END IF;
  ELSIF v_group_org_id IS NOT NULL THEN
    IF v_group_org_id = v_user_org_id THEN
      RETURN 'member';
    END IF;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."get_broadcast_group_role"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cancellation_reason_breakdown"("p_from" "date", "p_to" "date", "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_subdept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("reason_code" "text", "reason_label" "text", "total" integer, "standard_count" integer, "critical_count" integer, "emergent_count" integer, "share_pct" numeric, "avg_notice_hours" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_perm jsonb;
    v_allowed_org_ids uuid[]; v_allowed_dept_ids uuid[]; v_allowed_subdept_ids uuid[];
    v_org_ids uuid[]; v_dept_ids uuid[]; v_subdept_ids uuid[];
BEGIN
    IF NOT public.is_manager_or_above() THEN
        RAISE EXCEPTION 'insufficient_privilege: managerial access required for KPI aggregates';
    END IF;

    v_perm := public.resolve_user_permissions();

    SELECT COALESCE(array_agg(DISTINCT (org->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_org_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org;

    SELECT COALESCE(array_agg(DISTINCT (dept->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_dept_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org,
           jsonb_array_elements(COALESCE(org->'departments', '[]'::jsonb)) dept;

    SELECT COALESCE(array_agg(DISTINCT (sd->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_subdept_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org,
           jsonb_array_elements(COALESCE(org->'departments', '[]'::jsonb)) dept,
           jsonb_array_elements(COALESCE(dept->'subdepartments', '[]'::jsonb)) sd;

    IF array_length(v_allowed_org_ids, 1) IS NULL THEN RETURN; END IF;

    v_org_ids := CASE WHEN p_org_ids IS NULL THEN v_allowed_org_ids
                      ELSE ARRAY(SELECT unnest(p_org_ids) INTERSECT SELECT unnest(v_allowed_org_ids)) END;
    v_dept_ids := CASE WHEN p_dept_ids IS NULL THEN v_allowed_dept_ids
                       ELSE ARRAY(SELECT unnest(p_dept_ids) INTERSECT SELECT unnest(v_allowed_dept_ids)) END;
    v_subdept_ids := CASE WHEN p_subdept_ids IS NULL THEN v_allowed_subdept_ids
                          ELSE ARRAY(SELECT unnest(p_subdept_ids) INTERSECT SELECT unnest(v_allowed_subdept_ids)) END;

    RETURN QUERY
    WITH drops AS (
        SELECT
            COALESCE(NULLIF(se.metadata->>'reason_code', ''), 'UNSPECIFIED') AS code,
            COALESCE(se.metadata->>'cancellation', 'standard')               AS kind,
            COALESCE(se.metadata->>'urgency', 'normal')                      AS urgency,
            NULLIF(se.metadata->>'notice_hours', '')::numeric                AS notice_hours
        FROM public.shift_events se
        JOIN public.shifts s ON s.id = se.shift_id
        WHERE se.event_type IN ('CANCELLED', 'LATE_CANCELLED')
          AND se.metadata->>'op' = 'employee_drop'
          AND s.shift_date BETWEEN p_from AND p_to
          AND (array_length(v_org_ids,1)     IS NULL OR s.organization_id    = ANY(v_org_ids))
          AND (array_length(v_dept_ids,1)    IS NULL OR s.department_id     = ANY(v_dept_ids))
          AND (array_length(v_subdept_ids,1) IS NULL OR s.sub_department_id = ANY(v_subdept_ids))
    ),
    grand AS (SELECT COUNT(*)::numeric AS n FROM drops)
    SELECT
        d.code,
        COALESCE(cr.label, initcap(replace(d.code, '_', ' ')))                      AS reason_label,
        COUNT(*)::int                                                                AS total,
        COUNT(*) FILTER (WHERE d.kind = 'standard')::int                             AS standard_count,
        COUNT(*) FILTER (WHERE d.kind = 'critical')::int                             AS critical_count,
        COUNT(*) FILTER (WHERE d.urgency = 'emergent')::int                          AS emergent_count,
        ROUND(CASE WHEN g.n = 0 THEN 0 ELSE COUNT(*)::numeric / g.n * 100 END, 1)    AS share_pct,
        ROUND(AVG(d.notice_hours), 1)                                                AS avg_notice_hours
    FROM drops d
    CROSS JOIN grand g
    LEFT JOIN public.cancellation_reasons cr ON cr.code = d.code
    GROUP BY d.code, cr.label, cr.sort_order, g.n
    ORDER BY COUNT(*) DESC, COALESCE(cr.sort_order, 1000), d.code;
END;
$$;


ALTER FUNCTION "public"."get_cancellation_reason_breakdown"("p_from" "date", "p_to" "date", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dept_insights_breakdown"("p_start_date" "date", "p_end_date" "date", "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_subdept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("dept_id" "uuid", "dept_name" "text", "shifts_total" integer, "shifts_assigned" integer, "fill_rate" numeric, "estimated_cost" numeric, "no_show_count" integer, "emergency_count" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        s.department_id,
        d.name,
        COUNT(*)::int,
        COUNT(*) FILTER (WHERE s.assigned_employee_id IS NOT NULL)::int,
        ROUND(CASE WHEN COUNT(*)=0 THEN 0 ELSE COUNT(*) FILTER (WHERE s.assigned_employee_id IS NOT NULL)::numeric/COUNT(*)*100 END,1),
        COALESCE(SUM(public.fn_eba_shift_cost(s)) FILTER (WHERE s.assigned_employee_id IS NOT NULL), 0),
        COUNT(*) FILTER (WHERE s.attendance_status='no_show' OR s.assignment_outcome='no_show')::int,
        COUNT(*) FILTER (WHERE s.emergency_assigned_at IS NOT NULL)::int
    FROM shifts s
    LEFT JOIN departments d ON d.id = s.department_id
    WHERE s.shift_date BETWEEN p_start_date AND p_end_date
      AND s.lifecycle_status != 'Draft'
      AND (p_org_ids     IS NULL OR s.organization_id    = ANY(p_org_ids))
      AND (p_dept_ids    IS NULL OR s.department_id      = ANY(p_dept_ids))
      AND (p_subdept_ids IS NULL OR s.sub_department_id  = ANY(p_subdept_ids))
    GROUP BY s.department_id, d.name
    ORDER BY d.name;
END;
$$;


ALTER FUNCTION "public"."get_dept_insights_breakdown"("p_start_date" "date", "p_end_date" "date", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_eligible_employees_for_shift"("p_shift_id" "uuid") RETURNS TABLE("employee_id" "uuid", "employee_name" "text", "employee_email" "text", "has_required_skills" boolean, "current_weekly_hours" numeric, "has_availability" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role_id uuid;
  v_shift_date date;
  v_start_time time;
  v_end_time time;
  v_week_start_date date;
BEGIN
  -- Get shift details
  SELECT role_id, shift_date, start_time, end_time
  INTO v_role_id, v_shift_date, v_start_time, v_end_time
  FROM shifts
  WHERE id = p_shift_id;

  -- Calculate week start (assuming week starts on Monday)
  v_week_start_date := v_shift_date - (EXTRACT(DOW FROM v_shift_date)::integer - 1);

  RETURN QUERY
  SELECT
    p.id AS employee_id,
    p.full_name AS employee_name,
    p.email AS employee_email,
    true AS has_required_skills, -- Check 'employee_skills' table if needed later
    calculate_weekly_hours(p.id, v_week_start_date) AS current_weekly_hours,
    NOT check_shift_overlap(p.id, v_shift_date, v_start_time, v_end_time) AS has_availability
  FROM profiles p
  WHERE EXISTS (
    SELECT 1 FROM user_contracts uc
    WHERE uc.user_id = p.id
      AND uc.role_id = v_role_id
      AND uc.status = 'active'
      AND (uc.end_date IS NULL OR uc.end_date >= v_shift_date)
      AND uc.start_date <= v_shift_date
  )
  ORDER BY calculate_weekly_hours(p.id, v_week_start_date) ASC;
END;
$$;


ALTER FUNCTION "public"."get_eligible_employees_for_shift"("p_shift_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_metrics"("p_employee_id" "uuid", "p_start_date" timestamp with time zone DEFAULT '-infinity'::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT 'infinity'::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_metrics JSONB;
BEGIN
    WITH events AS (
        SELECT se.event_type
        FROM public.shift_events se
        WHERE se.employee_id = p_employee_id
          AND se.event_time BETWEEN p_start_date AND p_end_date
    ),
    agg AS (
        SELECT
            COUNT(*) FILTER (WHERE event_type = 'OFFERED') AS offered,
            COUNT(*) FILTER (WHERE event_type = 'ACCEPTED') AS accepted,
            COUNT(*) FILTER (WHERE event_type = 'REJECTED') AS rejected,
            COUNT(*) FILTER (WHERE event_type = 'IGNORED') AS expired,
            COUNT(*) FILTER (WHERE event_type = 'ASSIGNED') AS assigned,
            COUNT(*) FILTER (WHERE event_type = 'EMERGENCY_ASSIGNED') AS emergency,
            COUNT(*) FILTER (WHERE event_type = 'CANCELLED') AS cancelled,
            COUNT(*) FILTER (WHERE event_type = 'LATE_CANCELLED') AS late_cancelled,
            COUNT(*) FILTER (WHERE event_type = 'SWAPPED_OUT') AS swapped,
            COUNT(*) FILTER (WHERE event_type = 'LATE_IN') AS late_in,
            COUNT(*) FILTER (WHERE event_type = 'EARLY_OUT') AS early_out,
            COUNT(*) FILTER (WHERE event_type = 'NO_SHOW') AS no_show,
            COUNT(*) FILTER (WHERE event_type = 'CHECKED_IN') AS worked
        FROM events
    )
    SELECT
        jsonb_build_object(
            'offers_sent', a.offered,
            'accepted', a.accepted,
            'rejected', a.rejected,
            'expired', a.expired,
            'assigned', a.assigned,
            'emergency_assigned', a.emergency,
            'cancel_standard', a.cancelled,
            'cancel_late', a.late_cancelled,
            'swap_out', a.swapped,
            'late_clock_in', a.late_in,
            'early_clock_out', a.early_out,
            'no_show', a.no_show,
            'completed', a.worked,
            'acceptance_rate', ROUND(CASE WHEN a.offered = 0 THEN 0 ELSE a.accepted::numeric / a.offered * 100 END, 1),
            'rejection_rate', ROUND(CASE WHEN a.offered = 0 THEN 0 ELSE a.rejected::numeric / a.offered * 100 END, 1),
            'ignorance_rate', ROUND(CASE WHEN a.offered = 0 THEN 0 ELSE a.expired::numeric / a.offered * 100 END, 1),
            'cancel_rate', ROUND(CASE WHEN a.assigned = 0 THEN 0 ELSE (a.cancelled + a.late_cancelled)::numeric / a.assigned * 100 END, 1),
            'late_cancel_rate', ROUND(CASE WHEN a.assigned = 0 THEN 0 ELSE a.late_cancelled::numeric / a.assigned * 100 END, 1),
            'swap_rate', ROUND(CASE WHEN a.assigned = 0 THEN 0 ELSE a.swapped::numeric / a.assigned * 100 END, 1),
            'reliability_score', GREATEST(0, LEAST(100, ROUND(
                100
                - (CASE WHEN a.assigned = 0 THEN 0 ELSE (a.cancelled + a.late_cancelled)::numeric / a.assigned * 30 END)
                - (CASE WHEN a.assigned = 0 THEN 0 ELSE a.late_cancelled::numeric / a.assigned * 20 END)
                - (CASE WHEN a.assigned = 0 THEN 0 ELSE a.no_show::numeric / a.assigned * 40 END)
                - (CASE WHEN a.worked = 0 THEN 0 ELSE a.late_in::numeric / a.worked * 5 END)
                - (CASE WHEN a.worked = 0 THEN 0 ELSE a.early_out::numeric / a.worked * 5 END)
            , 1))),
            'late_clock_in_rate', ROUND(CASE WHEN a.worked = 0 THEN 0 ELSE a.late_in::numeric / a.worked * 100 END, 1),
            'early_clock_out_rate', ROUND(CASE WHEN a.worked = 0 THEN 0 ELSE a.early_out::numeric / a.worked * 100 END, 1),
            'no_show_rate', ROUND(CASE WHEN a.assigned = 0 THEN 0 ELSE a.no_show::numeric / a.assigned * 100 END, 1)
        ) INTO v_metrics
    FROM agg a;

    RETURN v_metrics;
END;
$$;


ALTER FUNCTION "public"."get_employee_metrics"("p_employee_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_metrics"("p_employee_id" "uuid", "p_start_date" timestamp with time zone DEFAULT '-infinity'::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT 'infinity'::timestamp with time zone, "p_department_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_metrics JSONB;
BEGIN
    WITH events AS (
        SELECT 
            se.*,
            s.department_id
        FROM public.shift_events se
        JOIN public.shifts s ON se.shift_id = s.id
        WHERE se.employee_id = p_employee_id
          AND se.event_time >= p_start_date
          AND se.event_time <= p_end_date
          AND (p_department_id IS NULL OR s.department_id = p_department_id)
    ),
    counts AS (
        SELECT
            COUNT(*) FILTER (WHERE event_type = 'OFFERED') AS offered,
            COUNT(*) FILTER (WHERE event_type = 'ACCEPTED') AS accepted,
            COUNT(*) FILTER (WHERE event_type = 'REJECTED') AS rejected,
            COUNT(*) FILTER (WHERE event_type = 'CANCELLED') AS cancelled,
            COUNT(*) FILTER (WHERE event_type = 'LATE_CANCELLED') AS late_cancelled,
            COUNT(*) FILTER (WHERE event_type = 'NO_SHOW') AS no_show,
            COUNT(*) FILTER (WHERE event_type = 'LATE_IN') AS late_in,
            COUNT(*) FILTER (WHERE event_type = 'CHECKED_IN') AS worked
        FROM events
    )
    SELECT 
        jsonb_build_object(
            'offered', offered,
            'accepted', accepted,
            'rejected', rejected,
            'cancelled', cancelled,
            'late_cancelled', late_cancelled,
            'no_show', no_show,
            'worked', worked,
            'cancel_pct', CASE WHEN offered > 0 THEN (cancelled::float / offered * 100) ELSE 0 END,
            'reliability_score', (
                100 
                - (0.3 * CASE WHEN offered > 0 THEN (cancelled::float / offered * 100) ELSE 0 END)
                - (0.25 * CASE WHEN offered > 0 THEN (late_cancelled::float / offered * 100) ELSE 0 END)
                - (0.3 * CASE WHEN worked + no_show > 0 THEN (no_show::float / (worked + no_show) * 100) ELSE 0 END)
                - (0.15 * CASE WHEN worked > 0 THEN (late_in::float / worked * 100) ELSE 0 END)
            )
        ) INTO v_metrics
    FROM counts;

    RETURN v_metrics;
END;
$$;


ALTER FUNCTION "public"."get_employee_metrics"("p_employee_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_department_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_quarterly_performance"("p_employee_id" "uuid", "p_year" integer, "p_quarter" integer) RETURNS TABLE("employee_id" "uuid", "total_offers" integer, "accepted" integer, "rejected" integer, "expired" integer, "assigned" integer, "emergency_assigned" integer, "completed" integer, "no_show" integer, "swap_out" integer, "acceptance_rate" numeric, "rejection_rate" numeric, "ignorance_rate" numeric, "cancel_rate" numeric, "late_cancel_rate" numeric, "no_show_rate" numeric, "swap_rate" numeric, "reliability_score" numeric, "late_clock_in_rate" numeric, "early_clock_out_rate" numeric, "attendance_compliance_rate" numeric, "total_bids" integer, "bids_accepted" integer, "bid_success_rate" numeric, "trade_requests" integer, "performance_score" numeric, "engagement_score" numeric, "calculated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_start date;
    v_end   date;
BEGIN
    IF NOT (p_employee_id = auth.uid() OR public.is_manager_or_above()) THEN
        RAISE EXCEPTION 'insufficient_privilege: may only view your own performance, or requires managerial access';
    END IF;

    SELECT qdr.v_start, qdr.v_end INTO v_start, v_end
    FROM quarter_date_range(p_year, p_quarter) qdr;

    RETURN QUERY
    WITH
    offer_agg AS (
        SELECT
            COUNT(*) FILTER (WHERE ep.had_offer AND ep.terminal_outcome <> 'unassigned')::int                  AS total_offers_sent,
            COUNT(*) FILTER (WHERE ep.had_offer AND ep.had_accept AND ep.terminal_outcome <> 'unassigned')::int AS total_accepted,
            COUNT(*) FILTER (WHERE ep.had_offer AND ep.terminal_outcome = 'rejected')::int                     AS total_rejected,
            COUNT(*) FILTER (WHERE ep.had_offer AND ep.terminal_outcome = 'ignored')::int                      AS total_expired
        FROM v_shift_assignment_episodes ep
        WHERE ep.employee_id = p_employee_id
          AND ep.shift_date BETWEEN v_start AND v_end
          AND ep.terminal_outcome != 'shift_deleted'
    ),
    snap_agg AS (
        SELECT
            COUNT(*) FILTER (WHERE snap.source != 'emergency')::int                   AS assigned_count,
            COUNT(*) FILTER (WHERE snap.source = 'emergency')::int                    AS emergency_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'worked')::int                   AS completed_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'dropped_std')::int              AS cancel_standard_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'dropped_late')::int             AS cancel_late_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'traded_out')::int               AS swap_out_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'no_show')::int                  AS no_show_count,
            COUNT(*) FILTER (WHERE snap.late_in AND snap.end_reason = 'worked')::int  AS late_clock_in_count,
            COUNT(*) FILTER (WHERE snap.early_out AND snap.end_reason = 'worked')::int AS early_clock_out_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'worked' AND NOT snap.late_in AND NOT snap.early_out)::int AS compliant_count,
            COUNT(*)::int                                                             AS held_count
        FROM assignment_snapshots snap
        WHERE snap.employee_id = p_employee_id
          AND snap.shift_date BETWEEN v_start AND v_end
    ),
    bid_agg AS (
        SELECT
            COUNT(*)::int                                       AS total_bids,
            COUNT(*) FILTER (WHERE sb.status = 'accepted')::int AS bids_accepted
        FROM shift_bids sb
        JOIN shifts s ON s.id = sb.shift_id
        WHERE sb.employee_id = p_employee_id
          AND s.shift_date BETWEEN v_start AND v_end
    ),
    trade_agg AS (
        SELECT COUNT(*)::int AS trade_requests
        FROM swap_requests sr
        JOIN shifts s ON s.id = sr.original_shift_id
        WHERE sr.requested_by_employee_id = p_employee_id
          AND s.shift_date BETWEEN v_start AND v_end
    ),
    raw_metrics AS (
        SELECT
            COALESCE(oa.total_offers_sent, 0)::int AS total_offers,
            COALESCE(oa.total_accepted,    0)::int AS accepted,
            COALESCE(oa.total_rejected,    0)::int AS rejected,
            COALESCE(oa.total_expired,     0)::int AS expired,
            COALESCE(sa.assigned_count,    0)::int AS assigned,
            COALESCE(sa.emergency_count,   0)::int AS emergency_assigned,
            COALESCE(sa.completed_count,   0)::int AS completed,
            COALESCE(sa.no_show_count,     0)::int AS no_show,
            COALESCE(sa.swap_out_count,    0)::int AS swap_out,

            ROUND(CASE WHEN COALESCE(oa.total_offers_sent,0)=0 THEN 0
                  ELSE oa.total_accepted::numeric/oa.total_offers_sent*100 END,2)::numeric AS acceptance_rate,
            ROUND(CASE WHEN COALESCE(oa.total_offers_sent,0)=0 THEN 0
                  ELSE oa.total_rejected::numeric/oa.total_offers_sent*100 END,2)::numeric AS rejection_rate,
            ROUND(CASE WHEN COALESCE(oa.total_offers_sent,0)=0 THEN 0
                  ELSE oa.total_expired::numeric/oa.total_offers_sent*100 END,2)::numeric  AS ignorance_rate,

            ROUND(CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                  ELSE COALESCE(sa.cancel_standard_count,0)::numeric/sa.held_count*100 END,2)::numeric AS cancel_rate,
            ROUND(CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                  ELSE COALESCE(sa.cancel_late_count,0)::numeric/sa.held_count*100 END,2)::numeric AS late_cancel_rate,
            ROUND(CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                  ELSE COALESCE(sa.no_show_count,0)::numeric/sa.held_count*100 END,2)::numeric AS no_show_rate,
            ROUND(CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                  ELSE COALESCE(sa.swap_out_count,0)::numeric/sa.held_count*100 END,2)::numeric AS swap_rate,

            GREATEST(0,LEAST(100,ROUND(
                100
                -CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                      ELSE (COALESCE(sa.cancel_standard_count,0)+COALESCE(sa.cancel_late_count,0))::numeric/sa.held_count*30 END
                -CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                      ELSE COALESCE(sa.cancel_late_count,0)::numeric/sa.held_count*20 END
                -CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0 ELSE COALESCE(sa.no_show_count,0)::numeric/sa.held_count*40 END
                -CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                      ELSE COALESCE(sa.late_clock_in_count,0)::numeric/sa.completed_count*5 END
                -CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                      ELSE COALESCE(sa.early_clock_out_count,0)::numeric/sa.completed_count*5 END
            ,2)))::numeric AS reliability_score,

            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE COALESCE(sa.late_clock_in_count,0)::numeric/sa.completed_count*100 END,2)::numeric AS late_clock_in_rate,
            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE COALESCE(sa.early_clock_out_count,0)::numeric/sa.completed_count*100 END,2)::numeric AS early_clock_out_rate,
            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE sa.compliant_count::numeric/sa.completed_count*100 END, 2)::numeric AS attendance_compliance_rate,

            COALESCE(ba.total_bids, 0)::int AS total_bids,
            COALESCE(ba.bids_accepted, 0)::int AS bids_accepted,
            ROUND(CASE WHEN COALESCE(ba.total_bids,0)=0 THEN 0
                  ELSE ba.bids_accepted::numeric/ba.total_bids*100 END, 2)::numeric AS bid_success_rate,

            COALESCE(ta.trade_requests, 0)::int AS trade_requests
        FROM offer_agg oa, snap_agg sa, bid_agg ba, trade_agg ta
    )
    SELECT
        p_employee_id,
        rm.total_offers,
        rm.accepted,
        rm.rejected,
        rm.expired,
        rm.assigned,
        rm.emergency_assigned,
        rm.completed,
        rm.no_show,
        rm.swap_out,
        rm.acceptance_rate,
        rm.rejection_rate,
        rm.ignorance_rate,
        rm.cancel_rate,
        rm.late_cancel_rate,
        rm.no_show_rate,
        rm.swap_rate,
        rm.reliability_score,
        rm.late_clock_in_rate,
        rm.early_clock_out_rate,
        rm.attendance_compliance_rate,
        rm.total_bids,
        rm.bids_accepted,
        rm.bid_success_rate,
        rm.trade_requests,
        -- Same weighting as get_quarterly_performance_report(): keep these two in sync.
        ROUND(
            (rm.reliability_score * 0.35) +
            (rm.acceptance_rate * 0.25) +
            (rm.attendance_compliance_rate * 0.20) +
            (rm.bid_success_rate * 0.20),
            2
        )::numeric AS performance_score,
        GREATEST(0, LEAST(100, ROUND(
            (rm.total_bids + rm.trade_requests * 1.5 + rm.total_offers * 1.25)
            / GREATEST(rm.completed, 1)
            * 30,
            2
        )))::numeric AS engagement_score,
        now() AS calculated_at
    FROM raw_metrics rm;
END;
$$;


ALTER FUNCTION "public"."get_employee_quarterly_performance"("p_employee_id" "uuid", "p_year" integer, "p_quarter" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_shift_window"("p_employee_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_exclude_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "shift_date" "date", "start_time" time without time zone, "end_time" time without time zone, "unpaid_break_minutes" integer, "user_contract_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    s.id,
    s.shift_date,
    s.start_time,
    s.end_time,
    s.unpaid_break_minutes,
    s.user_contract_id
  FROM public.shifts s
  WHERE s.assigned_employee_id = p_employee_id
    AND s.shift_date >= p_start_date
    AND s.shift_date <= p_end_date
    AND s.lifecycle_status != 'Cancelled' -- Correct column name
    AND s.deleted_at IS NULL
    AND (p_exclude_id IS NULL OR s.id != p_exclude_id);
END;
$$;


ALTER FUNCTION "public"."get_employee_shift_window"("p_employee_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_exclude_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employees_shift_window_bulk"("p_employee_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("id" "uuid", "assigned_employee_id" "uuid", "shift_date" "date", "start_time" time without time zone, "end_time" time without time zone, "unpaid_break_minutes" integer, "user_contract_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_self_only boolean;
  v_wide      boolean;
BEGIN
  -- `auth.uid()`, never `current_user`: inside a SECURITY DEFINER body
  -- `current_user` is always the function OWNER and identifies nobody.
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  v_self_only := NOT EXISTS (
    SELECT 1 FROM unnest(coalesce(p_employee_ids, '{}'::uuid[])) e(uid)
    WHERE e.uid IS DISTINCT FROM v_uid
  );

  IF NOT v_self_only THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.app_access_certificates ac
      JOIN public.rbac_permissions rp ON rp.access_level = ac.access_level
      WHERE ac.user_id = v_uid AND ac.is_active
        AND rp.action_code = 'shift.view' AND rp.scope::text <> 'SELF'
      UNION ALL
      SELECT 1
      FROM public.user_contracts uc
      JOIN public.rbac_permissions rp ON rp.access_level = uc.access_level
      WHERE uc.user_id = v_uid AND uc.status = 'Active'
        AND rp.action_code = 'shift.view' AND rp.scope::text <> 'SELF'
    ) INTO v_wide;

    IF NOT v_wide THEN
      RAISE EXCEPTION 'not authorised to read other employees'' rosters'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  SELECT s.id, s.assigned_employee_id, s.shift_date, s.start_time, s.end_time, s.unpaid_break_minutes, s.user_contract_id
  FROM public.shifts s
  WHERE s.assigned_employee_id = ANY(p_employee_ids)
    AND s.shift_date >= p_start_date
    AND s.shift_date <= p_end_date
    AND s.lifecycle_status != 'Cancelled'
    AND s.deleted_at IS NULL;
END;
$$;


ALTER FUNCTION "public"."get_employees_shift_window_bulk"("p_employee_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_fairness_debts_latest"("p_org_id" "uuid", "p_employee_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("employee_id" "uuid", "metric" "text", "window_start" "date", "window_end" "date", "rolling_value" numeric, "team_average" numeric, "debt" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
    SELECT DISTINCT ON (fl.employee_id, fl.metric)
           fl.employee_id,
           fl.metric,
           fl.window_start,
           fl.window_end,
           fl.rolling_value,
           fl.team_average,
           fl.debt
      FROM public.fairness_ledger fl
     WHERE fl.organization_id = p_org_id
       AND fl.window_end     <= p_as_of
       AND (p_employee_ids IS NULL OR fl.employee_id = ANY (p_employee_ids))
     ORDER BY fl.employee_id, fl.metric, fl.window_end DESC;
$$;


ALTER FUNCTION "public"."get_fairness_debts_latest"("p_org_id" "uuid", "p_employee_ids" "uuid"[], "p_as_of" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_fairness_debts_latest"("p_org_id" "uuid", "p_employee_ids" "uuid"[], "p_as_of" "date") IS 'F1 fairness ledger: most recent debt row per (employee, metric) with window_end <= p_as_of. Replaces the exact window_end = today match that made the ledger read empty on any day without a recompute (audit F-04). Returns window_end so callers can surface staleness. SECURITY INVOKER - fairness_ledger_org_scoped RLS is the single access-control source.';



CREATE OR REPLACE FUNCTION "public"."get_insights_summary"("p_start_date" "date", "p_end_date" "date", "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_subdept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'hr'
    AS $$
DECLARE
    v_total       int; v_published   int; v_assigned    int;
    v_cancelled   int; v_completed   int; v_no_show     int;
    v_emergency   int; v_sched_hrs   numeric; v_cost      numeric;
    v_comp_over   int;
BEGIN
    SELECT
        COUNT(*)                                                             ,
        COUNT(*) FILTER (WHERE s.is_published = true)                       ,
        COUNT(*) FILTER (WHERE s.assigned_employee_id IS NOT NULL)           ,
        COUNT(*) FILTER (WHERE s.is_cancelled = true)                       ,
        COUNT(*) FILTER (WHERE s.lifecycle_status = 'Completed')            ,
        COUNT(*) FILTER (WHERE s.attendance_status = 'no_show'
                            OR s.assignment_outcome = 'no_show')            ,
        COUNT(*) FILTER (WHERE s.emergency_assigned_at IS NOT NULL)          ,
        COALESCE(SUM(COALESCE(s.net_length_minutes,0)::numeric / 60)
            FILTER (WHERE s.assigned_employee_id IS NOT NULL), 0)           ,
        COALESCE(SUM(public.fn_eba_shift_cost(s))
            FILTER (WHERE s.assigned_employee_id IS NOT NULL), 0)
    INTO
        v_total, v_published, v_assigned, v_cancelled,
        v_completed, v_no_show, v_emergency, v_sched_hrs, v_cost
    FROM shifts s
    WHERE s.shift_date BETWEEN p_start_date AND p_end_date
      AND (p_org_ids     IS NULL OR s.organization_id    = ANY(p_org_ids))
      AND (p_dept_ids    IS NULL OR s.department_id      = ANY(p_dept_ids))
      AND (p_subdept_ids IS NULL OR s.sub_department_id  = ANY(p_subdept_ids));

    SELECT COUNT(*) FILTER (WHERE s.compliance_override = true)
    INTO v_comp_over
    FROM shifts s
    WHERE s.shift_date BETWEEN p_start_date AND p_end_date
      AND (p_org_ids     IS NULL OR s.organization_id    = ANY(p_org_ids))
      AND (p_dept_ids    IS NULL OR s.department_id      = ANY(p_dept_ids))
      AND (p_subdept_ids IS NULL OR s.sub_department_id  = ANY(p_subdept_ids));

    RETURN json_build_object(
        'shifts_total',          COALESCE(v_total, 0),
        'shifts_published',      COALESCE(v_published, 0),
        'shifts_assigned',       COALESCE(v_assigned, 0),
        'shifts_unassigned',     GREATEST(0, COALESCE(v_total,0) - COALESCE(v_assigned,0) - COALESCE(v_cancelled,0)),
        'shifts_cancelled',      COALESCE(v_cancelled, 0),
        'shifts_completed',      COALESCE(v_completed, 0),
        'shifts_no_show',        COALESCE(v_no_show, 0),
        'shifts_emergency',      COALESCE(v_emergency, 0),
        'scheduled_hours',       COALESCE(v_sched_hrs, 0),
        'estimated_cost',        COALESCE(v_cost, 0),
        'shift_fill_rate',       CASE WHEN COALESCE(v_total,0) = 0 THEN 0
                                      ELSE ROUND(v_assigned::numeric / v_total * 100, 1) END,
        'compliance_overrides',  COALESCE(v_comp_over, 0),
        'no_show_rate',          CASE WHEN COALESCE(v_assigned,0) = 0 THEN 0
                                      ELSE ROUND(v_no_show::numeric / v_assigned * 100, 1) END
    );
END;
$$;


ALTER FUNCTION "public"."get_insights_summary"("p_start_date" "date", "p_end_date" "date", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_insights_trend"("p_start_date" "date", "p_end_date" "date", "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_subdept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("period_date" "date", "dept_id" "uuid", "dept_name" "text", "shifts_total" integer, "shifts_assigned" integer, "fill_rate" numeric, "estimated_cost" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        s.shift_date,
        s.department_id,
        d.name,
        COUNT(*)::int,
        COUNT(*) FILTER (WHERE s.assigned_employee_id IS NOT NULL)::int,
        ROUND(CASE WHEN COUNT(*)=0 THEN 0 ELSE COUNT(*) FILTER (WHERE s.assigned_employee_id IS NOT NULL)::numeric/COUNT(*)*100 END,1),
        COALESCE(SUM(public.fn_eba_shift_cost(s)) FILTER (WHERE s.assigned_employee_id IS NOT NULL), 0)
    FROM shifts s
    LEFT JOIN departments d ON d.id = s.department_id
    WHERE s.shift_date BETWEEN p_start_date AND p_end_date
      AND s.lifecycle_status != 'Draft'
      AND (p_org_ids     IS NULL OR s.organization_id    = ANY(p_org_ids))
      AND (p_dept_ids    IS NULL OR s.department_id      = ANY(p_dept_ids))
      AND (p_subdept_ids IS NULL OR s.sub_department_id  = ANY(p_subdept_ids))
    GROUP BY s.shift_date, s.department_id, d.name
    ORDER BY s.shift_date, d.name;
END;
$$;


ALTER FUNCTION "public"."get_insights_trend"("p_start_date" "date", "p_end_date" "date", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_kpi_behaviour_summary"("p_from" "date", "p_to" "date", "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_subdept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("held" integer, "worked" integer, "no_show" integer, "standard_cancellations" integer, "critical_cancellations" integer, "swapped_out" integer, "reassigned" integer, "emergency_assigned" integer, "on_time_in" integer, "on_time_out" integer, "early_clock_in" integer, "late_clock_in" integer, "early_clock_out" integer, "late_clock_out" integer, "auto_clock_out" integer, "attendance_compliant" integer, "employees" integer, "no_show_rate" numeric, "on_time_in_rate" numeric, "on_time_out_rate" numeric, "early_clock_in_rate" numeric, "late_clock_in_rate" numeric, "early_clock_out_rate" numeric, "late_clock_out_rate" numeric, "auto_clock_out_rate" numeric, "attendance_compliance_rate" numeric, "standard_cancel_rate" numeric, "critical_cancel_rate" numeric, "total_cancel_rate" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_perm jsonb;
    v_allowed_org_ids uuid[]; v_allowed_dept_ids uuid[]; v_allowed_subdept_ids uuid[];
    v_org_ids uuid[]; v_dept_ids uuid[]; v_subdept_ids uuid[];
BEGIN
    IF NOT public.is_manager_or_above() THEN
        RAISE EXCEPTION 'insufficient_privilege: managerial access required for KPI aggregates';
    END IF;

    v_perm := public.resolve_user_permissions();

    SELECT COALESCE(array_agg(DISTINCT (org->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_org_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org;

    SELECT COALESCE(array_agg(DISTINCT (dept->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_dept_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org,
           jsonb_array_elements(COALESCE(org->'departments', '[]'::jsonb)) dept;

    SELECT COALESCE(array_agg(DISTINCT (sd->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_subdept_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org,
           jsonb_array_elements(COALESCE(org->'departments', '[]'::jsonb)) dept,
           jsonb_array_elements(COALESCE(dept->'subdepartments', '[]'::jsonb)) sd;

    IF array_length(v_allowed_org_ids, 1) IS NULL THEN RETURN; END IF;

    v_org_ids := CASE WHEN p_org_ids IS NULL THEN v_allowed_org_ids
                      ELSE ARRAY(SELECT unnest(p_org_ids) INTERSECT SELECT unnest(v_allowed_org_ids)) END;
    v_dept_ids := CASE WHEN p_dept_ids IS NULL THEN v_allowed_dept_ids
                       ELSE ARRAY(SELECT unnest(p_dept_ids) INTERSECT SELECT unnest(v_allowed_dept_ids)) END;
    v_subdept_ids := CASE WHEN p_subdept_ids IS NULL THEN v_allowed_subdept_ids
                          ELSE ARRAY(SELECT unnest(p_subdept_ids) INTERSECT SELECT unnest(v_allowed_subdept_ids)) END;

    RETURN QUERY
    WITH agg AS (
        SELECT
            COUNT(*)::int                                                            AS c_held,
            COUNT(*) FILTER (WHERE s.end_reason = 'worked')::int                     AS c_worked,
            COUNT(*) FILTER (WHERE s.end_reason = 'no_show')::int                    AS c_no_show,
            COUNT(*) FILTER (WHERE s.end_reason = 'dropped_std')::int                AS c_std,
            COUNT(*) FILTER (WHERE s.end_reason = 'dropped_late')::int               AS c_critical,
            COUNT(*) FILTER (WHERE s.end_reason = 'traded_out')::int                 AS c_swap,
            COUNT(*) FILTER (WHERE s.end_reason = 'reassigned')::int                 AS c_reassigned,
            COUNT(*) FILTER (WHERE s.source = 'emergency')::int                      AS c_emergency,
            COUNT(*) FILTER (WHERE s.on_time_in     AND s.end_reason = 'worked')::int AS c_oti,
            COUNT(*) FILTER (WHERE s.on_time_out    AND s.end_reason = 'worked')::int AS c_oto,
            COUNT(*) FILTER (WHERE s.early_in       AND s.end_reason = 'worked')::int AS c_ei,
            COUNT(*) FILTER (WHERE s.late_in        AND s.end_reason = 'worked')::int AS c_li,
            COUNT(*) FILTER (WHERE s.early_out      AND s.end_reason = 'worked')::int AS c_eo,
            COUNT(*) FILTER (WHERE s.late_out       AND s.end_reason = 'worked')::int AS c_lo,
            COUNT(*) FILTER (WHERE s.auto_clock_out AND s.end_reason = 'worked')::int AS c_aco,
            COUNT(*) FILTER (WHERE s.end_reason = 'worked'
                             AND NOT s.late_in AND NOT s.early_out)::int              AS c_compliant,
            COUNT(DISTINCT s.employee_id)::int                                        AS c_employees
        FROM public.assignment_snapshots s
        WHERE s.shift_date BETWEEN p_from AND p_to
          AND (array_length(v_org_ids,1)     IS NULL OR s.organization_id    = ANY(v_org_ids))
          AND (array_length(v_dept_ids,1)    IS NULL OR s.department_id     = ANY(v_dept_ids))
          AND (array_length(v_subdept_ids,1) IS NULL OR s.sub_department_id = ANY(v_subdept_ids))
    )
    SELECT
        a.c_held, a.c_worked, a.c_no_show, a.c_std, a.c_critical, a.c_swap, a.c_reassigned,
        a.c_emergency, a.c_oti, a.c_oto, a.c_ei, a.c_li, a.c_eo, a.c_lo, a.c_aco,
        a.c_compliant, a.c_employees,
        ROUND(CASE WHEN a.c_held   = 0 THEN 0 ELSE a.c_no_show::numeric   / a.c_held   * 100 END, 2),
        ROUND(CASE WHEN a.c_worked = 0 THEN 0 ELSE a.c_oti::numeric       / a.c_worked * 100 END, 2),
        ROUND(CASE WHEN a.c_worked = 0 THEN 0 ELSE a.c_oto::numeric       / a.c_worked * 100 END, 2),
        ROUND(CASE WHEN a.c_worked = 0 THEN 0 ELSE a.c_ei::numeric        / a.c_worked * 100 END, 2),
        ROUND(CASE WHEN a.c_worked = 0 THEN 0 ELSE a.c_li::numeric        / a.c_worked * 100 END, 2),
        ROUND(CASE WHEN a.c_worked = 0 THEN 0 ELSE a.c_eo::numeric        / a.c_worked * 100 END, 2),
        ROUND(CASE WHEN a.c_worked = 0 THEN 0 ELSE a.c_lo::numeric        / a.c_worked * 100 END, 2),
        ROUND(CASE WHEN a.c_worked = 0 THEN 0 ELSE a.c_aco::numeric       / a.c_worked * 100 END, 2),
        ROUND(CASE WHEN a.c_worked = 0 THEN 0 ELSE a.c_compliant::numeric / a.c_worked * 100 END, 2),
        ROUND(CASE WHEN a.c_held   = 0 THEN 0 ELSE a.c_std::numeric       / a.c_held   * 100 END, 2),
        ROUND(CASE WHEN a.c_held   = 0 THEN 0 ELSE a.c_critical::numeric  / a.c_held   * 100 END, 2),
        ROUND(CASE WHEN a.c_held   = 0 THEN 0 ELSE (a.c_std + a.c_critical)::numeric / a.c_held * 100 END, 2)
    FROM agg a;
END;
$$;


ALTER FUNCTION "public"."get_kpi_behaviour_summary"("p_from" "date", "p_to" "date", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_kpi_behaviour_trend"("p_from" "date", "p_to" "date", "p_grain" "text" DEFAULT 'week'::"text", "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_subdept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("bucket_start" "date", "held" integer, "worked" integer, "no_show" integer, "standard_cancellations" integer, "critical_cancellations" integer, "swapped_out" integer, "on_time_in" integer, "late_clock_in" integer, "early_clock_out" integer, "auto_clock_out" integer, "attendance_compliant" integer, "no_show_rate" numeric, "attendance_compliance_rate" numeric, "standard_cancel_rate" numeric, "critical_cancel_rate" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_perm jsonb;
    v_allowed_org_ids uuid[]; v_allowed_dept_ids uuid[]; v_allowed_subdept_ids uuid[];
    v_org_ids uuid[]; v_dept_ids uuid[]; v_subdept_ids uuid[];
    v_grain text;
BEGIN
    IF NOT public.is_manager_or_above() THEN
        RAISE EXCEPTION 'insufficient_privilege: managerial access required for KPI aggregates';
    END IF;

    -- Whitelist, never interpolate: p_grain reaches date_trunc.
    v_grain := CASE lower(COALESCE(p_grain, 'week')) WHEN 'day' THEN 'day' ELSE 'week' END;

    v_perm := public.resolve_user_permissions();

    SELECT COALESCE(array_agg(DISTINCT (org->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_org_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org;

    SELECT COALESCE(array_agg(DISTINCT (dept->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_dept_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org,
           jsonb_array_elements(COALESCE(org->'departments', '[]'::jsonb)) dept;

    SELECT COALESCE(array_agg(DISTINCT (sd->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_subdept_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org,
           jsonb_array_elements(COALESCE(org->'departments', '[]'::jsonb)) dept,
           jsonb_array_elements(COALESCE(dept->'subdepartments', '[]'::jsonb)) sd;

    IF array_length(v_allowed_org_ids, 1) IS NULL THEN RETURN; END IF;

    v_org_ids := CASE WHEN p_org_ids IS NULL THEN v_allowed_org_ids
                      ELSE ARRAY(SELECT unnest(p_org_ids) INTERSECT SELECT unnest(v_allowed_org_ids)) END;
    v_dept_ids := CASE WHEN p_dept_ids IS NULL THEN v_allowed_dept_ids
                       ELSE ARRAY(SELECT unnest(p_dept_ids) INTERSECT SELECT unnest(v_allowed_dept_ids)) END;
    v_subdept_ids := CASE WHEN p_subdept_ids IS NULL THEN v_allowed_subdept_ids
                          ELSE ARRAY(SELECT unnest(p_subdept_ids) INTERSECT SELECT unnest(v_allowed_subdept_ids)) END;

    RETURN QUERY
    WITH buckets AS (
        SELECT generate_series(
                   date_trunc(v_grain, p_from::timestamp),
                   date_trunc(v_grain, p_to::timestamp),
                   CASE v_grain WHEN 'day' THEN interval '1 day' ELSE interval '1 week' END
               )::date AS b
    ),
    agg AS (
        SELECT
            date_trunc(v_grain, s.shift_date::timestamp)::date                       AS b,
            COUNT(*)::int                                                            AS c_held,
            COUNT(*) FILTER (WHERE s.end_reason = 'worked')::int                     AS c_worked,
            COUNT(*) FILTER (WHERE s.end_reason = 'no_show')::int                    AS c_no_show,
            COUNT(*) FILTER (WHERE s.end_reason = 'dropped_std')::int                AS c_std,
            COUNT(*) FILTER (WHERE s.end_reason = 'dropped_late')::int               AS c_critical,
            COUNT(*) FILTER (WHERE s.end_reason = 'traded_out')::int                 AS c_swap,
            COUNT(*) FILTER (WHERE s.on_time_in     AND s.end_reason = 'worked')::int AS c_oti,
            COUNT(*) FILTER (WHERE s.late_in        AND s.end_reason = 'worked')::int AS c_li,
            COUNT(*) FILTER (WHERE s.early_out      AND s.end_reason = 'worked')::int AS c_eo,
            COUNT(*) FILTER (WHERE s.auto_clock_out AND s.end_reason = 'worked')::int AS c_aco,
            COUNT(*) FILTER (WHERE s.end_reason = 'worked'
                             AND NOT s.late_in AND NOT s.early_out)::int              AS c_compliant
        FROM public.assignment_snapshots s
        WHERE s.shift_date BETWEEN p_from AND p_to
          AND (array_length(v_org_ids,1)     IS NULL OR s.organization_id    = ANY(v_org_ids))
          AND (array_length(v_dept_ids,1)    IS NULL OR s.department_id     = ANY(v_dept_ids))
          AND (array_length(v_subdept_ids,1) IS NULL OR s.sub_department_id = ANY(v_subdept_ids))
        GROUP BY 1
    )
    SELECT
        b.b,
        COALESCE(a.c_held, 0),
        COALESCE(a.c_worked, 0),
        COALESCE(a.c_no_show, 0),
        COALESCE(a.c_std, 0),
        COALESCE(a.c_critical, 0),
        COALESCE(a.c_swap, 0),
        COALESCE(a.c_oti, 0),
        COALESCE(a.c_li, 0),
        COALESCE(a.c_eo, 0),
        COALESCE(a.c_aco, 0),
        COALESCE(a.c_compliant, 0),
        ROUND(CASE WHEN COALESCE(a.c_held,0)   = 0 THEN 0 ELSE a.c_no_show::numeric   / a.c_held   * 100 END, 2),
        ROUND(CASE WHEN COALESCE(a.c_worked,0) = 0 THEN 0 ELSE a.c_compliant::numeric / a.c_worked * 100 END, 2),
        ROUND(CASE WHEN COALESCE(a.c_held,0)   = 0 THEN 0 ELSE a.c_std::numeric       / a.c_held   * 100 END, 2),
        ROUND(CASE WHEN COALESCE(a.c_held,0)   = 0 THEN 0 ELSE a.c_critical::numeric  / a.c_held   * 100 END, 2)
    FROM buckets b
    LEFT JOIN agg a ON a.b = b.b
    ORDER BY b.b;
END;
$$;


ALTER FUNCTION "public"."get_kpi_behaviour_trend"("p_from" "date", "p_to" "date", "p_grain" "text", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_kpi_marketplace_trend"("p_from" "date", "p_to" "date", "p_grain" "text" DEFAULT 'week'::"text", "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_subdept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("bucket_start" "date", "open_shifts" integer, "bids_placed" integer, "winners_selected" integer, "award_rate" numeric, "swaps_initiated" integer, "swaps_completed" integer, "swaps_rejected" integer, "swaps_cancelled" integer, "swap_completion_rate" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_perm jsonb;
    v_allowed_org_ids uuid[]; v_allowed_dept_ids uuid[]; v_allowed_subdept_ids uuid[];
    v_org_ids uuid[]; v_dept_ids uuid[]; v_subdept_ids uuid[];
    v_grain text;
BEGIN
    IF NOT public.is_manager_or_above() THEN
        RAISE EXCEPTION 'insufficient_privilege: managerial access required for KPI aggregates';
    END IF;

    -- Whitelist, never interpolate: p_grain reaches date_trunc.
    v_grain := CASE lower(COALESCE(p_grain, 'week')) WHEN 'day' THEN 'day' ELSE 'week' END;

    v_perm := public.resolve_user_permissions();

    SELECT COALESCE(array_agg(DISTINCT (org->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_org_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org;

    SELECT COALESCE(array_agg(DISTINCT (dept->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_dept_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org,
           jsonb_array_elements(COALESCE(org->'departments', '[]'::jsonb)) dept;

    SELECT COALESCE(array_agg(DISTINCT (sd->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_allowed_subdept_ids
      FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org,
           jsonb_array_elements(COALESCE(org->'departments', '[]'::jsonb)) dept,
           jsonb_array_elements(COALESCE(dept->'subdepartments', '[]'::jsonb)) sd;

    IF array_length(v_allowed_org_ids, 1) IS NULL THEN RETURN; END IF;

    v_org_ids := CASE WHEN p_org_ids IS NULL THEN v_allowed_org_ids
                      ELSE ARRAY(SELECT unnest(p_org_ids) INTERSECT SELECT unnest(v_allowed_org_ids)) END;
    v_dept_ids := CASE WHEN p_dept_ids IS NULL THEN v_allowed_dept_ids
                       ELSE ARRAY(SELECT unnest(p_dept_ids) INTERSECT SELECT unnest(v_allowed_dept_ids)) END;
    v_subdept_ids := CASE WHEN p_subdept_ids IS NULL THEN v_allowed_subdept_ids
                          ELSE ARRAY(SELECT unnest(p_subdept_ids) INTERSECT SELECT unnest(v_allowed_subdept_ids)) END;

    RETURN QUERY
    WITH buckets AS (
        SELECT generate_series(
                   date_trunc(v_grain, p_from::timestamp),
                   date_trunc(v_grain, p_to::timestamp),
                   CASE v_grain WHEN 'day' THEN interval '1 day' ELSE interval '1 week' END
               )::date AS b
    ),
    scoped_shifts AS (
        SELECT s.id, date_trunc(v_grain, s.shift_date::timestamp)::date AS b, s.bidding_status
        FROM public.shifts s
        WHERE s.shift_date BETWEEN p_from AND p_to
          AND s.deleted_at IS NULL
          AND (array_length(v_org_ids,1)     IS NULL OR s.organization_id    = ANY(v_org_ids))
          AND (array_length(v_dept_ids,1)    IS NULL OR s.department_id     = ANY(v_dept_ids))
          AND (array_length(v_subdept_ids,1) IS NULL OR s.sub_department_id = ANY(v_subdept_ids))
    ),
    bid_agg AS (
        SELECT ss.b,
               COUNT(DISTINCT ss.id) FILTER (
                   WHERE ss.bidding_status NOT IN ('not_on_bidding', 'bidding_closed_no_winner')
                      OR sb.id IS NOT NULL
               )::int                                                    AS open_shifts,
               COUNT(sb.id)::int                                         AS bids_placed,
               COUNT(DISTINCT sb.shift_id) FILTER (WHERE sb.status = 'accepted')::int AS winners
        FROM scoped_shifts ss
        LEFT JOIN public.shift_bids sb ON sb.shift_id = ss.id
        GROUP BY ss.b
    ),
    swap_agg AS (
        SELECT ss.b,
               COUNT(sr.id)::int                                              AS initiated,
               COUNT(*) FILTER (WHERE sr.status = 'approved')::int            AS completed,
               COUNT(*) FILTER (WHERE sr.status = 'rejected')::int            AS rejected,
               COUNT(*) FILTER (WHERE sr.status = 'cancelled')::int           AS cancelled
        FROM scoped_shifts ss
        JOIN public.swap_requests sr ON sr.original_shift_id = ss.id
        GROUP BY ss.b
    )
    SELECT
        bk.b,
        COALESCE(ba.open_shifts, 0),
        COALESCE(ba.bids_placed, 0),
        COALESCE(ba.winners, 0),
        ROUND(CASE WHEN COALESCE(ba.open_shifts,0) = 0 THEN 0
                   ELSE ba.winners::numeric / ba.open_shifts * 100 END, 2),
        COALESCE(sa.initiated, 0),
        COALESCE(sa.completed, 0),
        COALESCE(sa.rejected, 0),
        COALESCE(sa.cancelled, 0),
        ROUND(CASE WHEN COALESCE(sa.initiated,0) = 0 THEN 0
                   ELSE sa.completed::numeric / sa.initiated * 100 END, 2)
    FROM buckets bk
    LEFT JOIN bid_agg  ba ON ba.b = bk.b
    LEFT JOIN swap_agg sa ON sa.b = bk.b
    ORDER BY bk.b;
END;
$$;


ALTER FUNCTION "public"."get_kpi_marketplace_trend"("p_from" "date", "p_to" "date", "p_grain" "text", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_manager_scorecard"("p_from" "date", "p_to" "date", "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_subdept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("managed_published_shifts" integer, "filled_shifts" integer, "fill_rate" numeric, "open_shifts" integer, "covered_open_shifts" integer, "open_coverage_rate" numeric, "published_snapshots" integer, "distinct_shifts" integer, "churn_rate" numeric, "emergency_fill_count" integer, "emergency_fill_rate" numeric, "reassignment_count" integer, "avg_publish_lead_time_hours" numeric, "manager_actions" integer, "employee_actions" integer, "system_actions" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN QUERY
    WITH
    -- ── Scoped published shift universe ───────────────────────────────
    -- Every shift-grain metric (fill, coverage, publish lead time) is
    -- anchored here. Window: shift_date in [p_from, p_to]; org/dept/subdept
    -- ANDed. "Published" = lifecycle_status <> 'Draft' AND not soft-deleted.
    pub_shifts AS (
        SELECT
            s.id,
            s.assigned_employee_id,
            s.scheduled_start,
            s.published_at,
            s.bidding_open_at
        FROM shifts s
        WHERE s.deleted_at IS NULL
          AND s.lifecycle_status <> 'Draft'
          AND s.shift_date BETWEEN p_from AND p_to
          AND (p_org_ids     IS NULL OR s.organization_id   = ANY(p_org_ids))
          AND (p_dept_ids    IS NULL OR s.department_id     = ANY(p_dept_ids))
          AND (p_subdept_ids IS NULL OR s.sub_department_id = ANY(p_subdept_ids))
    ),

    -- ── Per-shift open flag ───────────────────────────────────────────
    -- A shift is "open" (entered the marketplace as an unfilled posting) if
    -- it had >=1 OFFERED event OR >=1 shift_bids row OR went on bidding
    -- (bidding_open_at IS NOT NULL). "Covered" = open AND currently filled.
    shift_flags AS (
        SELECT
            ps.id,
            ps.assigned_employee_id,
            ps.scheduled_start,
            ps.published_at,
            (
                EXISTS (
                    SELECT 1 FROM shift_events e
                    WHERE e.shift_id = ps.id AND e.event_type = 'OFFERED'
                )
                OR EXISTS (
                    SELECT 1 FROM shift_bids b WHERE b.shift_id = ps.id
                )
                OR ps.bidding_open_at IS NOT NULL
            ) AS is_open
        FROM pub_shifts ps
    ),

    -- ── Shift Fill Rate + Open Shift Coverage + Publish Lead Time ─────
    -- avg_publish_lead_time_hours: average over published shifts of
    -- (scheduled_start - published_at) in hours. Rows with NULL
    -- scheduled_start / NULL published_at or a NEGATIVE delta (published
    -- after the shift was due to start) are discarded via the FILTER so they
    -- don't pollute the average. LOW lead time = manager-negative.
    shift_metrics AS (
        SELECT
            COUNT(*)::int                                                AS managed_published_shifts,
            COUNT(*) FILTER (WHERE assigned_employee_id IS NOT NULL)::int
                                                                         AS filled_shifts,
            COUNT(*) FILTER (WHERE is_open)::int                         AS open_shifts,
            COUNT(*) FILTER (WHERE is_open AND assigned_employee_id IS NOT NULL)::int
                                                                         AS covered_open_shifts,
            AVG(
                EXTRACT(EPOCH FROM (scheduled_start - published_at)) / 3600.0
            ) FILTER (
                WHERE scheduled_start IS NOT NULL
                  AND published_at   IS NOT NULL
                  AND scheduled_start >= published_at
            )                                                            AS avg_publish_lead_time_hours
        FROM shift_flags
    ),

    -- ── Snapshot universe (Churn + Emergency Fill + Reassignment) ─────
    -- Snapshot-grain metrics are scoped by the snapshot's OWN denormalized
    -- org/dept/subdept + shift_date (NOT by joining shifts), per spec.
    -- One snapshot = one published-active assignment episode.
    snaps AS (
        SELECT
            asnp.shift_id,
            asnp.source,
            asnp.end_reason
        FROM assignment_snapshots asnp
        WHERE asnp.shift_date BETWEEN p_from AND p_to
          AND (p_org_ids     IS NULL OR asnp.organization_id   = ANY(p_org_ids))
          AND (p_dept_ids    IS NULL OR asnp.department_id     = ANY(p_dept_ids))
          AND (p_subdept_ids IS NULL OR asnp.sub_department_id = ANY(p_subdept_ids))
    ),

    snapshot_metrics AS (
        SELECT
            COUNT(*)::int                                                AS published_snapshots,
            COUNT(DISTINCT shift_id)::int                               AS distinct_shifts,
            COUNT(*) FILTER (WHERE source = 'emergency')::int           AS emergency_fill_count,
            COUNT(*) FILTER (WHERE end_reason = 'reassigned')::int      AS reassignment_count
        FROM snaps
    ),

    -- ── Action split over enriched shift_events (event-grain) ─────────
    -- Window each event by joining its shift (shift_date + org/dept/subdept
    -- scope). actor_role is the manager/employee/system attribution added by
    -- migration 20260626090000. Events whose actor_role is NULL/other fall
    -- into none of the three buckets (the three counts need not sum to the
    -- total event count). Soft-deleted shifts are excluded.
    action_metrics AS (
        SELECT
            COUNT(*) FILTER (WHERE e.actor_role = 'manager')::int        AS manager_actions,
            COUNT(*) FILTER (WHERE e.actor_role = 'employee')::int       AS employee_actions,
            COUNT(*) FILTER (WHERE e.actor_role = 'system')::int         AS system_actions
        FROM shift_events e
        JOIN shifts s ON s.id = e.shift_id
        WHERE s.deleted_at IS NULL
          AND s.lifecycle_status <> 'Draft'
          AND s.shift_date BETWEEN p_from AND p_to
          AND (p_org_ids     IS NULL OR s.organization_id   = ANY(p_org_ids))
          AND (p_dept_ids    IS NULL OR s.department_id     = ANY(p_dept_ids))
          AND (p_subdept_ids IS NULL OR s.sub_department_id = ANY(p_subdept_ids))
    )

    -- ── Single-row assembly with guarded divides + ROUND(...,2) ───────
    SELECT
        -- Shift Fill Rate
        sm.managed_published_shifts,
        sm.filled_shifts,
        CASE WHEN sm.managed_published_shifts = 0 THEN 0
             ELSE ROUND(sm.filled_shifts::numeric / sm.managed_published_shifts * 100, 2) END
                                                                         AS fill_rate,
        -- Open Shift Coverage Rate
        sm.open_shifts,
        sm.covered_open_shifts,
        CASE WHEN sm.open_shifts = 0 THEN 0
             ELSE ROUND(sm.covered_open_shifts::numeric / sm.open_shifts * 100, 2) END
                                                                         AS open_coverage_rate,
        -- Assignment Churn Rate, as a PERCENTAGE: extra owners per 100 shifts
        -- = (snapshots - distinct shifts) / distinct shifts * 100. (Can exceed
        -- 100 if shifts average >2 owners.)
        spm.published_snapshots,
        spm.distinct_shifts,
        CASE WHEN spm.distinct_shifts = 0 THEN 0
             ELSE ROUND(
                 (spm.published_snapshots - spm.distinct_shifts)::numeric
                 / spm.distinct_shifts * 100, 2) END                    AS churn_rate,
        -- Emergency Fill: count + rate over all snapshots in scope. HIGH rate =
        -- poor planning / short lead time (manager-negative).
        spm.emergency_fill_count,
        CASE WHEN spm.published_snapshots = 0 THEN 0
             ELSE ROUND(spm.emergency_fill_count::numeric
                        / spm.published_snapshots * 100, 2) END          AS emergency_fill_rate,
        -- Reassignment volume (snapshots ended by a manager reassignment)
        spm.reassignment_count,
        -- Average publish lead time (hours); NULL -> 0 when no resolvable shifts
        ROUND(COALESCE(sm.avg_publish_lead_time_hours, 0), 2)            AS avg_publish_lead_time_hours,
        -- Action split (event-grain, by actor_role)
        am.manager_actions,
        am.employee_actions,
        am.system_actions
    FROM shift_metrics     sm
    CROSS JOIN snapshot_metrics spm
    CROSS JOIN action_metrics   am;
END;
$$;


ALTER FUNCTION "public"."get_manager_scorecard"("p_from" "date", "p_to" "date", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_manager_scorecard"("p_from" "date", "p_to" "date", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) IS 'Single-row manager / roster-quality scorecard (fill / open-coverage / assignment-churn / emergency-fill / reassignment / publish-lead-time / manager-employee-system action split) for a [p_from,p_to] shift_date window, optionally scoped by org/dept/subdept arrays (NULL = no filter). Shift-grain metrics scope via shifts; churn/emergency/reassignment are snapshot-grain over assignment_snapshots; the action split is event-grain over shift_events.actor_role joined to shifts. emergency_fill_rate and a LOW avg_publish_lead_time_hours are manager-NEGATIVE (worse planning). SECURITY DEFINER / STABLE.';



CREATE OR REPLACE FUNCTION "public"."get_marketplace_kpis"("p_from" "date", "p_to" "date", "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_subdept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("published_shifts" integer, "filled_shifts" integer, "fill_rate" numeric, "open_shifts" integer, "covered_open_shifts" integer, "open_coverage_rate" numeric, "published_snapshots" integer, "distinct_filled_shifts" integer, "churn_rate" numeric, "avg_time_to_fill_hours" numeric, "marketplace_eligible_shifts" integer, "marketplace_used_shifts" integer, "marketplace_utilization_rate" numeric, "offers_resolved" integer, "offer_accept_rate" numeric, "offer_reject_rate" numeric, "offer_ignore_rate" numeric, "trades_initiated" integer, "trade_completion_rate" numeric, "trade_rejection_rate" numeric, "trade_cancellation_rate" numeric, "trade_expiry_rate" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN QUERY
    WITH
    -- ── Scoped published shift universe ───────────────────────────────
    -- Every shift-grain metric (fill, coverage, marketplace utilization,
    -- and the per-shift inputs to time-to-fill) is anchored here.
    -- Window: shift_date in [p_from, p_to]; org/dept/subdept ANDed.
    -- "Published" = lifecycle_status <> 'Draft' AND not soft-deleted.
    pub_shifts AS (
        SELECT
            s.id,
            s.assigned_employee_id,
            s.scheduled_start,
            s.shift_date,
            s.bidding_open_at,
            s.published_at,
            s.created_at,
            s.organization_id,
            s.department_id,
            s.sub_department_id
        FROM shifts s
        WHERE s.deleted_at IS NULL
          -- "published" = EVER published (published_at is set on first publish and
          -- survives a revert-to-Draft from offer-expiry / bidding-expiry). Using
          -- lifecycle_status <> 'Draft' would wrongly DROP shifts that were published,
          -- failed to fill, and reverted (e.g. a bidding shift that expired unfilled),
          -- inflating the fill rate. published_at IS NOT NULL keeps them in scope.
          AND s.published_at IS NOT NULL
          AND s.shift_date BETWEEN p_from AND p_to
          AND (p_org_ids     IS NULL OR s.organization_id   = ANY(p_org_ids))
          AND (p_dept_ids    IS NULL OR s.department_id     = ANY(p_dept_ids))
          AND (p_subdept_ids IS NULL OR s.sub_department_id = ANY(p_subdept_ids))
    ),

    -- ── Per-shift marketplace touch flags ─────────────────────────────
    -- A shift "used the marketplace" if it had >=1 OFFERED event OR >=1
    -- shift_bids row OR >=1 shift_swaps row. A shift is "open" (entered the
    -- marketplace as an unfilled posting) if it had >=1 OFFERED event OR
    -- >=1 shift_bids row OR went on bidding (bidding_open_at IS NOT NULL).
    -- Trades alone do NOT make a shift "open" (a trade is a hand-off of an
    -- already-filled shift), but DO count toward marketplace utilization.
    shift_flags AS (
        SELECT
            ps.id,
            ps.assigned_employee_id,
            -- had an OFFERED event in the ledger
            EXISTS (
                SELECT 1 FROM shift_events e
                WHERE e.shift_id = ps.id AND e.event_type = 'OFFERED'
            ) AS had_offer,
            -- had at least one bid (any status)
            EXISTS (
                SELECT 1 FROM shift_bids b WHERE b.shift_id = ps.id
            ) AS had_bid,
            -- had at least one swap initiated against it as the requester's shift
            EXISTS (
                SELECT 1 FROM shift_swaps sw WHERE sw.requester_shift_id = ps.id
            ) AS had_swap,
            -- ever went on bidding (column set when a shift is posted to bidding)
            (ps.bidding_open_at IS NOT NULL) AS went_on_bidding
        FROM pub_shifts ps
    ),

    -- ── Shift Fill Rate + Open Shift Coverage Rate + Marketplace Util ──
    shift_metrics AS (
        SELECT
            COUNT(*)::int                                              AS published_shifts,
            COUNT(*) FILTER (WHERE assigned_employee_id IS NOT NULL)::int
                                                                       AS filled_shifts,
            -- open = entered marketplace as a posting
            COUNT(*) FILTER (WHERE had_offer OR had_bid OR went_on_bidding)::int
                                                                       AS open_shifts,
            -- covered = open AND currently filled
            COUNT(*) FILTER (
                WHERE (had_offer OR had_bid OR went_on_bidding)
                  AND assigned_employee_id IS NOT NULL
            )::int                                                     AS covered_open_shifts,
            -- marketplace-eligible = all published shifts in scope
            COUNT(*)::int                                              AS marketplace_eligible_shifts,
            -- marketplace-used = touched offer / bid / swap
            COUNT(*) FILTER (WHERE had_offer OR had_bid OR had_swap)::int
                                                                       AS marketplace_used_shifts
        FROM shift_flags
    ),

    -- ── Snapshot universe (Assignment Churn + Average Time To Fill) ───
    -- Snapshot-grain metrics are scoped by the snapshot's OWN denormalized
    -- org/dept/subdept + shift_date (NOT by joining shifts), per spec.
    -- One snapshot = one published-active assignment episode.
    snaps AS (
        SELECT
            asnp.shift_id,
            asnp.became_active_at,
            asnp.scheduled_start
        FROM assignment_snapshots asnp
        WHERE asnp.shift_date BETWEEN p_from AND p_to
          AND (p_org_ids     IS NULL OR asnp.organization_id   = ANY(p_org_ids))
          AND (p_dept_ids    IS NULL OR asnp.department_id     = ANY(p_dept_ids))
          AND (p_subdept_ids IS NULL OR asnp.sub_department_id = ANY(p_subdept_ids))
    ),

    -- Per-snapshot time-to-fill: hours from the marketplace-open moment to the
    -- moment the assignment became active.
    --   open_started_at := the latest shift_events.event_time STRICTLY BEFORE
    --                      became_active_at among OFFERED events for that shift
    --                      (the most recent preceding "posted/offered" signal).
    --   Fallbacks (when no preceding OFFERED event exists): the shift's
    --   bidding_open_at, then published_at, then created_at. All read from the
    --   `shifts` row (no org/dept scope needed — we already have the snapshot).
    -- Negative / NULL deltas are discarded (NULLIF guard) so a snapshot whose
    -- open moment can't be established does not pollute the average.
    ttf AS (
        SELECT
            sn.shift_id,
            sn.became_active_at,
            COALESCE(
                (
                    SELECT MAX(e.event_time)
                    FROM shift_events e
                    WHERE e.shift_id   = sn.shift_id
                      AND e.event_type = 'OFFERED'
                      AND e.event_time < sn.became_active_at
                ),
                sh.bidding_open_at,
                sh.published_at,
                sh.created_at
            ) AS open_started_at
        FROM snaps sn
        LEFT JOIN shifts sh ON sh.id = sn.shift_id
    ),

    snapshot_metrics AS (
        SELECT
            COUNT(*)::int                          AS published_snapshots,
            COUNT(DISTINCT shift_id)::int          AS distinct_filled_shifts
        FROM snaps
    ),

    ttf_metrics AS (
        SELECT
            -- average over snapshots with a resolvable, non-negative open->active gap
            AVG(
                EXTRACT(EPOCH FROM (became_active_at - open_started_at)) / 3600.0
            ) FILTER (
                WHERE open_started_at IS NOT NULL
                  AND became_active_at IS NOT NULL
                  AND became_active_at >= open_started_at
            ) AS avg_time_to_fill_hours
        FROM ttf
    ),

    -- ── Offer funnel over RESOLVED offers (event-sourced) ─────────────
    -- Resolved = ACCEPTED + REJECTED + IGNORED (an OFFERED with no terminal
    -- event is still pending and is excluded). Scoped by joining shifts for
    -- the window + org/dept/subdept. The three rates sum to 100.
    -- ── Offer funnel — EPISODE-sourced (an offer = an S3 OFFERED in an episode) ──
    -- IMPORTANT: a raw ACCEPTED event is emitted for offer-accepts AND for bid-wins
    -- (select_winner sets assignment_outcome='confirmed') AND for trade-confirms.
    -- Counting raw ACCEPTED events therefore OVER-counts the acceptance rate. The
    -- offer funnel must count only episodes that carried a real S3 offer (had_offer):
    --   accepted = had_offer AND had_accept       (the offer was accepted — even if
    --                                               later dropped/swapped; that's a
    --                                               separate cancellation event)
    --   ignored  = had_offer AND not accepted AND terminal_outcome='ignored'
    --   rejected = had_offer AND not accepted AND terminal_outcome NOT IN ('ignored','open')
    --   resolved = accepted + rejected + ignored  (a still-outstanding offer with
    --              terminal_outcome='open' is pending and excluded)
    offer_metrics AS (
        SELECT
            COUNT(*) FILTER (WHERE ep.had_offer AND ep.had_accept)::int AS accepted,
            COUNT(*) FILTER (WHERE ep.had_offer AND NOT ep.had_accept
                                   AND ep.terminal_outcome NOT IN ('ignored','open'))::int AS rejected,
            COUNT(*) FILTER (WHERE ep.had_offer AND NOT ep.had_accept
                                   AND ep.terminal_outcome = 'ignored')::int AS ignored,
            COUNT(*) FILTER (WHERE ep.had_offer
                                   AND (ep.had_accept OR ep.terminal_outcome <> 'open'))::int AS resolved
        FROM v_shift_assignment_episodes ep
        WHERE ep.shift_date BETWEEN p_from AND p_to
          AND ep.terminal_outcome <> 'shift_deleted'
          AND (p_org_ids     IS NULL OR ep.organization_id   = ANY(p_org_ids))
          AND (p_dept_ids    IS NULL OR ep.department_id     = ANY(p_dept_ids))
          AND (p_subdept_ids IS NULL OR ep.sub_department_id = ANY(p_subdept_ids))
    ),

    -- ── Trade funnel over shift_swaps in window ───────────────────────
    -- Scoped by joining the requester's shift (requester_shift_id) for the
    -- window + org/dept/subdept. Bucket mapping over swap_request_status:
    --   completed   := APPROVED    (the trade went through)
    --   rejected    := REJECTED    (the manager rejected the trade)
    --   cancelled   := CANCELLED   (the requester withdrew the trade)
    --   expired     := EXPIRED
    --   (OPEN / OFFER_SELECTED / MANAGER_PENDING are still in-flight: counted
    --    in the denominator `total` but in none of the four terminal buckets,
    --    so the four rates need not sum to 100.)
    trade_metrics AS (
        SELECT
            COUNT(*)::int                                                  AS total,
            COUNT(*) FILTER (WHERE ss.status = 'APPROVED')::int            AS completed,
            COUNT(*) FILTER (WHERE ss.status = 'REJECTED')::int            AS rejected,
            COUNT(*) FILTER (WHERE ss.status = 'CANCELLED')::int           AS cancelled,
            COUNT(*) FILTER (WHERE ss.status = 'EXPIRED')::int             AS expired
        FROM shift_swaps ss
        JOIN shifts s ON s.id = ss.requester_shift_id
        WHERE s.deleted_at IS NULL
          AND s.shift_date BETWEEN p_from AND p_to
          AND (p_org_ids     IS NULL OR s.organization_id   = ANY(p_org_ids))
          AND (p_dept_ids    IS NULL OR s.department_id     = ANY(p_dept_ids))
          AND (p_subdept_ids IS NULL OR s.sub_department_id = ANY(p_subdept_ids))
    )

    -- ── Single-row assembly with guarded divides + ROUND(...,2) ───────
    SELECT
        -- Fill Rate
        sm.published_shifts,
        sm.filled_shifts,
        CASE WHEN sm.published_shifts = 0 THEN 0
             ELSE ROUND(sm.filled_shifts::numeric / sm.published_shifts * 100, 2) END
                                                                       AS fill_rate,
        -- Open Shift Coverage Rate
        sm.open_shifts,
        sm.covered_open_shifts,
        CASE WHEN sm.open_shifts = 0 THEN 0
             ELSE ROUND(sm.covered_open_shifts::numeric / sm.open_shifts * 100, 2) END
                                                                       AS open_coverage_rate,
        -- Assignment Churn Rate, as a PERCENTAGE: extra owners per 100 published
        -- shifts = (snapshots - distinct shifts) / distinct shifts * 100. (Expressed
        -- as a % so it aligns with the UI formatting + thresholds; can exceed 100 if
        -- shifts average >2 owners.)
        spm.published_snapshots,
        spm.distinct_filled_shifts,
        CASE WHEN spm.distinct_filled_shifts = 0 THEN 0
             ELSE ROUND(
                 (spm.published_snapshots - spm.distinct_filled_shifts)::numeric
                 / spm.distinct_filled_shifts * 100, 2) END           AS churn_rate,
        -- Average Time To Fill (hours); NULL -> 0 when no resolvable snapshots
        ROUND(COALESCE(tm.avg_time_to_fill_hours, 0), 2)              AS avg_time_to_fill_hours,
        -- Marketplace Utilization Rate
        sm.marketplace_eligible_shifts,
        sm.marketplace_used_shifts,
        CASE WHEN sm.marketplace_eligible_shifts = 0 THEN 0
             ELSE ROUND(sm.marketplace_used_shifts::numeric
                        / sm.marketplace_eligible_shifts * 100, 2) END AS marketplace_utilization_rate,
        -- Offer funnel (resolved)
        om.resolved                                                   AS offers_resolved,
        CASE WHEN om.resolved = 0 THEN 0
             ELSE ROUND(om.accepted::numeric / om.resolved * 100, 2) END AS offer_accept_rate,
        CASE WHEN om.resolved = 0 THEN 0
             ELSE ROUND(om.rejected::numeric / om.resolved * 100, 2) END AS offer_reject_rate,
        CASE WHEN om.resolved = 0 THEN 0
             ELSE ROUND(om.ignored::numeric  / om.resolved * 100, 2) END AS offer_ignore_rate,
        -- Trade funnel
        trm.total                                                     AS trades_initiated,
        CASE WHEN trm.total = 0 THEN 0
             ELSE ROUND(trm.completed::numeric / trm.total * 100, 2) END AS trade_completion_rate,
        CASE WHEN trm.total = 0 THEN 0
             ELSE ROUND(trm.rejected::numeric / trm.total * 100, 2) END AS trade_rejection_rate,
        CASE WHEN trm.total = 0 THEN 0
             ELSE ROUND(trm.cancelled::numeric / trm.total * 100, 2) END AS trade_cancellation_rate,
        CASE WHEN trm.total = 0 THEN 0
             ELSE ROUND(trm.expired::numeric / trm.total * 100, 2) END AS trade_expiry_rate
    FROM shift_metrics    sm
    CROSS JOIN snapshot_metrics spm
    CROSS JOIN ttf_metrics      tm
    CROSS JOIN offer_metrics    om
    CROSS JOIN trade_metrics    trm;
END;
$$;


ALTER FUNCTION "public"."get_marketplace_kpis"("p_from" "date", "p_to" "date", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_marketplace_kpis"("p_from" "date", "p_to" "date", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) IS 'Single-row marketplace KPIs (fill / open-coverage / churn / time-to-fill / utilization / offer funnel / trade funnel) for a [p_from,p_to] shift_date window, optionally scoped by org/dept/subdept arrays (NULL = no filter). Offer behaviour is event-sourced from shift_events; churn & time-to-fill are snapshot-grain over assignment_snapshots; trades over shift_swaps (APPROVED=completed, REJECTED=rejected [manager rejected], CANCELLED=cancelled [requester withdrew], EXPIRED=expired). SECURITY DEFINER / STABLE.';



CREATE OR REPLACE FUNCTION "public"."get_metric_detailed_analysis"("p_metric_id" "text", "p_start_date" "date", "p_end_date" "date", "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
    v_current_val text;
    v_target_val text;
    v_trend text;
    v_summary text;
    v_details text;
    v_chart_data jsonb;
    v_recs text[];
    v_title text;
    v_chart_type text := 'line';
BEGIN
    v_recs := ARRAY['Review staff availability patterns', 'Analyze demand variance by day-of-week', 'Consider automated notifications for schedule changes'];

    IF p_metric_id = 'shift-fill-rate' THEN
        v_title := 'Shift Fill Rate Analysis';
        WITH daily AS (
            SELECT shift_date as d, COUNT(*) as t, COUNT(*) FILTER (WHERE assigned_employee_id IS NOT NULL) as f
            FROM shifts WHERE shift_date BETWEEN p_start_date AND p_end_date AND lifecycle_status != 'Draft'
            AND (p_org_ids IS NULL OR organization_id = ANY(p_org_ids)) AND (p_dept_ids IS NULL OR department_id = ANY(p_dept_ids))
            GROUP BY 1 ORDER BY 1
        )
        SELECT jsonb_agg(jsonb_build_object('label', d, 'value', ROUND(f::numeric/NULLIF(t,0)*100,1))) INTO v_chart_data FROM daily;

        SELECT ROUND(COUNT(*) FILTER (WHERE assigned_employee_id IS NOT NULL)::numeric/NULLIF(COUNT(*),0)*100,1)::text INTO v_current_val
        FROM shifts WHERE shift_date BETWEEN p_start_date AND p_end_date AND lifecycle_status != 'Draft'
        AND (p_org_ids IS NULL OR organization_id = ANY(p_org_ids)) AND (p_dept_ids IS NULL OR department_id = ANY(p_dept_ids));
        
        v_target_val := '95%';
        v_summary := 'Current fill rate is ' || COALESCE(v_current_val, '0') || '% across the selected period.';
        v_details := 'Shift fill rate tracks the percentage of published shifts that have an assigned employee. Falling below 90% typically indicates a recruitment need or a mismatch between staff availability and roster demand.';

    ELSIF p_metric_id = 'labour-cost-per-event' OR p_metric_id = 'estimated-cost' THEN
        v_title := 'Labour Cost Analysis';
        WITH daily AS (
            SELECT shift_date as d, COALESCE(SUM(public.fn_eba_shift_cost(s)),0) as c
            FROM shifts s WHERE s.shift_date BETWEEN p_start_date AND p_end_date AND s.assigned_employee_id IS NOT NULL
            AND (p_org_ids IS NULL OR organization_id = ANY(p_org_ids)) AND (p_dept_ids IS NULL OR department_id = ANY(p_dept_ids))
            GROUP BY 1 ORDER BY 1
        )
        SELECT jsonb_agg(jsonb_build_object('label', d, 'value', ROUND(c, 2))) INTO v_chart_data FROM daily;

        SELECT ROUND(SUM(public.fn_eba_shift_cost(s)),0)::text INTO v_current_val
        FROM shifts s WHERE s.shift_date BETWEEN p_start_date AND p_end_date AND s.assigned_employee_id IS NOT NULL
        AND (p_org_ids IS NULL OR organization_id = ANY(p_org_ids)) AND (p_dept_ids IS NULL OR department_id = ANY(p_dept_ids));

        v_target_val := 'Budgeted';
        v_summary := 'Total estimated labour cost for this period is $' || COALESCE(v_current_val, '0') || '.';
        v_details := 'This represents the gross labour expenditure based on rostered hours and remuneration rates. It does not include payroll taxes or secondary benefits.';

    ELSIF p_metric_id = 'no-show-rate' THEN
        v_title := 'No-Show Rate Analysis';
        WITH daily AS (
            SELECT shift_date as d, COUNT(*) FILTER (WHERE assigned_employee_id IS NOT NULL) as a, 
                   COUNT(*) FILTER (WHERE attendance_status = 'no_show' OR assignment_outcome = 'no_show') as n
            FROM shifts WHERE shift_date BETWEEN p_start_date AND p_end_date
            AND (p_org_ids IS NULL OR organization_id = ANY(p_org_ids)) AND (p_dept_ids IS NULL OR department_id = ANY(p_dept_ids))
            GROUP BY 1 ORDER BY 1
        )
        SELECT jsonb_agg(jsonb_build_object('label', d, 'value', ROUND(n::numeric/NULLIF(a,0)*100,1))) INTO v_chart_data FROM daily;

        SELECT ROUND(COUNT(*) FILTER (WHERE attendance_status = 'no_show' OR assignment_outcome = 'no_show')::numeric/NULLIF(COUNT(*) FILTER (WHERE assigned_employee_id IS NOT NULL),0)*100,1)::text INTO v_current_val
        FROM shifts WHERE shift_date BETWEEN p_start_date AND p_end_date AND assigned_employee_id IS NOT NULL
        AND (p_org_ids IS NULL OR organization_id = ANY(p_org_ids)) AND (p_dept_ids IS NULL OR department_id = ANY(p_dept_ids));

        v_target_val := '<2%';
        v_summary := 'The average no-show rate is ' || COALESCE(v_current_val, '0') || '%.';
        v_details := 'A high no-show rate is a critical indicator of poor employee engagement or scheduling conflicts. Investigate specific departments or roles with recurring issues.';

    ELSIF p_metric_id = 'attendance-compliance-rate' THEN
        v_title := 'Attendance Compliance Analysis';
        WITH daily AS (
            SELECT s.shift_date AS d,
                   COUNT(*) FILTER (WHERE s.end_reason = 'worked') AS w,
                   COUNT(*) FILTER (WHERE s.end_reason = 'worked' AND NOT s.late_in AND NOT s.early_out) AS ok
            FROM assignment_snapshots s
            WHERE s.shift_date BETWEEN p_start_date AND p_end_date
              AND (p_org_ids IS NULL OR s.organization_id = ANY(p_org_ids))
              AND (p_dept_ids IS NULL OR s.department_id = ANY(p_dept_ids))
            GROUP BY 1 ORDER BY 1
        )
        SELECT jsonb_agg(jsonb_build_object('label', d, 'value', ROUND(ok::numeric/NULLIF(w,0)*100,1))) INTO v_chart_data FROM daily;
        SELECT ROUND(COUNT(*) FILTER (WHERE s.end_reason = 'worked' AND NOT s.late_in AND NOT s.early_out)::numeric
                     / NULLIF(COUNT(*) FILTER (WHERE s.end_reason = 'worked'),0) * 100, 1)::text
        INTO v_current_val
        FROM assignment_snapshots s
        WHERE s.shift_date BETWEEN p_start_date AND p_end_date
          AND (p_org_ids IS NULL OR s.organization_id = ANY(p_org_ids))
          AND (p_dept_ids IS NULL OR s.department_id = ANY(p_dept_ids));
        v_target_val := '95%';
        v_summary := 'Attendance compliance is ' || COALESCE(v_current_val, '0') || '% across the selected period.';
        v_details := 'Counts shifts that were worked AND clocked in on time AND clocked out on time, over shifts worked. The grace window is 7.5 minutes either side of schedule.';
        v_recs := ARRAY['Check whether late starts cluster on particular shift times', 'Review sites with repeated missing clock-outs', 'Confirm rosters give enough travel time between venues'];

    ELSIF p_metric_id = 'cancellation-rate' THEN
        v_title := 'Cancellation Analysis';
        WITH weekly AS (
            SELECT date_trunc('week', s.shift_date::timestamp)::date AS d,
                   COUNT(*) AS held,
                   COUNT(*) FILTER (WHERE s.end_reason IN ('dropped_std','dropped_late')) AS c
            FROM assignment_snapshots s
            WHERE s.shift_date BETWEEN p_start_date AND p_end_date
              AND (p_org_ids IS NULL OR s.organization_id = ANY(p_org_ids))
              AND (p_dept_ids IS NULL OR s.department_id = ANY(p_dept_ids))
            GROUP BY 1 ORDER BY 1
        )
        SELECT jsonb_agg(jsonb_build_object('label', d, 'value', ROUND(c::numeric/NULLIF(held,0)*100,1))) INTO v_chart_data FROM weekly;
        SELECT ROUND(COUNT(*) FILTER (WHERE s.end_reason IN ('dropped_std','dropped_late'))::numeric
                     / NULLIF(COUNT(*),0) * 100, 1)::text
        INTO v_current_val
        FROM assignment_snapshots s
        WHERE s.shift_date BETWEEN p_start_date AND p_end_date
          AND (p_org_ids IS NULL OR s.organization_id = ANY(p_org_ids))
          AND (p_dept_ids IS NULL OR s.department_id = ANY(p_dept_ids));
        v_target_val := '5%';
        v_summary := 'Cancellation rate is ' || COALESCE(v_current_val, '0') || '% of shifts held.';
        v_details := 'Shifts released by the person holding them, over all shifts held. Two kinds, split at 24 hours notice: standard above, critical at or below. 4 hours is a different line entirely - the urgent/emergent boundary, where exchange operations are blocked.';
        v_recs := ARRAY['Look at the reason distribution before the rate', 'Critical cancellations matter more than the total', 'Check whether one sub-department carries most of them'];
        v_chart_type := 'bar';

    ELSIF p_metric_id = 'open-shift-award-rate' THEN
        v_title := 'Open-Shift Award Analysis';
        WITH weekly AS (
            SELECT date_trunc('week', s.shift_date::timestamp)::date AS d,
                   COUNT(DISTINCT s.id) AS opened,
                   COUNT(DISTINCT sb.shift_id) FILTER (WHERE sb.status = 'accepted') AS won
            FROM shifts s
            LEFT JOIN shift_bids sb ON sb.shift_id = s.id
            WHERE s.shift_date BETWEEN p_start_date AND p_end_date
              AND s.deleted_at IS NULL
              AND s.bidding_status NOT IN ('not_on_bidding','bidding_closed_no_winner')
              AND (p_org_ids IS NULL OR s.organization_id = ANY(p_org_ids))
              AND (p_dept_ids IS NULL OR s.department_id = ANY(p_dept_ids))
            GROUP BY 1 ORDER BY 1
        )
        SELECT jsonb_agg(jsonb_build_object('label', d, 'value', ROUND(won::numeric/NULLIF(opened,0)*100,1))) INTO v_chart_data FROM weekly;
        SELECT ROUND(COUNT(DISTINCT sb.shift_id) FILTER (WHERE sb.status = 'accepted')::numeric
                     / NULLIF(COUNT(DISTINCT s.id),0) * 100, 1)::text
        INTO v_current_val
        FROM shifts s
        LEFT JOIN shift_bids sb ON sb.shift_id = s.id
        WHERE s.shift_date BETWEEN p_start_date AND p_end_date
          AND s.deleted_at IS NULL
          AND s.bidding_status NOT IN ('not_on_bidding','bidding_closed_no_winner')
          AND (p_org_ids IS NULL OR s.organization_id = ANY(p_org_ids))
          AND (p_dept_ids IS NULL OR s.department_id = ANY(p_dept_ids));
        v_target_val := '80%';
        v_summary := 'Open-shift award rate is ' || COALESCE(v_current_val, '0') || '% across the selected period.';
        v_details := 'Open bidding shifts that ended with a winner selected. Distinct from bid win rate, which is winners over ALL bids placed and falls as competition per shift rises.';
        v_recs := ARRAY['Check shifts that expired without a single bid first', 'Compare bids per shift against award rate', 'Review whether urgent shifts are opening late'];
        v_chart_type := 'bar';

    ELSIF p_metric_id = 'swap-completion-rate' THEN
        v_title := 'Swap Completion Analysis';
        WITH weekly AS (
            SELECT date_trunc('week', s.shift_date::timestamp)::date AS d,
                   COUNT(sr.id) AS started,
                   COUNT(*) FILTER (WHERE sr.status = 'approved') AS done
            FROM shifts s
            JOIN swap_requests sr ON sr.original_shift_id = s.id
            WHERE s.shift_date BETWEEN p_start_date AND p_end_date
              AND s.deleted_at IS NULL
              AND (p_org_ids IS NULL OR s.organization_id = ANY(p_org_ids))
              AND (p_dept_ids IS NULL OR s.department_id = ANY(p_dept_ids))
            GROUP BY 1 ORDER BY 1
        )
        SELECT jsonb_agg(jsonb_build_object('label', d, 'value', ROUND(done::numeric/NULLIF(started,0)*100,1))) INTO v_chart_data FROM weekly;
        SELECT ROUND(COUNT(*) FILTER (WHERE sr.status = 'approved')::numeric / NULLIF(COUNT(sr.id),0) * 100, 1)::text
        INTO v_current_val
        FROM shifts s
        JOIN swap_requests sr ON sr.original_shift_id = s.id
        WHERE s.shift_date BETWEEN p_start_date AND p_end_date
          AND s.deleted_at IS NULL
          AND (p_org_ids IS NULL OR s.organization_id = ANY(p_org_ids))
          AND (p_dept_ids IS NULL OR s.department_id = ANY(p_dept_ids));
        v_target_val := '75%';
        v_summary := 'Swap completion rate is ' || COALESCE(v_current_val, '0') || '% of swaps initiated.';
        v_details := 'Swaps that reached an approved completion, over swaps initiated. The shortfall splits into manager rejections, requester withdrawals and expiries, each pointing at a different fix.';
        v_recs := ARRAY['Find which stage the pipeline leaks at before acting', 'Expiries suggest nobody saw the request', 'Manager rejections suggest a compliance or cost block'];
        v_chart_type := 'bar';

    ELSE
        -- FALLBACK
        v_title := initcap(replace(p_metric_id, '-', ' '));
        v_current_val := '—';
        v_target_val := '—';
        v_summary := 'Detailed analysis for ' || v_title || ' is pending full database migration.';
        v_details := 'We are currently mapping historical events to this metric. Please check back as more data points are indexed.';
        v_chart_data := '[]'::jsonb;
    END IF;

    v_trend := 'stable';

    RETURN json_build_object(
        'title', v_title,
        'summary', v_summary,
        'details', v_details,
        'metrics', jsonb_build_object(
            'current', COALESCE(v_current_val, '0'),
            'target', COALESCE(v_target_val, '—'),
            'trend', v_trend
        ),
        'chartData', COALESCE(v_chart_data, '[]'::jsonb),
        'chartType', v_chart_type,
        'recommendations', v_recs
    );
END;
$_$;


ALTER FUNCTION "public"."get_metric_detailed_analysis"("p_metric_id" "text", "p_start_date" "date", "p_end_date" "date", "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_department_ids"() RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RETURN (
    SELECT array_agg(DISTINCT department_id)
    FROM public.employee_assignments
    WHERE profile_id = auth.uid()
  );
END;
$$;


ALTER FUNCTION "public"."get_my_department_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_role"() RETURNS "public"."system_role"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RETURN (
    SELECT system_role 
    FROM public.profiles 
    WHERE id = auth.uid()
  );
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."get_my_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_roster_day"("p_organization_id" "uuid", "p_date" "date", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_roster_day_id UUID;
BEGIN
  -- Try to find existing
  SELECT id INTO v_roster_day_id
  FROM roster_days
  WHERE organization_id = p_organization_id 
    AND date = p_date;
  
  -- Create if not found
  IF v_roster_day_id IS NULL THEN
    INSERT INTO roster_days (
      organization_id, date, status, created_by, created_at, updated_at
    )
    VALUES (
      p_organization_id, p_date, 'draft', p_user_id, NOW(), NOW()
    )
    RETURNING id INTO v_roster_day_id;
  END IF;
  
  RETURN v_roster_day_id;
END;
$$;


ALTER FUNCTION "public"."get_or_create_roster_day"("p_organization_id" "uuid", "p_date" "date", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_performance_trends"("p_employee_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_interval" "text" DEFAULT 'day'::"text") RETURNS TABLE("period_start" "date", "reliability_score" numeric, "cancel_rate" numeric, "worked_count" integer)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN QUERY
    WITH daily_agg AS (
        SELECT
            (se.event_time AT TIME ZONE 'Australia/Sydney')::date as d,
            COUNT(*) FILTER (WHERE event_type = 'ASSIGNED') AS assigned,
            COUNT(*) FILTER (WHERE event_type = 'CANCELLED' OR event_type = 'LATE_CANCELLED') AS cancelled,
            COUNT(*) FILTER (WHERE event_type = 'LATE_CANCELLED') AS late_cancelled,
            COUNT(*) FILTER (WHERE event_type = 'NO_SHOW') AS no_show,
            COUNT(*) FILTER (WHERE event_type = 'CHECKED_IN') AS worked,
            COUNT(*) FILTER (WHERE event_type = 'LATE_IN') AS late_in
        FROM public.shift_events se
        WHERE se.employee_id = p_employee_id
          AND se.event_time BETWEEN p_start_date AND p_end_date
        GROUP BY d
    )
    SELECT
        d,
        GREATEST(0, LEAST(100, ROUND(
            100
            - (CASE WHEN assigned = 0 THEN 0 ELSE cancelled::numeric / assigned * 30 END)
            - (CASE WHEN assigned = 0 THEN 0 ELSE late_cancelled::numeric / assigned * 20 END)
            - (CASE WHEN assigned = 0 THEN 0 ELSE no_show::numeric / assigned * 40 END)
            - (CASE WHEN worked = 0 THEN 0 ELSE late_in::numeric / worked * 10 END)
        , 1))),
        ROUND(CASE WHEN assigned = 0 THEN 0 ELSE cancelled::numeric / assigned * 100 END, 1),
        worked::int
    FROM daily_agg
    ORDER BY d;
END;
$$;


ALTER FUNCTION "public"."get_performance_trends"("p_employee_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_interval" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_prospective_pay_terms"("p_shift_ids" "uuid"[], "p_employee_ids" "uuid"[]) RETURNS TABLE("shift_id" "uuid", "employee_id" "uuid", "pay_terms" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
    SELECT s.id, x.employee_id, public.shift_pay_terms_for(s, x.employee_id)
      FROM unnest(p_shift_ids, p_employee_ids) AS x(shift_id, employee_id)
      JOIN public.shifts s ON s.id = x.shift_id
     WHERE x.employee_id IS NOT NULL;
$$;


ALTER FUNCTION "public"."get_prospective_pay_terms"("p_shift_ids" "uuid"[], "p_employee_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_publish_target_state"("p_has_assignment" boolean, "p_is_confirmed" boolean, "p_hours_until_start" numeric) RETURNS TABLE("state_id" "text", "lifecycle_status" "public"."shift_lifecycle", "assignment_status" "public"."shift_assignment_status", "assignment_outcome" "public"."shift_assignment_outcome", "bidding_status" "public"."shift_bidding_status", "fulfillment_status" "public"."shift_fulfillment_status")
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF p_has_assignment THEN
        IF p_is_confirmed THEN
            RETURN QUERY SELECT
                'S4'::TEXT, 'Published'::shift_lifecycle, 'assigned'::shift_assignment_status,
                'confirmed'::shift_assignment_outcome, 'not_on_bidding'::shift_bidding_status,
                'fulfilled'::shift_fulfillment_status;
        ELSE
            RETURN QUERY SELECT
                'S3'::TEXT, 'Published'::shift_lifecycle, 'assigned'::shift_assignment_status,
                'offered'::shift_assignment_outcome, 'not_on_bidding'::shift_bidding_status,
                'pending'::shift_fulfillment_status;
        END IF;
    ELSE
        -- Unassigned -> Bidding (unified on_bidding; urgency derived from TTS at read time)
        RETURN QUERY SELECT
            'S5'::TEXT, 'Published'::shift_lifecycle, 'unassigned'::shift_assignment_status,
            NULL::shift_assignment_outcome, 'on_bidding'::shift_bidding_status,
            'none'::shift_fulfillment_status;
    END IF;
END;
$$;


ALTER FUNCTION "public"."get_publish_target_state"("p_has_assignment" boolean, "p_is_confirmed" boolean, "p_hours_until_start" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_quarterly_performance_report"("p_year" integer, "p_quarter" integer, "p_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_subdept_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("employee_id" "uuid", "employee_name" "text", "total_offers" integer, "accepted" integer, "rejected" integer, "expired" integer, "assigned" integer, "emergency_assigned" integer, "cancel_standard" integer, "cancel_late" integer, "swap_out" integer, "late_clock_in" integer, "early_clock_out" integer, "no_show" integer, "completed" integer, "acceptance_rate" numeric, "rejection_rate" numeric, "ignorance_rate" numeric, "cancel_rate" numeric, "late_cancel_rate" numeric, "swap_rate" numeric, "reliability_score" numeric, "late_clock_in_rate" numeric, "early_clock_out_rate" numeric, "no_show_rate" numeric, "drop_rate" numeric, "total_bids" integer, "bids_accepted" integer, "bid_success_rate" numeric, "assignment_changes" integer, "trade_requests" integer, "trade_completion_rate" numeric, "trade_cancellation_rate" numeric, "attendance_compliance_rate" numeric, "performance_score" numeric, "engagement_score" numeric, "standard_drop_rate" numeric, "urgent_drop_rate" numeric, "early_clock_in" integer, "late_clock_out" integer, "early_clock_in_rate" numeric, "late_clock_out_rate" numeric, "on_time_in" integer, "on_time_out" integer, "on_time_in_rate" numeric, "on_time_out_rate" numeric, "auto_clock_out" integer, "auto_clock_out_rate" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_start date;
    v_end   date;
    v_perm  jsonb;
    v_allowed_org_ids     uuid[];
    v_allowed_dept_ids    uuid[];
    v_allowed_subdept_ids uuid[];
    v_org_ids     uuid[];
    v_dept_ids    uuid[];
    v_subdept_ids uuid[];
BEGIN
    IF NOT public.is_manager_or_above() THEN
        RAISE EXCEPTION 'insufficient_privilege: managerial access required for performance reports';
    END IF;

    v_perm := public.resolve_user_permissions();

    SELECT COALESCE(array_agg(DISTINCT (org->>'id')::uuid), ARRAY[]::uuid[])
    INTO v_allowed_org_ids
    FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org;

    SELECT COALESCE(array_agg(DISTINCT (dept->>'id')::uuid), ARRAY[]::uuid[])
    INTO v_allowed_dept_ids
    FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org,
         jsonb_array_elements(COALESCE(org->'departments', '[]'::jsonb)) dept;

    SELECT COALESCE(array_agg(DISTINCT (sd->>'id')::uuid), ARRAY[]::uuid[])
    INTO v_allowed_subdept_ids
    FROM jsonb_array_elements(COALESCE(v_perm->'allowed_scope_tree'->'organizations', '[]'::jsonb)) org,
         jsonb_array_elements(COALESCE(org->'departments', '[]'::jsonb)) dept,
         jsonb_array_elements(COALESCE(dept->'subdepartments', '[]'::jsonb)) sd;

    IF array_length(v_allowed_org_ids, 1) IS NULL THEN
        -- Manager flag is set but no Type Y scope resolved (e.g. cert data
        -- inconsistency) — fail closed to zero rows rather than everyone.
        RETURN;
    END IF;

    v_org_ids := CASE WHEN p_org_ids IS NULL THEN v_allowed_org_ids
                      ELSE ARRAY(SELECT unnest(p_org_ids) INTERSECT SELECT unnest(v_allowed_org_ids)) END;
    v_dept_ids := CASE WHEN p_dept_ids IS NULL THEN v_allowed_dept_ids
                       ELSE ARRAY(SELECT unnest(p_dept_ids) INTERSECT SELECT unnest(v_allowed_dept_ids)) END;
    v_subdept_ids := CASE WHEN p_subdept_ids IS NULL THEN v_allowed_subdept_ids
                          ELSE ARRAY(SELECT unnest(p_subdept_ids) INTERSECT SELECT unnest(v_allowed_subdept_ids)) END;

    SELECT qdr.v_start, qdr.v_end INTO v_start, v_end
    FROM quarter_date_range(p_year, p_quarter) qdr;

    RETURN QUERY
    WITH
    -- Offer behaviour from episodes view
    offer_agg AS (
        SELECT
            ep.employee_id AS emp_id,
            COUNT(*) FILTER (WHERE ep.had_offer AND ep.terminal_outcome <> 'unassigned')::int                           AS total_offers_sent,
            COUNT(*) FILTER (WHERE ep.had_offer AND ep.had_accept AND ep.terminal_outcome <> 'unassigned')::int          AS total_accepted,
            COUNT(*) FILTER (WHERE ep.had_offer AND ep.terminal_outcome = 'rejected')::int AS total_rejected,
            COUNT(*) FILTER (WHERE ep.had_offer AND ep.terminal_outcome = 'ignored')::int  AS total_expired,
            COUNT(*) FILTER (WHERE ep.had_offer AND ep.had_accept AND ep.terminal_outcome IN ('cancelled_standard','cancelled_late','no_show'))::int AS dropped_count
        FROM v_shift_assignment_episodes ep
        WHERE ep.shift_date BETWEEN v_start AND v_end
          AND ep.terminal_outcome != 'shift_deleted'
          AND (array_length(v_org_ids,1)     IS NULL OR ep.organization_id    = ANY(v_org_ids))
          AND (array_length(v_dept_ids,1)    IS NULL OR ep.department_id     = ANY(v_dept_ids))
          AND (array_length(v_subdept_ids,1) IS NULL OR ep.sub_department_id = ANY(v_subdept_ids))
        GROUP BY ep.employee_id
    ),

    -- Assignment, Reliability, Attendance from assignment_snapshots
    snap_agg AS (
        SELECT
            snap.employee_id AS emp_id,
            COUNT(*) FILTER (WHERE snap.source != 'emergency')::int                  AS assigned_count,
            COUNT(*) FILTER (WHERE snap.source = 'emergency')::int                    AS emergency_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'worked')::int                   AS completed_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'dropped_std')::int              AS cancel_standard_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'dropped_late')::int             AS cancel_late_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'traded_out')::int               AS swap_out_count,
            COUNT(*) FILTER (WHERE snap.end_reason = 'no_show')::int                  AS no_show_count,
            COUNT(*) FILTER (WHERE snap.late_in AND snap.end_reason = 'worked')::int  AS late_clock_in_count,
            COUNT(*) FILTER (WHERE snap.early_out AND snap.end_reason = 'worked')::int AS early_clock_out_count,
            COUNT(*) FILTER (WHERE snap.early_in AND snap.end_reason = 'worked')::int  AS early_clock_in_count,
            COUNT(*) FILTER (WHERE snap.late_out AND snap.end_reason = 'worked')::int  AS late_clock_out_count,
            COUNT(*) FILTER (WHERE snap.on_time_in AND snap.end_reason = 'worked')::int AS on_time_in_count,
            COUNT(*) FILTER (WHERE snap.on_time_out AND snap.end_reason = 'worked')::int AS on_time_out_count,
            COUNT(*) FILTER (WHERE snap.auto_clock_out AND snap.end_reason = 'worked')::int AS auto_clock_out_count,
            COUNT(*)::int                                                             AS held_count,

            -- Assignment Changes: standard cancel, late cancel, no show, traded out, reassigned
            COUNT(*) FILTER (WHERE snap.end_reason IS NOT NULL AND snap.end_reason != 'worked')::int AS assignment_changes,
            -- Compliant count (for Attendance percentage): completed/worked AND neither late check-in nor early check-out
            COUNT(*) FILTER (WHERE snap.end_reason = 'worked' AND NOT snap.late_in AND NOT snap.early_out)::int AS compliant_count,

            -- Standard drops (TTS > 24 hours)
            COUNT(*) FILTER (WHERE snap.end_reason = 'dropped_std' AND (snap.scheduled_start - snap.ended_at) > interval '24 hours')::int AS standard_drop_count,
            -- Urgent drops (4 hours < TTS <= 24 hours)
            COUNT(*) FILTER (WHERE snap.end_reason = 'dropped_std' AND (snap.scheduled_start - snap.ended_at) <= interval '24 hours')::int AS urgent_drop_count
        FROM assignment_snapshots snap
        WHERE snap.shift_date BETWEEN v_start AND v_end
          AND (array_length(v_org_ids,1)     IS NULL OR snap.organization_id    = ANY(v_org_ids))
          AND (array_length(v_dept_ids,1)    IS NULL OR snap.department_id     = ANY(v_dept_ids))
          AND (array_length(v_subdept_ids,1) IS NULL OR snap.sub_department_id = ANY(v_subdept_ids))
        GROUP BY snap.employee_id
    ),

    -- Bidding metrics
    bid_agg AS (
        SELECT
            sb.employee_id AS emp_id,
            COUNT(*)::int                                       AS total_bids,
            COUNT(*) FILTER (WHERE sb.status = 'accepted')::int AS bids_accepted
        FROM shift_bids sb
        JOIN shifts s ON s.id = sb.shift_id
        WHERE s.shift_date BETWEEN v_start AND v_end
          AND (array_length(v_org_ids,1)     IS NULL OR s.organization_id    = ANY(v_org_ids))
          AND (array_length(v_dept_ids,1)    IS NULL OR s.department_id     = ANY(v_dept_ids))
          AND (array_length(v_subdept_ids,1) IS NULL OR s.sub_department_id = ANY(v_subdept_ids))
        GROUP BY sb.employee_id
    ),

    -- Trading metrics
    trade_agg AS (
        SELECT
            sr.requested_by_employee_id AS emp_id,
            COUNT(*)::int AS trade_requests,
            COUNT(*) FILTER (WHERE sr.status = 'approved')::int AS trades_approved,
            COUNT(*) FILTER (WHERE sr.status = 'cancelled')::int AS trades_cancelled
        FROM swap_requests sr
        JOIN shifts s ON s.id = sr.original_shift_id
        WHERE s.shift_date BETWEEN v_start AND v_end
          AND (array_length(v_org_ids,1)     IS NULL OR s.organization_id    = ANY(v_org_ids))
          AND (array_length(v_dept_ids,1)    IS NULL OR s.department_id     = ANY(v_dept_ids))
          AND (array_length(v_subdept_ids,1) IS NULL OR s.sub_department_id = ANY(v_subdept_ids))
        GROUP BY sr.requested_by_employee_id
    ),

    all_emps AS (
        SELECT emp_id FROM offer_agg
        UNION
        SELECT emp_id FROM snap_agg
        UNION
        SELECT emp_id FROM bid_agg
        UNION
        SELECT emp_id FROM trade_agg
    ),

    raw_metrics AS (
        SELECT
            ae.emp_id                                               AS employee_id,
            COALESCE(prof.full_name, ae.emp_id::text)::text        AS employee_name,
            COALESCE(oa.total_offers_sent,    0)::int              AS total_offers,
            COALESCE(oa.total_accepted,       0)::int              AS accepted,
            COALESCE(oa.total_rejected,       0)::int              AS rejected,
            COALESCE(oa.total_expired,        0)::int              AS expired,
            COALESCE(sa.assigned_count,       0)::int              AS assigned,
            COALESCE(sa.emergency_count,      0)::int              AS emergency_assigned,
            COALESCE(sa.cancel_standard_count,0)::int              AS cancel_standard,
            COALESCE(sa.cancel_late_count,    0)::int              AS cancel_late,
            COALESCE(sa.swap_out_count,       0)::int              AS swap_out,
            COALESCE(sa.late_clock_in_count,  0)::int              AS late_clock_in,
            COALESCE(sa.early_clock_out_count,0)::int              AS early_clock_out,
            COALESCE(sa.no_show_count,        0)::int              AS no_show,
            COALESCE(sa.completed_count,      0)::int              AS completed,

            -- Offer rates
            ROUND(CASE WHEN COALESCE(oa.total_offers_sent,0)=0 THEN 0
                  ELSE oa.total_accepted::numeric/oa.total_offers_sent*100 END,2)::numeric AS acceptance_rate,
            ROUND(CASE WHEN COALESCE(oa.total_offers_sent,0)=0 THEN 0
                  ELSE oa.total_rejected::numeric/oa.total_offers_sent*100 END,2)::numeric AS rejection_rate,
            ROUND(CASE WHEN COALESCE(oa.total_offers_sent,0)=0 THEN 0
                  ELSE oa.total_expired::numeric/oa.total_offers_sent*100 END,2)::numeric  AS ignorance_rate,

            -- Assignment/cancellation rates
            ROUND(CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                  ELSE COALESCE(sa.cancel_standard_count,0)::numeric/sa.held_count*100 END,2)::numeric AS cancel_rate,
            ROUND(CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                  ELSE COALESCE(sa.cancel_late_count,0)::numeric/sa.held_count*100 END,2)::numeric AS late_cancel_rate,
            ROUND(CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                  ELSE COALESCE(sa.swap_out_count,0)::numeric/sa.held_count*100 END,2)::numeric AS swap_rate,

            -- Reliability
            GREATEST(0,LEAST(100,ROUND(
                100
                -CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                      ELSE (COALESCE(sa.cancel_standard_count,0)+COALESCE(sa.cancel_late_count,0))::numeric/sa.held_count*30 END
                -CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                      ELSE COALESCE(sa.cancel_late_count,0)::numeric/sa.held_count*20 END
                -CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0 ELSE COALESCE(sa.no_show_count,0)::numeric/sa.held_count*40 END
                -CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                      ELSE COALESCE(sa.late_clock_in_count,0)::numeric/sa.completed_count*5 END
                -CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                      ELSE COALESCE(sa.early_clock_out_count,0)::numeric/sa.completed_count*5 END
            ,2)))::numeric AS reliability_score,

            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE COALESCE(sa.late_clock_in_count,0)::numeric/sa.completed_count*100 END,2)::numeric AS late_clock_in_rate,
            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE COALESCE(sa.early_clock_out_count,0)::numeric/sa.completed_count*100 END,2)::numeric AS early_clock_out_rate,
            ROUND(CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                  ELSE COALESCE(sa.no_show_count,0)::numeric/sa.held_count*100 END,2)::numeric AS no_show_rate,
            ROUND(CASE WHEN COALESCE(oa.total_accepted,0)=0 THEN 0
                  ELSE COALESCE(oa.dropped_count,0)::numeric/oa.total_accepted*100 END,2)::numeric AS drop_rate,

            COALESCE(ba.total_bids, 0)::int AS total_bids,
            COALESCE(ba.bids_accepted, 0)::int AS bids_accepted,
            ROUND(CASE WHEN COALESCE(ba.total_bids,0)=0 THEN 0
                  ELSE ba.bids_accepted::numeric/ba.total_bids*100 END, 2)::numeric AS bid_success_rate,

            COALESCE(sa.assignment_changes, 0)::int AS assignment_changes,
            COALESCE(ta.trade_requests, 0)::int AS trade_requests,
            ROUND(CASE WHEN COALESCE(ta.trade_requests,0)=0 THEN 0
                  ELSE ta.trades_approved::numeric/ta.trade_requests*100 END, 2)::numeric AS trade_completion_rate,
            ROUND(CASE WHEN COALESCE(ta.trade_requests,0)=0 THEN 0
                  ELSE ta.trades_cancelled::numeric/ta.trade_requests*100 END, 2)::numeric AS trade_cancellation_rate,
            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE sa.compliant_count::numeric/sa.completed_count*100 END, 2)::numeric AS attendance_compliance_rate,

            -- Standard and Urgent Drop rates
            ROUND(CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                  ELSE sa.standard_drop_count::numeric/sa.held_count*100 END,2)::numeric AS standard_drop_rate,
            ROUND(CASE WHEN COALESCE(sa.held_count,0)=0 THEN 0
                  ELSE sa.urgent_drop_count::numeric/sa.held_count*100 END,2)::numeric AS urgent_drop_rate,

            COALESCE(sa.early_clock_in_count, 0)::int AS early_clock_in,
            COALESCE(sa.late_clock_out_count, 0)::int AS late_clock_out,
            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE COALESCE(sa.early_clock_in_count,0)::numeric/sa.completed_count*100 END,2)::numeric AS early_clock_in_rate,
            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE COALESCE(sa.late_clock_out_count,0)::numeric/sa.completed_count*100 END,2)::numeric AS late_clock_out_rate,

            -- New attendance fields
            COALESCE(sa.on_time_in_count, 0)::int AS on_time_in,
            COALESCE(sa.on_time_out_count, 0)::int AS on_time_out,
            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE COALESCE(sa.on_time_in_count,0)::numeric/sa.completed_count*100 END,2)::numeric AS on_time_in_rate,
            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE COALESCE(sa.on_time_out_count,0)::numeric/sa.completed_count*100 END,2)::numeric AS on_time_out_rate,

            -- Auto clock-out: denominator = worked snapshots
            COALESCE(sa.auto_clock_out_count, 0)::int AS auto_clock_out,
            ROUND(CASE WHEN COALESCE(sa.completed_count,0)=0 THEN 0
                  ELSE COALESCE(sa.auto_clock_out_count,0)::numeric/sa.completed_count*100 END,2)::numeric AS auto_clock_out_rate
        FROM all_emps ae
        LEFT JOIN profiles      prof ON prof.id   = ae.emp_id
        LEFT JOIN offer_agg     oa   ON oa.emp_id = ae.emp_id
        LEFT JOIN snap_agg      sa   ON sa.emp_id = ae.emp_id
        LEFT JOIN bid_agg       ba   ON ba.emp_id = ae.emp_id
        LEFT JOIN trade_agg     ta   ON ta.emp_id = ae.emp_id
    )
    SELECT
        rm.employee_id,
        rm.employee_name,
        rm.total_offers,
        rm.accepted,
        rm.rejected,
        rm.expired,
        rm.assigned,
        rm.emergency_assigned,
        rm.cancel_standard,
        rm.cancel_late,
        rm.swap_out,
        rm.late_clock_in,
        rm.early_clock_out,
        rm.no_show,
        rm.completed,
        rm.acceptance_rate,
        rm.rejection_rate,
        rm.ignorance_rate,
        rm.cancel_rate,
        rm.late_cancel_rate,
        rm.swap_rate,
        rm.reliability_score,
        rm.late_clock_in_rate,
        rm.early_clock_out_rate,
        rm.no_show_rate,
        rm.drop_rate,
        rm.total_bids,
        rm.bids_accepted,
        rm.bid_success_rate,

        rm.assignment_changes,
        rm.trade_requests,
        rm.trade_completion_rate,
        rm.trade_cancellation_rate,
        rm.attendance_compliance_rate,
        -- performance_score: weighted sum of Reliability, Acceptance, Attendance, Bid Success
        ROUND(
            (rm.reliability_score * 0.35) +
            (rm.acceptance_rate * 0.25) +
            (rm.attendance_compliance_rate * 0.20) +
            (rm.bid_success_rate * 0.20),
            2
        )::numeric AS performance_score,
        -- engagement_score: marketplace activity per shift actually worked, not a raw
        -- point count. GREATEST(completed,1) avoids div-by-0 for employees with no
        -- worked shifts yet; the *30 scale means a raw ratio of ~3.33 activity-points
        -- per shift worked reaches the 100 ceiling — a starting default, not a
        -- precisely product-validated constant. Normalizing this way (vs. the old
        -- bids*8 + trades*12 + offers*10 point count) stops the score from simply
        -- tracking tenure length / shift volume.
        GREATEST(0, LEAST(100, ROUND(
            (rm.total_bids + rm.trade_requests * 1.5 + rm.total_offers * 1.25)
            / GREATEST(rm.completed, 1)
            * 30,
            2
        )))::numeric AS engagement_score,

        rm.standard_drop_rate,
        rm.urgent_drop_rate,

        rm.early_clock_in,
        rm.late_clock_out,
        rm.early_clock_in_rate,
        rm.late_clock_out_rate,

        -- New attendance fields
        rm.on_time_in,
        rm.on_time_out,
        rm.on_time_in_rate,
        rm.on_time_out_rate,

        -- Auto clock-out
        rm.auto_clock_out,
        rm.auto_clock_out_rate
    FROM raw_metrics rm
    ORDER BY employee_name;
END;
$$;


ALTER FUNCTION "public"."get_quarterly_performance_report"("p_year" integer, "p_quarter" integer, "p_org_ids" "uuid"[], "p_dept_ids" "uuid"[], "p_subdept_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_roster_day_publish_status"("p_roster_day_id" "uuid") RETURNS TABLE("roster_day_id" "uuid", "roster_date" "date", "total_shifts" bigint, "draft_shifts" bigint, "published_shifts" bigint, "publish_percentage" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        rd.id,
        rd.date,
        COUNT(rs.id),
        COUNT(rs.id) FILTER (WHERE rs.lifecycle = 'draft'),
        COUNT(rs.id) FILTER (WHERE rs.lifecycle = 'published'),
        CASE 
            WHEN COUNT(rs.id) = 0 THEN 0
            ELSE ROUND(
                (COUNT(rs.id) FILTER (WHERE rs.lifecycle = 'published')::NUMERIC / COUNT(rs.id)) * 100, 
                2
            )
        END
    FROM roster_days rd
    LEFT JOIN roster_groups rg ON rg.roster_day_id = rd.id
    LEFT JOIN roster_subgroups rsg ON rsg.roster_group_id = rg.id
    LEFT JOIN roster_shifts rs ON rs.roster_subgroup_id = rsg.id
    WHERE rd.id = p_roster_day_id
    GROUP BY rd.id, rd.date;
END;
$$;


ALTER FUNCTION "public"."get_roster_day_publish_status"("p_roster_day_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_roster_day_shifts"("p_roster_day_id" "uuid") RETURNS TABLE("shift_id" "uuid", "subgroup_id" "uuid", "subgroup_name" character varying, "group_id" "uuid", "group_name" character varying, "role_name" character varying, "start_time" time without time zone, "end_time" time without time zone, "employee_name" "text", "employee_id" "uuid", "state_id" "text", "lifecycle_status" "text", "assignment_status" "text", "assignment_outcome" "text", "bidding_status" "text", "trading_status" "text", "is_live" boolean, "sort_order" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        v.id,
        v.subgroup_id,
        v.subgroup_name,
        v.group_id,
        v.group_name,
        v.role_name,
        v.start_time,
        v.end_time,
        v.employee_name,
        v.assigned_employee_id,
        v.state_id,
        v.lifecycle_status,
        v.assignment_status,
        v.assignment_outcome,
        v.bidding_status,
        v.trading_status,
        v.is_live,
        v.sort_order
    FROM v_roster_shifts_with_live_state v
    WHERE v.roster_day_id = p_roster_day_id
    ORDER BY v.group_id, v.subgroup_id, v.sort_order;
END;
$$;


ALTER FUNCTION "public"."get_roster_day_shifts"("p_roster_day_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_roster_days_in_range"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("date" "date", "roster_day_id" "uuid", "status" "text", "shift_count" bigint, "assigned_count" bigint, "has_template" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    rd.date,
    rd.id as roster_day_id,
    rd.status::TEXT,
    COALESCE((
      SELECT COUNT(*)
      FROM public.roster_shifts rs
      JOIN public.roster_subgroups rsg ON rsg.id = rs.roster_subgroup_id
      JOIN public.roster_groups rg ON rg.id = rsg.roster_group_id
      WHERE rg.roster_day_id = rd.id
    ), 0) as shift_count,
    COALESCE((
      SELECT COUNT(*)
      FROM public.roster_shift_assignments rsa
      JOIN public.roster_shifts rs ON rs.id = rsa.roster_shift_id
      JOIN public.roster_subgroups rsg ON rsg.id = rs.roster_subgroup_id
      JOIN public.roster_groups rg ON rg.id = rsg.roster_group_id
      WHERE rg.roster_day_id = rd.id
    ), 0) as assigned_count,
    EXISTS (
      SELECT 1 FROM public.roster_template_applications rta
      WHERE rta.roster_day_id = rd.id
    ) as has_template
  FROM public.roster_days rd
  WHERE rd.organization_id = p_organization_id
    AND rd.date >= p_start_date
    AND rd.date <= p_end_date
  ORDER BY rd.date;
END;
$$;


ALTER FUNCTION "public"."get_roster_days_in_range"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_roster_days_in_range"("p_organization_id" "uuid", "p_department_id" "uuid", "p_sub_department_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("roster_date" "date", "roster_id" "uuid", "status" "text", "shift_count" bigint, "assigned_count" bigint, "has_template" boolean, "applied_template_ids" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.start_date as roster_date,
        r.id as roster_id,
        r.status::TEXT,
        COALESCE((
            SELECT COUNT(*)
            FROM public.shifts s
            WHERE s.roster_id = r.id AND s.deleted_at IS NULL
        ), 0) as shift_count,
        COALESCE((
            SELECT COUNT(*)
            FROM public.shifts s
            WHERE s.roster_id = r.id AND s.assigned_employee_id IS NOT NULL AND s.deleted_at IS NULL
        ), 0) as assigned_count,
        EXISTS (
            SELECT 1 FROM public.roster_template_applications rta
            WHERE rta.roster_id = r.id
        ) as has_template,
        ARRAY(
            SELECT rta.template_id FROM public.roster_template_applications rta
            WHERE rta.roster_id = r.id
        ) as applied_template_ids
    FROM public.rosters r
    WHERE r.organization_id = p_organization_id
      AND r.department_id = p_department_id
      AND (
          (p_sub_department_id IS NULL AND r.sub_department_id IS NULL) OR
          (p_sub_department_id IS NOT NULL AND r.sub_department_id = p_sub_department_id)
      )
      AND r.start_date >= p_start_date
      AND r.start_date <= p_end_date
    ORDER BY r.start_date;
END;
$$;


ALTER FUNCTION "public"."get_roster_days_in_range"("p_organization_id" "uuid", "p_department_id" "uuid", "p_sub_department_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_roster_planner_stats"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_department_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_sub_department_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("total_shifts" integer, "assigned_shifts" integer, "open_shifts" integer, "published_shifts" integer, "cancelled_shifts" integer, "total_net_minutes" bigint, "unique_employees" integer, "est_cost" numeric, "budget_cost" numeric, "scheduled_cost" numeric, "actual_cost" numeric, "actual_net_minutes" bigint, "costed_shifts" integer, "uncosted_shifts" integer, "actual_shifts" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH scoped AS (
      SELECT
          s.*,
          s AS shift_row,
          CASE
              WHEN ts.start_time IS NOT NULL AND ts.end_time IS NOT NULL THEN
                  GREATEST(0, (EXTRACT(EPOCH FROM (
                      (s.shift_date + ts.end_time)
                        + CASE WHEN ts.end_time <= ts.start_time
                               THEN INTERVAL '1 day' ELSE INTERVAL '0' END
                        - (s.shift_date + ts.start_time)
                  )) / 60)::int - COALESCE(s.unpaid_break_minutes, 0))
              WHEN s.actual_start IS NOT NULL AND s.actual_end IS NOT NULL THEN
                  GREATEST(0, (EXTRACT(EPOCH FROM (s.actual_end - s.actual_start)) / 60)::int
                              - COALESCE(s.unpaid_break_minutes, 0))
              ELSE NULL
          END AS worked_minutes
      FROM public.shifts s
      LEFT JOIN LATERAL (
          SELECT t.start_time, t.end_time
            FROM public.timesheets t
           WHERE t.shift_id = s.id
           ORDER BY t.start_time NULLS LAST
           LIMIT 1
      ) ts ON TRUE
      WHERE s.organization_id = p_organization_id
        AND s.shift_date BETWEEN p_start_date AND p_end_date
        AND s.deleted_at IS NULL
        AND (p_department_ids IS NULL OR s.department_id = ANY(p_department_ids))
        AND (p_sub_department_ids IS NULL OR s.sub_department_id = ANY(p_sub_department_ids))
  ),
  priced AS (
      SELECT
          scoped.*,
          -- Full award pricing on the assignee's contract terms (or the shift's
          -- own terms when unassigned): cl 41 penalties, cl 41.4, cl 42 OT, cl 43
          -- night, cl 28.1 meal, cl 28.2 first aid, cl 12/56.2 minimum
          -- engagement, cl 29 higher duties, Sch 2 §2 annualised Security, salary.
          internal.shift_cost(shift_row, net_length_minutes) AS sched_shift_cost,
          CASE WHEN worked_minutes IS NULL THEN NULL
               ELSE internal.shift_cost(shift_row, worked_minutes)
          END AS actual_shift_cost
      FROM scoped
  )
  SELECT
      COUNT(*) FILTER (WHERE NOT is_cancelled)::int,
      COUNT(*) FILTER (WHERE NOT is_cancelled AND assigned_employee_id IS NOT NULL)::int,
      COUNT(*) FILTER (WHERE NOT is_cancelled AND assigned_employee_id IS NULL)::int,
      COUNT(*) FILTER (WHERE lifecycle_status IN ('Published','InProgress','Completed'))::int,
      COUNT(*) FILTER (WHERE is_cancelled)::int,
      COALESCE(SUM(net_length_minutes) FILTER (WHERE NOT is_cancelled), 0)::bigint,
      COUNT(DISTINCT assigned_employee_id) FILTER (WHERE NOT is_cancelled)::int,
      COALESCE(SUM(sched_shift_cost) FILTER (WHERE NOT is_cancelled), 0)::numeric,
      (
        SELECT COALESCE(SUM(
          db.budgeted_cost
          * ( (LEAST(db.period_end, p_end_date) - GREATEST(db.period_start, p_start_date) + 1)::numeric
              / NULLIF((db.period_end - db.period_start + 1), 0) )
        ), 0)::numeric
        FROM public.department_budgets db
        JOIN public.departments d ON d.id = db.dept_id AND d.organization_id = p_organization_id
        WHERE db.period_start <= p_end_date AND db.period_end >= p_start_date
          AND (p_department_ids IS NULL OR db.dept_id = ANY(p_department_ids))
      ),
      COALESCE(SUM(sched_shift_cost) FILTER (WHERE NOT is_cancelled), 0)::numeric,
      COALESCE(SUM(actual_shift_cost) FILTER (WHERE NOT is_cancelled AND worked_minutes IS NOT NULL), 0)::numeric,
      COALESCE(SUM(worked_minutes) FILTER (WHERE NOT is_cancelled AND worked_minutes IS NOT NULL), 0)::bigint,
      COUNT(*) FILTER (WHERE NOT is_cancelled AND sched_shift_cost IS NOT NULL)::int,
      COUNT(*) FILTER (WHERE NOT is_cancelled AND sched_shift_cost IS NULL)::int,
      COUNT(*) FILTER (WHERE NOT is_cancelled AND worked_minutes IS NOT NULL)::int
  FROM priced;
$$;


ALTER FUNCTION "public"."get_roster_planner_stats"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_department_ids" "uuid"[], "p_sub_department_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_roster_planner_stats"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_department_ids" "uuid"[], "p_sub_department_ids" "uuid"[]) IS 'Roster Planner footer totals. scheduled_cost = the roster as planned (all live shifts, filled or not); actual_cost = what was worked. Both priced by fn_eba_estimate_shift_cost, the SQL port of the TypeScript EBA engine, so the footer agrees with the per-shift cards to the cent on ordinary/weekend/PH/night/overtime shifts.';



CREATE OR REPLACE FUNCTION "public"."get_roster_shift_state"("p_lifecycle" "text", "p_has_assignment" boolean, "p_assignment_confirmed" boolean) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    -- Only Draft states are valid for roster_shifts
    IF p_lifecycle = 'draft' THEN
        IF NOT p_has_assignment THEN
            RETURN 'S1';  -- Draft + Unassigned
        ELSE
            RETURN 'S2';  -- Draft + Assigned + Pending
        END IF;
    END IF;
    
    RETURN 'INVALID';
END;
$$;


ALTER FUNCTION "public"."get_roster_shift_state"("p_lifecycle" "text", "p_has_assignment" boolean, "p_assignment_confirmed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_roster_summary"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_department_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_sub_department_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("shift_date" "date", "group_type" "text", "sub_group_name" "text", "total_shifts" integer, "assigned_shifts" integer, "open_shifts" integer, "published_shifts" integer, "draft_shifts" integer, "cancelled_shifts" integer, "total_net_minutes" bigint, "unique_employees" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'hr'
    AS $$
  SELECT
    s.shift_date,
    s.group_type::text,
    s.sub_group_name::text,
    COUNT(*)::int                                            AS total_shifts,
    COUNT(*) FILTER (WHERE s.assigned_employee_id IS NOT NULL)::int AS assigned_shifts,
    COUNT(*) FILTER (WHERE s.assigned_employee_id IS NULL)::int    AS open_shifts,
    COUNT(*) FILTER (WHERE s.lifecycle_status IN ('Published', 'InProgress', 'Completed'))::int  AS published_shifts,
    COUNT(*) FILTER (WHERE s.lifecycle_status = 'Draft')::int      AS draft_shifts,
    COUNT(*) FILTER (WHERE s.is_cancelled)::int                    AS cancelled_shifts,
    COALESCE(SUM(s.net_length_minutes), 0)::bigint                 AS total_net_minutes,
    COUNT(DISTINCT s.assigned_employee_id)::int                    AS unique_employees
  FROM shifts s
  WHERE s.organization_id = p_organization_id
    AND s.shift_date BETWEEN p_start_date AND p_end_date
    AND s.deleted_at IS NULL
    AND (p_department_ids IS NULL OR s.department_id = ANY(p_department_ids))
    AND (p_sub_department_ids IS NULL OR s.sub_department_id = ANY(p_sub_department_ids))
  GROUP BY s.shift_date, s.group_type, s.sub_group_name
  ORDER BY s.shift_date, s.group_type, s.sub_group_name;
$$;


ALTER FUNCTION "public"."get_roster_summary"("p_organization_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_department_ids" "uuid"[], "p_sub_department_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shift_delta"("p_org_id" "uuid", "p_since" timestamp with time zone, "p_dept_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "deleted_at" timestamp with time zone, "shift_date" "date", "start_time" time without time zone, "end_time" time without time zone, "lifecycle_status" "public"."shift_lifecycle", "assignment_status" "public"."shift_assignment_status", "assigned_employee_id" "uuid", "version" integer, "department_id" "uuid", "sub_department_id" "uuid", "role_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
    SELECT
        s.id,
        s.updated_at,
        s.deleted_at,
        s.shift_date,
        s.start_time,
        s.end_time,
        s.lifecycle_status,
        s.assignment_status,
        s.assigned_employee_id,
        s.version,
        s.department_id,
        s.sub_department_id,
        s.role_id
    FROM shifts s
    WHERE
        s.organization_id = p_org_id
        AND s.updated_at > p_since
        AND (p_dept_ids IS NULL OR s.department_id = ANY(p_dept_ids))
        AND (p_start_date IS NULL OR s.shift_date >= p_start_date)
        AND (p_end_date   IS NULL OR s.shift_date <= p_end_date)
    ORDER BY s.updated_at ASC
    LIMIT 500;
$$;


ALTER FUNCTION "public"."get_shift_delta"("p_org_id" "uuid", "p_since" timestamp with time zone, "p_dept_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_shift_delta"("p_org_id" "uuid", "p_since" timestamp with time zone, "p_dept_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") IS 'Returns up to 500 shifts changed since p_since (exclusive). Client uses the max(updated_at) of the response as the next cursor. Includes soft-deleted rows (deleted_at IS NOT NULL) so client can purge them.';



