    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
BEGIN
  IF str IS NULL OR str = '' THEN
    RETURN FALSE;
  END IF;
  -- Check if it matches UUID format
  RETURN str ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
END;
$_$;


