CREATE OR REPLACE FUNCTION "public"."rename_roster_subgroup"("p_subgroup_id" "uuid", "p_new_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    UPDATE public.roster_subgroups SET name = p_new_name WHERE id = p_subgroup_id;
    
    -- Sync denormalized columns in shifts
    UPDATE public.shifts 
    SET sub_group_name = p_new_name,
        template_sub_group = p_new_name
    WHERE roster_subgroup_id = p_subgroup_id;
END;
$$;


ALTER FUNCTION "public"."rename_roster_subgroup"("p_subgroup_id" "uuid", "p_new_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rename_roster_subgroup_v2"("p_org_id" "uuid", "p_dept_id" "uuid", "p_group_external_id" "text", "p_old_name" "text", "p_new_name" "text", "p_start_date" "date", "p_end_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_current_date DATE;
    v_roster_id UUID;
    v_roster_group_id UUID;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_scope('roster.edit', p_org_id, p_dept_id, NULL);
    v_current_date := p_start_date;
    WHILE v_current_date <= p_end_date LOOP
        -- Find Roster
        SELECT id INTO v_roster_id FROM public.rosters 
        WHERE organization_id = p_org_id 
          AND department_id = p_dept_id
          AND start_date = v_current_date;

        IF v_roster_id IS NOT NULL THEN
            -- Find Group
            SELECT id INTO v_roster_group_id FROM public.roster_groups
            WHERE roster_id = v_roster_id AND external_id = p_group_external_id;

            IF v_roster_group_id IS NOT NULL THEN
                -- 1. Update formal subgroup records (idempotent name change)
                UPDATE public.roster_subgroups
                SET name = p_new_name
                WHERE roster_group_id = v_roster_group_id AND name = p_old_name;

                -- 2. Update shifts (denormalized name column)
                UPDATE public.shifts
                SET sub_group_name = p_new_name
                WHERE roster_id = v_roster_id AND sub_group_name = p_old_name;
            END IF;
        END IF;

        v_current_date := v_current_date + 1;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."rename_roster_subgroup_v2"("p_org_id" "uuid", "p_dept_id" "uuid", "p_group_external_id" "text", "p_old_name" "text", "p_new_name" "text", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_fairness_ledger_recompute"("p_org_id" "uuid", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_rows integer;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
    END IF;

    IF NOT (
        EXISTS (SELECT 1 FROM public.app_access_certificates c
                    WHERE c.user_id = auth.uid()
                      AND c.is_active = true
                      AND (c.access_level = 'zeta' OR c.organization_id = p_org_id)
                      AND c.access_level = ANY (
                            ARRAY['gamma','delta','epsilon','zeta']::public.access_level[]))
    ) THEN
        RAISE EXCEPTION 'not authorised to recompute the fairness ledger for this organization'
            USING ERRCODE = '42501';
    END IF;

    SELECT public.recompute_fairness_ledger(p_org_id, p_as_of) INTO v_rows;
    RETURN v_rows;
END $$;


ALTER FUNCTION "public"."request_fairness_ledger_recompute"("p_org_id" "uuid", "p_as_of" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_fairness_ledger_recompute"("p_org_id" "uuid", "p_as_of" "date") IS 'Client-callable fairness-ledger rebuild. SECURITY DEFINER: authorises the caller against the same predicate as fairness_ledger_org_scoped (and rejects an absent auth.uid()) BEFORE delegating to the privileged recompute, which authenticated may not call directly.';



CREATE OR REPLACE FUNCTION "public"."request_shift_trade"("p_shift_id" "uuid", "p_employee_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_shift RECORD;
BEGIN
    -- Get current shift state
    SELECT * INTO v_shift
    FROM shifts
    WHERE id = p_shift_id
    AND deleted_at IS NULL;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Shift not found');
    END IF;
    
    -- Validate: Must be in S4 (Confirmed) per state machine
    IF v_shift.lifecycle_status != 'Published' 
       OR v_shift.assignment_outcome != 'confirmed'
       OR v_shift.trading_status != 'NoTrade' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Shift cannot be traded');
    END IF;
    
    IF v_shift.assigned_employee_id != p_employee_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not assigned to this employee');
    END IF;
    
    -- Transition S4 → S9: Request trade
    UPDATE shifts
    SET 
        trading_status = 'TradeRequested'::shift_trading,
        trade_requested_at = NOW(),
        updated_at = NOW(),
        last_modified_by = p_employee_id,
        last_modified_reason = 'Trade requested'
    WHERE id = p_shift_id;
    
    -- Trigger will sync to roster_shifts automatically
    
    RETURN jsonb_build_object(
        'success', true,
        'shift_id', p_shift_id,
        'transition', 'S4 → S9',
        'new_state', 'TradeRequested'
    );
END;
$$;


ALTER FUNCTION "public"."request_shift_trade"("p_shift_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_trade"("p_shift_id" "uuid", "p_target_employee_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_shift RECORD;
BEGIN
    SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id FOR UPDATE;
    
    IF v_shift IS NULL THEN RAISE EXCEPTION 'Shift not found'; END IF;
    
    -- Validate Owner
    IF v_shift.assigned_employee_id != p_actor_id THEN
        RAISE EXCEPTION 'You can only trade your own shifts';
    END IF;
    
    -- Validate State (Must be S4 Confirmed)
    IF v_shift.assignment_outcome != 'confirmed' THEN
        RAISE EXCEPTION 'Only confirmed shifts can be traded';
    END IF;
    
    -- Create Trade Request
    INSERT INTO trade_requests (
        shift_id, requesting_employee_id, target_employee_id, status
    ) VALUES (
        p_shift_id, p_actor_id, p_target_employee_id, 'pending'
    );
    
    -- Update Shift Flag
    UPDATE shifts 
    SET is_trade_requested = TRUE 
    WHERE id = p_shift_id;
    
    RETURN jsonb_build_object('success', true, 'status', 'trade_requested');
END;
$$;


ALTER FUNCTION "public"."request_trade"("p_shift_id" "uuid", "p_target_employee_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_audit_uuid_array"("p_field" "text", "p_arr" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'hr'
    AS $$
DECLARE
    v_id text;
    v_name text;
    v_res jsonb := '[]'::jsonb;
BEGIN
    IF p_arr IS NULL OR jsonb_typeof(p_arr) <> 'array' THEN
        RETURN p_arr;
    END IF;

    FOR v_id IN SELECT jsonb_array_elements_text(p_arr)
    LOOP
        CASE p_field
            WHEN 'required_skills' THEN
                SELECT name INTO v_name FROM public.skills WHERE id = v_id::uuid;
            WHEN 'required_licenses' THEN
                SELECT name INTO v_name FROM public.licenses WHERE id = v_id::uuid;
            WHEN 'event_ids' THEN
                SELECT name INTO v_name FROM public.events WHERE id = v_id::uuid;
            ELSE
                v_name := NULL;
        END CASE;

        v_res := v_res || to_jsonb(COALESCE(v_name, v_id));
    END LOOP;

    RETURN v_res;
END;
$$;


ALTER FUNCTION "public"."resolve_audit_uuid_array"("p_field" "text", "p_arr" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_audit_uuid_name"("p_field" "text", "p_uuid" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'hr'
    AS $$
DECLARE
    v_name text;
BEGIN
    IF p_uuid IS NULL THEN
        RETURN NULL;
    END IF;
    CASE p_field
        WHEN 'role_id' THEN
            SELECT name INTO v_name FROM hr.roles WHERE id = p_uuid;
        WHEN 'remuneration_level_id' THEN
            -- Old UUIDs are no longer resolvable since remuneration_levels view uses level_number.
            v_name := p_uuid::text;
        WHEN 'shift_group_id' THEN
            SELECT name INTO v_name FROM public.roster_groups WHERE id = p_uuid;
        WHEN 'roster_subgroup_id' THEN
            SELECT name INTO v_name FROM public.roster_subgroups WHERE id = p_uuid;
        WHEN 'sub_department_id' THEN
            SELECT name INTO v_name FROM public.sub_departments WHERE id = p_uuid;
        ELSE
            v_name := NULL;
    END CASE;
    RETURN COALESCE(v_name, p_uuid::text);
END;
$$;


ALTER FUNCTION "public"."resolve_audit_uuid_name"("p_field" "text", "p_uuid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_changes_jsonb"("p_changes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'hr'
    AS $$
DECLARE
    v_key text;
    v_val jsonb;
    v_old jsonb;
    v_new jsonb;
    v_res jsonb := '{}'::jsonb;
BEGIN
    IF p_changes IS NULL THEN
        RETURN NULL;
    END IF;

    FOR v_key, v_val IN SELECT * FROM jsonb_each(p_changes)
    LOOP
        IF v_key IN ('role_id', 'remuneration_level_id', 'shift_group_id', 'roster_subgroup_id', 'sub_department_id') THEN
            v_old := to_jsonb(public.resolve_audit_uuid_name(v_key, (v_val->>'old')::uuid));
            v_new := to_jsonb(public.resolve_audit_uuid_name(v_key, (v_val->>'new')::uuid));
            v_res := v_res || jsonb_build_object(v_key, jsonb_build_object('old', v_old, 'new', v_new));
        ELSIF v_key IN ('required_skills', 'required_licenses', 'event_ids') THEN
            v_old := public.resolve_audit_uuid_array(v_key, v_val->'old');
            v_new := public.resolve_audit_uuid_array(v_key, v_val->'new');
            v_res := v_res || jsonb_build_object(v_key, jsonb_build_object('old', v_old, 'new', v_new));
        ELSE
            v_res := v_res || jsonb_build_object(v_key, v_val);
        END IF;
    END LOOP;

    RETURN v_res;
END;
$$;


ALTER FUNCTION "public"."resolve_changes_jsonb"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_user_permissions"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_type_x JSONB;
    v_type_y JSONB;
    v_scope_tree JSONB;
    v_y_level access_level;
    v_y_org_id UUID;
    v_y_dept_id UUID;
    v_y_subdept_id UUID;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;


    -- =============================================
    -- 1. Build typeX array (all active Type X certs)
    -- =============================================
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', ac.id,
            'level', ac.access_level::text,
            'org_id', ac.organization_id,
            'dept_id', ac.department_id,
            'subdept_id', ac.sub_department_id,
            'org_name', o.name,
            'dept_name', d.name,
            'subdept_name', sd.name
        )
    ), '[]'::jsonb)
    INTO v_type_x
    FROM app_access_certificates ac
    LEFT JOIN organizations o ON o.id = ac.organization_id
    LEFT JOIN departments d ON d.id = ac.department_id
    LEFT JOIN sub_departments sd ON sd.id = ac.sub_department_id
    WHERE ac.user_id = v_user_id
      AND ac.certificate_type = 'X'
      AND ac.is_active = true;

    -- =============================================
    -- 2. Build typeY object
    -- =============================================
    SELECT jsonb_build_object(
        'id', ac.id,
        'level', ac.access_level::text,
        'org_id', ac.organization_id,
        'dept_id', ac.department_id,
        'subdept_id', ac.sub_department_id,
        'org_name', o.name,
        'dept_name', d.name,
        'subdept_name', sd.name
    ),
    ac.access_level,
    ac.organization_id,
    ac.department_id,
    ac.sub_department_id
    INTO v_type_y, v_y_level, v_y_org_id, v_y_dept_id, v_y_subdept_id
    FROM app_access_certificates ac
    LEFT JOIN organizations o ON o.id = ac.organization_id
    LEFT JOIN departments d ON d.id = ac.department_id
    LEFT JOIN sub_departments sd ON sd.id = ac.sub_department_id
    WHERE ac.user_id = v_user_id
      AND ac.certificate_type = 'Y'
      AND ac.is_active = true
    LIMIT 1;

    -- IF no Type Y certificate found but user is an admin, grant Zeta access
    -- Synthetic-zeta branch removed by migration 20260825220000.
    -- A legacy_system_role='admin' holding no Type Y certificate used to be
    -- promoted here to zeta — ALL organizations — which is strictly more than
    -- any certificate this system can issue, and had no counterpart in
    -- user_has_action_in_scope. It also emitted a typeY object with a NULL id,
    -- violating the PermissionCert contract the frontend reads. Such a profile
    -- now resolves to no managerial level, like anyone else without a Type Y.

    -- =============================================
    -- 3. Build allowed_scope_tree based on Type Y level
    -- =============================================
    IF v_y_level IS NULL THEN
        -- No Type Y access: empty managerial scope
        v_scope_tree := jsonb_build_object('organizations', '[]'::jsonb);
    ELSIF v_y_level = 'zeta' THEN
        -- Zeta: full hierarchy (all orgs, all depts, all subdepts)
        SELECT jsonb_build_object('organizations',
            COALESCE(jsonb_agg(
                jsonb_build_object(
                    'id', org.id,
                    'name', org.name,
                    'departments', COALESCE(org.depts, '[]'::jsonb)
                )
            ), '[]'::jsonb)
        )
        INTO v_scope_tree
        FROM (
            SELECT o.id, o.name,
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', d.id,
                        'name', d.name,
                        'subdepartments', COALESCE(
                            (SELECT jsonb_agg(
                                jsonb_build_object('id', sd.id, 'name', sd.name)
                            ) FROM sub_departments sd WHERE sd.department_id = d.id AND sd.is_active = true),
                            '[]'::jsonb
                        )
                    )
                ) FROM departments d WHERE d.organization_id = o.id AND d.is_active = true) AS depts
            FROM organizations o
            WHERE o.is_active = true
        ) org;

    ELSIF v_y_level = 'epsilon' THEN
        -- Epsilon: fixed org, all depts under it, all subdepts
        SELECT jsonb_build_object('organizations',
            jsonb_build_array(
                jsonb_build_object(
                    'id', o.id,
                    'name', o.name,
                    'departments', COALESCE(
                        (SELECT jsonb_agg(
                            jsonb_build_object(
                                'id', d.id,
                                'name', d.name,
                                'subdepartments', COALESCE(
                                    (SELECT jsonb_agg(
                                        jsonb_build_object('id', sd.id, 'name', sd.name)
                                    ) FROM sub_departments sd WHERE sd.department_id = d.id AND sd.is_active = true),
                                    '[]'::jsonb
                                )
                            )
                        ) FROM departments d WHERE d.organization_id = o.id AND d.is_active = true),
                        '[]'::jsonb
                    )
                )
            )
        )
        INTO v_scope_tree
        FROM organizations o
        WHERE o.id = v_y_org_id;

    ELSIF v_y_level = 'delta' THEN
        -- Delta: fixed org + dept, all subdepts under that dept
        SELECT jsonb_build_object('organizations',
            jsonb_build_array(
                jsonb_build_object(
                    'id', o.id,
                    'name', o.name,
                    'departments', jsonb_build_array(
                        jsonb_build_object(
                            'id', d.id,
                            'name', d.name,
                            'subdepartments', COALESCE(
                                (SELECT jsonb_agg(
                                    jsonb_build_object('id', sd.id, 'name', sd.name)
                                ) FROM sub_departments sd WHERE sd.department_id = d.id AND sd.is_active = true),
                                '[]'::jsonb
                            )
                        )
                    )
                )
            )
        )
        INTO v_scope_tree
        FROM organizations o, departments d
        WHERE o.id = v_y_org_id
          AND d.id = v_y_dept_id;

    ELSIF v_y_level = 'gamma' THEN
        -- Gamma: fixed org + dept + subdept (fully locked)
        SELECT jsonb_build_object('organizations',
            jsonb_build_array(
                jsonb_build_object(
                    'id', o.id,
                    'name', o.name,
                    'departments', jsonb_build_array(
                        jsonb_build_object(
                            'id', d.id,
                            'name', d.name,
                            'subdepartments', jsonb_build_array(
                                jsonb_build_object('id', sd.id, 'name', sd.name)
                            )
                        )
                    )
                )
            )
        )
        INTO v_scope_tree
        FROM organizations o, departments d, sub_departments sd
        WHERE o.id = v_y_org_id
          AND d.id = v_y_dept_id
          AND sd.id = v_y_subdept_id;
    END IF;

    RETURN jsonb_build_object(
        'typeX', v_type_x,
        'typeY', v_type_y,
        'allowed_scope_tree', v_scope_tree
    );
END;
$$;


ALTER FUNCTION "public"."resolve_user_permissions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."roster_calculate_net_hours"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_duration DECIMAL;
BEGIN
  -- Calculate duration in hours
  IF NEW.end_time >= NEW.start_time THEN
    v_duration := EXTRACT(EPOCH FROM (NEW.end_time - NEW.start_time)) / 3600.0;
  ELSE
    -- Handle overnight shifts
    v_duration := EXTRACT(EPOCH FROM (NEW.end_time + INTERVAL '24 hours' - NEW.start_time)) / 3600.0;
  END IF;
  
  -- Subtract unpaid breaks
  NEW.net_hours := v_duration - COALESCE(NEW.unpaid_break_minutes, 0) / 60.0;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."roster_calculate_net_hours"() OWNER TO "postgres";


