CREATE OR REPLACE FUNCTION "public"."shares_organisation_with"("p_other" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT auth.uid() IS NOT NULL AND (
       p_other = auth.uid()
    OR EXISTS (
         SELECT 1 FROM public.user_contracts mine
         JOIN public.user_contracts theirs ON theirs.organization_id = mine.organization_id
          WHERE mine.user_id = auth.uid() AND mine.status = 'Active'
            AND theirs.user_id = p_other AND theirs.status = 'Active')
    OR EXISTS (
         SELECT 1 FROM public.app_access_certificates ac
         JOIN public.user_contracts theirs ON theirs.organization_id = ac.organization_id
          WHERE ac.user_id = auth.uid() AND ac.is_active
            AND theirs.user_id = p_other AND theirs.status = 'Active')
    OR EXISTS (
         SELECT 1 FROM public.app_access_certificates ac
          WHERE ac.user_id = auth.uid() AND ac.is_active AND ac.access_level = 'zeta')
  );
$$;


ALTER FUNCTION "public"."shares_organisation_with"("p_other" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_day_typed_shortfall"("p_shift_date" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_unpaid_break_minutes" integer, "p_target_employment_type" "text", "p_target_requires_flexible" boolean, "p_is_training" boolean, "p_role_id" "uuid", "p_jurisdiction" "text" DEFAULT 'AU-NSW'::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_is_security boolean;
    v_net         integer;
    v_is_ph       boolean;
    v_is_sunday   boolean;
    v_horizon     date;
BEGIN
    IF p_shift_date IS NULL OR p_start_time IS NULL OR p_end_time IS NULL THEN
        RETURN NULL;
    END IF;

    IF p_target_employment_type = 'FT' THEN
        RETURN NULL;
    END IF;

    v_is_ph := EXISTS (
        SELECT 1 FROM public.public_holidays ph
        WHERE ph.holiday_date = p_shift_date AND ph.jurisdiction = p_jurisdiction
    );

    IF NOT v_is_ph THEN
        v_horizon := public.public_holiday_calendar_horizon(p_jurisdiction);
        IF v_horizon IS NULL OR p_shift_date > v_horizon THEN
            RAISE EXCEPTION
                'The % public holiday calendar only reaches %, so a shift on % cannot be classified. Extend public_holidays before rostering past the horizon — treating an uncovered date as "not a public holiday" is how cl 56.2 silently stopped applying to an entire year once before.',
                p_jurisdiction, COALESCE(v_horizon::text, '(empty)'), p_shift_date
                USING ERRCODE = '23514';
        END IF;
    END IF;

    v_is_sunday := EXTRACT(DOW FROM p_shift_date) = 0;

    IF NOT v_is_ph AND NOT v_is_sunday THEN
        RETURN NULL;
    END IF;

    v_is_security := public.shift_is_security_role(p_role_id);
    v_net := public.shift_net_minutes(
        p_start_time,
        p_end_time,
        CASE WHEN v_is_security THEN 0 ELSE COALESCE(p_unpaid_break_minutes, 0) END
    );

    IF v_is_ph AND v_net < 240 THEN
        RETURN format(
            'SHAPE_MIN_ENGAGEMENT_PH: a shift on a public holiday must be at least 4 hours (ICC EBA cl 56.2); this one provides %s minutes of net working time.',
            v_net
        );
    END IF;

    IF v_is_sunday
       AND NOT (p_target_employment_type = 'PT' AND NOT COALESCE(p_target_requires_flexible, false))
       AND NOT COALESCE(p_is_training, false)
       AND v_net < 240
    THEN
        RETURN format(
            'SHAPE_MIN_ENGAGEMENT: a Sunday engagement must be at least 4 hours (ICC EBA cl 12.4(c)/12.5(c)); this one provides %s minutes of net working time.',
            v_net
        );
    END IF;

    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."shift_day_typed_shortfall"("p_shift_date" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_unpaid_break_minutes" integer, "p_target_employment_type" "text", "p_target_requires_flexible" boolean, "p_is_training" boolean, "p_role_id" "uuid", "p_jurisdiction" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."shift_day_typed_shortfall"("p_shift_date" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_unpaid_break_minutes" integer, "p_target_employment_type" "text", "p_target_requires_flexible" boolean, "p_is_training" boolean, "p_role_id" "uuid", "p_jurisdiction" "text") IS 'NULL when a shift satisfies the two DAY-TYPED shape rules (cl 56.2 public holiday, cl 12 Sunday tier), else the breach. Shared by trg_shift_shape_3_day_typed (which raises) and apply_template_to_date_range_v2 (which skips). Mirrors compliance/shape/evaluate.ts.';



CREATE OR REPLACE FUNCTION "public"."shift_is_security_role"("p_role_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.roles r
        WHERE r.id = p_role_id AND lower(r.name) LIKE '%security%'
    );
$$;


ALTER FUNCTION "public"."shift_is_security_role"("p_role_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."shift_is_security_role"("p_role_id" "uuid") IS 'True when a shift''s role is a Security role under EBA Schedule 3. Mirrors isSecurityRoleName() in src/modules/compliance/security-role.ts, which owns this definition.';



CREATE OR REPLACE FUNCTION "public"."shift_pay_terms"("s" "public"."shifts") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
DECLARE
    v_uid uuid := auth.uid();
    t     record;
BEGIN
    IF s.user_contract_id IS NULL OR s.assigned_employee_id IS NULL OR v_uid IS NULL THEN
        RETURN NULL;
    END IF;
    IF s.assigned_employee_id <> v_uid AND NOT public.user_has_delta_access(v_uid) THEN
        RETURN NULL;
    END IF;

    SELECT * INTO t FROM internal.shift_pay_terms(s);
    RETURN jsonb_build_object(
        'pay_basis',         t.pay_basis,
        'employment_type',   t.employment_type,
        'substantive_level', t.substantive_level,
        'paid_level',        t.paid_level,
        'higher_duties',     t.higher_duties,
        'base_rate',         round(t.base_rate, 4));
END;
$$;


ALTER FUNCTION "public"."shift_pay_terms"("s" "public"."shifts") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."shift_pay_terms"("s" "public"."shifts") IS 'Computed field: the linked contract''s pay terms on the shift date (pay_basis, employment_type, substantive_level, paid_level, higher_duties, base_rate). NULL unless the caller is the assignee or has delta access. Name it explicitly in a select — * never includes computed fields.';



CREATE OR REPLACE FUNCTION "public"."shift_pay_terms_for"("s" "public"."shifts", "p_employee" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
DECLARE
    v_uid uuid := auth.uid();
    t     record;
BEGIN
    IF p_employee IS NULL OR v_uid IS NULL THEN
        RETURN NULL;
    END IF;
    IF p_employee <> v_uid AND NOT public.user_has_delta_access(v_uid) THEN
        RETURN NULL;
    END IF;

    SELECT * INTO t FROM internal.prospective_pay_terms(s, p_employee);
    RETURN jsonb_build_object(
        'pay_basis',         t.pay_basis,
        'employment_type',   t.employment_type,
        'substantive_level', t.substantive_level,
        'paid_level',        t.paid_level,
        'higher_duties',     t.higher_duties,
        'base_rate',         round(t.base_rate, 4));
END;
$$;


ALTER FUNCTION "public"."shift_pay_terms_for"("s" "public"."shifts", "p_employee" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_accept_offer"("p_shift_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_shift RECORD; v_state text; v_name text; v_role text;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_assignee_or(p_shift_id, p_user_id, 'shift.assign');
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted'); END IF;
  SELECT COALESCE(first_name||' '||COALESCE(last_name,''), email), COALESCE(left(lower(legacy_system_role::text),50),'employee')
    INTO v_name, v_role FROM public.profiles WHERE id = p_user_id;
  v_name := COALESCE(v_name, 'System'); v_role := COALESCE(v_role, 'employee');
  v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status, v_shift.assignment_outcome, v_shift.trading_status, v_shift.is_cancelled);
  IF v_state != 'S3' THEN
    RETURN jsonb_build_object('success', false, 'error', format('sm_accept_offer requires state S3, current state is %s', v_state));
  END IF;
  UPDATE public.shifts SET
    assignment_outcome    = 'confirmed'::public.shift_assignment_outcome,
    confirmed_at          = NOW(),
    fulfillment_status    = 'scheduled'::public.shift_fulfillment_status,
    last_modified_by      = p_user_id,
    updated_at            = NOW()
  WHERE id = p_shift_id;
  RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S4');
END; $$;


ALTER FUNCTION "public"."sm_accept_offer"("p_shift_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_accept_trade"("p_shift_id" "uuid", "p_accepting_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_shift RECORD;
    v_state TEXT;
BEGIN
    SELECT * INTO v_shift FROM shifts WHERE id=p_shift_id AND deleted_at IS NULL FOR UPDATE;
    
    v_state := get_shift_state_id(p_shift_id);
    IF v_state != 'S9' THEN 
        RETURN jsonb_build_object('success', false, 'error', 'Not S9'); 
    END IF;
    
    IF v_shift.assigned_employee_id = p_accepting_employee_id THEN 
        RETURN jsonb_build_object('success', false, 'error', 'Cannot self-accept'); 
    END IF;
    
    UPDATE shifts 
    SET trading_status='TradeAccepted', 
        updated_at=NOW(), 
        last_modified_by=p_accepting_employee_id 
    WHERE id=p_shift_id;

    RETURN jsonb_build_object('success', true, 'from_state', 'S9', 'to_state', 'S10');
END; 
$$;


ALTER FUNCTION "public"."sm_accept_trade"("p_shift_id" "uuid", "p_accepting_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_accept_trade"("p_swap_id" "uuid", "p_offer_id" "uuid", "p_offerer_id" "uuid", "p_offer_shift_id" "uuid" DEFAULT NULL::"uuid", "p_compliance_snapshot" "jsonb" DEFAULT NULL::"jsonb") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_caller    uuid := auth.uid();
  v_swap      shift_swaps%ROWTYPE;
  v_offer     swap_offers%ROWTYPE;
  v_shift_ids uuid[];
BEGIN
  -- 1. Lock the swap row and verify it is still OPEN
  SELECT * INTO v_swap FROM shift_swaps WHERE id = p_swap_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Swap request not found', 'code', 'SWAP_NOT_FOUND');
  END IF;

  -- 1a. AUTHORIZATION (H2): only the swap's requester may accept an offer on it.
  IF v_caller IS NOT NULL
     AND v_caller <> v_swap.requester_id
     AND NOT public.can_act_on_shift('swap.approve', v_swap.requester_shift_id) THEN
    RETURN json_build_object('success', false, 'error', 'Not authorized to accept this swap', 'code', 'FORBIDDEN');
  END IF;

  IF v_swap.status <> 'OPEN' THEN
    RETURN json_build_object(
      'success', false,
      'error', format('Swap is no longer OPEN (current status: %s)', v_swap.status),
      'code', 'SWAP_NOT_OPEN'
    );
  END IF;

  -- 1b. OFFER INTEGRITY
  SELECT * INTO v_offer FROM swap_offers WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND OR v_offer.swap_request_id <> p_swap_id THEN
    RETURN json_build_object('success', false, 'error', 'Offer does not belong to this swap', 'code', 'OFFER_MISMATCH');
  END IF;
  IF v_offer.offerer_id <> p_offerer_id THEN
    RETURN json_build_object('success', false, 'error', 'Offerer does not match the offer', 'code', 'OFFERER_MISMATCH');
  END IF;
  IF v_offer.status <> 'SUBMITTED' THEN
    RETURN json_build_object(
      'success', false,
      'error', format('Offer is not selectable (status: %s)', v_offer.status),
      'code', 'OFFER_NOT_SUBMITTED'
    );
  END IF;

  -- 1c. COMPLIANCE GUARD
  IF p_compliance_snapshot IS NULL
     OR COALESCE((p_compliance_snapshot->>'feasible')::boolean, false) = false THEN
    RETURN json_build_object('success', false, 'error', 'Compliance snapshot missing or not feasible', 'code', 'COMPLIANCE_REQUIRED');
  END IF;

  -- 2. Move swap to MANAGER_PENDING
  UPDATE shift_swaps
  SET
    status          = 'MANAGER_PENDING',
    target_id       = p_offerer_id,
    target_shift_id = p_offer_shift_id,
    updated_at      = NOW()
  WHERE id = p_swap_id;

  -- 3. Mark chosen offer as SELECTED
  UPDATE swap_offers
  SET status              = 'SELECTED',
      compliance_snapshot = p_compliance_snapshot
  WHERE id = p_offer_id;

  -- 4. Reject all other outstanding offers for this swap
  UPDATE swap_offers
  SET status = 'REJECTED'
  WHERE swap_request_id = p_swap_id
    AND id <> p_offer_id
    AND status NOT IN ('WITHDRAWN', 'EXPIRED', 'REJECTED');

  -- 5. Lock both shifts to TradeAccepted
  v_shift_ids := ARRAY[v_swap.requester_shift_id, p_offer_shift_id];
  UPDATE shifts
  SET trading_status = 'TradeAccepted'
  WHERE id = ANY(v_shift_ids)
    AND id IS NOT NULL;

  RETURN json_build_object('success', true);

EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM, 'code', SQLSTATE);
END;
$$;


ALTER FUNCTION "public"."sm_accept_trade"("p_swap_id" "uuid", "p_offer_id" "uuid", "p_offerer_id" "uuid", "p_offer_shift_id" "uuid", "p_compliance_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_all_active_contracts_ft_in"("p_profile_id" "uuid", "p_sub_department_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'hr', 'pg_catalog'
    AS $$
  WITH in_scope AS (
    SELECT lower(COALESCE(uc.employment_status::text, '')) AS st
      FROM hr.user_contracts uc
     WHERE uc.user_id = p_profile_id
       AND uc.status = 'Active'
       AND ( p_sub_department_id IS NULL
          OR uc.sub_department_id = p_sub_department_id
          OR (uc.sub_department_id IS NULL AND uc.department_id IS NOT NULL
              AND uc.department_id = (SELECT sd.department_id
                                        FROM public.sub_departments sd
                                       WHERE sd.id = p_sub_department_id)) )
  )
  -- Vacuously true is the wrong answer: someone with NO contract in scope is
  -- not "wholly Full-Time", they are unclassified, and must stay able to
  -- declare. Hence the EXISTS as well as the NOT EXISTS.
  SELECT EXISTS (SELECT 1 FROM in_scope)
     AND NOT EXISTS (SELECT 1 FROM in_scope WHERE st NOT LIKE '%full%');
$$;


ALTER FUNCTION "public"."sm_all_active_contracts_ft_in"("p_profile_id" "uuid", "p_sub_department_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sm_all_active_contracts_ft_in"("p_profile_id" "uuid", "p_sub_department_id" "uuid") IS 'True when the profile holds at least one Active contract in scope and EVERY one of them is Full-Time. Narrower than sm_holds_active_ft_contract_in, which answers "any". Used by the availability guard so a sub-department holding both a Full-Time and a Casual role stays declarable for the Casual side (EBA cl 13 Multi-Hiring). See migration 20260824130200.';



CREATE OR REPLACE FUNCTION "public"."sm_apply_shift_op"("p_shift_id" "uuid", "p_expected_version" integer, "p_op" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_idempotency_key" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller     uuid := auth.uid();
  v_pre        RECORD;
  v_cur        RECORD;
  v_state      text;
  v_to_state   text;
  v_write      jsonb;
  v_event      public.shift_event_type;
  v_actor_role text;
  v_domain     text;
  v_changes    jsonb := '{}'::jsonb;
BEGIN
  IF v_caller IS NOT NULL AND NOT (
       EXISTS (
            SELECT 1 FROM public.app_access_certificates c
            WHERE c.user_id = v_caller
              AND c.is_active = true
              AND c.access_level IN ('gamma', 'delta', 'epsilon', 'zeta')
          )
     ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;

  SELECT * INTO v_pre
  FROM public.shifts
  WHERE id = p_shift_id AND deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'GONE');
  END IF;

  -- scope guard (20261011 access matrix): the caller must hold this op's
  -- action over THIS shift's place, not merely a manager level somewhere.
  IF v_caller IS NOT NULL AND NOT public.user_has_action_in_scope(
       CASE p_op
         WHEN 'publish'       THEN 'shift.publish'
         WHEN 'unpublish'     THEN 'shift.publish'
         WHEN 'delete'        THEN 'shift.delete'
         WHEN 'assign'        THEN 'shift.assign'
         WHEN 'unassign'      THEN 'shift.assign'
         WHEN 'select_winner' THEN 'bid.assign'
         WHEN 'approve_trade' THEN 'swap.approve'
         WHEN 'reject_trade'  THEN 'swap.approve'
         WHEN 'create'        THEN 'shift.create'
         ELSE 'shift.edit'
       END,
       v_pre.organization_id, v_pre.department_id, v_pre.sub_department_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;

  IF p_idempotency_key IS NOT NULL AND EXISTS (
       SELECT 1 FROM public.shift_events e
       WHERE e.shift_id = p_shift_id
         AND e.metadata->>'idem' = p_idempotency_key::text
     ) THEN
    RETURN jsonb_build_object(
      'ok', true, 'code', 'IDEMPOTENT_REPLAY', 'version', v_pre.version
    );
  END IF;

  IF v_pre.version <> p_expected_version THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'VERSION_CONFLICT',
      'current_version', v_pre.version,
      'current_state', public.get_shift_fsm_state(
        v_pre.lifecycle_status, v_pre.assignment_status, v_pre.assignment_outcome,
        v_pre.trading_status, v_pre.is_cancelled, v_pre.bidding_status),
      'last_modified_by', v_pre.last_modified_by,
      'updated_at', v_pre.updated_at,
      'server_row', to_jsonb(v_pre)
    );
  END IF;

  v_state := public.get_shift_fsm_state(
    v_pre.lifecycle_status, v_pre.assignment_status, v_pre.assignment_outcome,
    v_pre.trading_status, v_pre.is_cancelled, v_pre.bidding_status);

  IF NOT public.fsm_op_is_legal(v_state, p_op) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'ILLEGAL_TRANSITION',
      'current_state', v_state,
      'attempted', p_op
    );
  END IF;

  PERFORM set_config('app.audit.via_gateway', '1', true);
  v_write := public._apply_shift_op_write(p_shift_id, p_op, p_payload, v_caller);
  PERFORM set_config('app.audit.via_gateway', '0', true);

  SELECT * INTO v_cur FROM public.shifts WHERE id = p_shift_id;

  -- scope guard, destination (20261011 access matrix): an edit that moves the
  -- shift to another place needs the same authority there. Raising undoes the
  -- write.
  IF v_caller IS NOT NULL
     AND (v_cur.organization_id, v_cur.department_id, v_cur.sub_department_id)
         IS DISTINCT FROM (v_pre.organization_id, v_pre.department_id, v_pre.sub_department_id)
     AND NOT public.user_has_action_in_scope('shift.edit', v_cur.organization_id, v_cur.department_id, v_cur.sub_department_id) THEN
    RAISE EXCEPTION 'Not authorised: shift.edit is not granted to you where this shift is moving'
      USING ERRCODE = '42501';
  END IF;

  IF COALESCE((v_write->>'applied')::boolean, false) IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'WRITE_REJECTED',
      'note', v_write->>'note',
      'version', v_cur.version,
      'state', public.get_shift_fsm_state(
        v_cur.lifecycle_status, v_cur.assignment_status, v_cur.assignment_outcome,
        v_cur.trading_status, v_cur.is_cancelled, v_cur.bidding_status)
    );
  END IF;

  v_to_state := public.get_shift_fsm_state(
    v_cur.lifecycle_status, v_cur.assignment_status, v_cur.assignment_outcome,
    v_cur.trading_status, v_cur.is_cancelled, v_cur.bidding_status);

  IF p_op IN ('edit', 'move') THEN
    IF v_pre.start_time IS DISTINCT FROM v_cur.start_time THEN
      v_changes := v_changes || jsonb_build_object('start_time',
        jsonb_build_object('old', to_jsonb(v_pre.start_time), 'new', to_jsonb(v_cur.start_time)));
    END IF;
    IF v_pre.end_time IS DISTINCT FROM v_cur.end_time THEN
      v_changes := v_changes || jsonb_build_object('end_time',
        jsonb_build_object('old', to_jsonb(v_pre.end_time), 'new', to_jsonb(v_cur.end_time)));
    END IF;
    IF v_pre.shift_date IS DISTINCT FROM v_cur.shift_date THEN
      v_changes := v_changes || jsonb_build_object('shift_date',
        jsonb_build_object('old', to_jsonb(v_pre.shift_date), 'new', to_jsonb(v_cur.shift_date)));
    END IF;
    IF v_pre.paid_break_minutes IS DISTINCT FROM v_cur.paid_break_minutes THEN
      v_changes := v_changes || jsonb_build_object('paid_break_minutes',
        jsonb_build_object('old', to_jsonb(v_pre.paid_break_minutes), 'new', to_jsonb(v_cur.paid_break_minutes)));
    END IF;
    IF v_pre.unpaid_break_minutes IS DISTINCT FROM v_cur.unpaid_break_minutes THEN
      v_changes := v_changes || jsonb_build_object('unpaid_break_minutes',
        jsonb_build_object('old', to_jsonb(v_pre.unpaid_break_minutes), 'new', to_jsonb(v_cur.unpaid_break_minutes)));
    END IF;
    IF v_pre.notes IS DISTINCT FROM v_cur.notes THEN
      v_changes := v_changes || jsonb_build_object('notes',
        jsonb_build_object('old', to_jsonb(v_pre.notes), 'new', to_jsonb(v_cur.notes)));
    END IF;
    IF v_pre.role_id IS DISTINCT FROM v_cur.role_id THEN
      v_changes := v_changes || jsonb_build_object('role_id',
        jsonb_build_object('old', to_jsonb(v_pre.role_id), 'new', to_jsonb(v_cur.role_id)));
    END IF;
    IF v_pre.sub_department_id IS DISTINCT FROM v_cur.sub_department_id THEN
      v_changes := v_changes || jsonb_build_object('sub_department_id',
        jsonb_build_object('old', to_jsonb(v_pre.sub_department_id), 'new', to_jsonb(v_cur.sub_department_id)));
    END IF;
    IF v_pre.remuneration_level IS DISTINCT FROM v_cur.remuneration_level THEN
      v_changes := v_changes || jsonb_build_object('remuneration_level',
        jsonb_build_object('old', to_jsonb(v_pre.remuneration_level), 'new', to_jsonb(v_cur.remuneration_level)));
    END IF;
    IF v_pre.group_type IS DISTINCT FROM v_cur.group_type THEN
      v_changes := v_changes || jsonb_build_object('group_type',
        jsonb_build_object('old', to_jsonb(v_pre.group_type), 'new', to_jsonb(v_cur.group_type)));
    END IF;
    IF v_pre.sub_group_name IS DISTINCT FROM v_cur.sub_group_name THEN
      v_changes := v_changes || jsonb_build_object('sub_group_name',
        jsonb_build_object('old', to_jsonb(v_pre.sub_group_name), 'new', to_jsonb(v_cur.sub_group_name)));
    END IF;
    IF v_pre.display_order IS DISTINCT FROM v_cur.display_order THEN
      v_changes := v_changes || jsonb_build_object('display_order',
        jsonb_build_object('old', to_jsonb(v_pre.display_order), 'new', to_jsonb(v_cur.display_order)));
    END IF;
    IF v_pre.shift_group_id IS DISTINCT FROM v_cur.shift_group_id THEN
      v_changes := v_changes || jsonb_build_object('shift_group_id',
        jsonb_build_object('old', to_jsonb(v_pre.shift_group_id), 'new', to_jsonb(v_cur.shift_group_id)));
    END IF;
    IF v_pre.roster_subgroup_id IS DISTINCT FROM v_cur.roster_subgroup_id THEN
      v_changes := v_changes || jsonb_build_object('roster_subgroup_id',
        jsonb_build_object('old', to_jsonb(v_pre.roster_subgroup_id), 'new', to_jsonb(v_cur.roster_subgroup_id)));
    END IF;
    IF v_pre.timezone IS DISTINCT FROM v_cur.timezone THEN
      v_changes := v_changes || jsonb_build_object('timezone',
        jsonb_build_object('old', to_jsonb(v_pre.timezone), 'new', to_jsonb(v_cur.timezone)));
    END IF;
    IF v_pre.is_training IS DISTINCT FROM v_cur.is_training THEN
      v_changes := v_changes || jsonb_build_object('is_training',
        jsonb_build_object('old', to_jsonb(v_pre.is_training), 'new', to_jsonb(v_cur.is_training)));
    END IF;
    IF v_pre.required_skills IS DISTINCT FROM v_cur.required_skills THEN
      v_changes := v_changes || jsonb_build_object('required_skills',
        jsonb_build_object('old', to_jsonb(v_pre.required_skills), 'new', to_jsonb(v_cur.required_skills)));
    END IF;
    IF v_pre.required_licenses IS DISTINCT FROM v_cur.required_licenses THEN
      v_changes := v_changes || jsonb_build_object('required_licenses',
        jsonb_build_object('old', to_jsonb(v_pre.required_licenses), 'new', to_jsonb(v_cur.required_licenses)));
    END IF;
    IF v_pre.event_ids IS DISTINCT FROM v_cur.event_ids THEN
      v_changes := v_changes || jsonb_build_object('event_ids',
        jsonb_build_object('old', to_jsonb(v_pre.event_ids), 'new', to_jsonb(v_cur.event_ids)));
    END IF;
    IF v_pre.assigned_employee_id IS DISTINCT FROM v_cur.assigned_employee_id THEN
      v_changes := v_changes || jsonb_build_object('assignment',
        jsonb_build_object('old', to_jsonb(v_pre.assigned_employee_id), 'new', to_jsonb(v_cur.assigned_employee_id)));
    END IF;
  END IF;

  IF v_caller IS NULL THEN
    v_actor_role := 'system';
  ELSIF EXISTS (
          SELECT 1 FROM public.app_access_certificates c
          WHERE c.user_id = v_caller
            AND c.is_active = true
            AND c.access_level IN ('gamma', 'delta', 'epsilon', 'zeta')
        ) THEN
    v_actor_role := 'manager';
  ELSE
    v_actor_role := 'employee';
  END IF;

  v_domain := CASE p_op
                WHEN 'create'        THEN 'lifecycle'
                WHEN 'publish'        THEN 'lifecycle'
                WHEN 'unpublish'      THEN 'lifecycle'
                WHEN 'delete'         THEN 'lifecycle'
                WHEN 'assign'         THEN 'assignment'
                WHEN 'unassign'       THEN 'assignment'
                WHEN 'select_winner'  THEN 'marketplace'
                WHEN 'edit'           THEN 'schedule'
                WHEN 'move'           THEN 'schedule'
                WHEN 'approve_trade'  THEN 'trade'
                WHEN 'reject_trade'   THEN 'trade'
                ELSE 'lifecycle'
              END;

  v_event := CASE
               WHEN p_op = 'assign'        THEN 'ASSIGNED'
               WHEN p_op = 'select_winner' THEN 'ASSIGNED'
               WHEN p_op = 'unpublish'     THEN 'UNASSIGNED'
               WHEN p_op = 'delete' AND v_cur.assigned_employee_id IS NOT NULL
                                           THEN 'CANCELLED'
               ELSE 'OP_APPLIED'
             END::public.shift_event_type;

  INSERT INTO public.shift_events (
    shift_id, employee_id, actor_id, event_type, metadata,
    actor_role, domain, shift_version, idempotency_key
  )
  VALUES (
    p_shift_id,
    v_cur.assigned_employee_id,
    v_caller,
    v_event,
    jsonb_build_object(
      'op',                p_op,
      'reason',            p_payload->>'reason',
      'from_state',        v_state,
      'to_state',          v_to_state,
      'from_version',      p_expected_version,
      'to_version',        v_cur.version,
      'idem',              p_idempotency_key,
      'source',            'sm_apply_shift_op',
      'assignment_source', v_cur.assignment_source,
      'payload',           p_payload,
      'write',             v_write
    )
    || CASE WHEN p_op IN ('edit', 'move')
            THEN jsonb_build_object('changes', v_changes)
            ELSE '{}'::jsonb
       END,
    v_actor_role,
    v_domain,
    v_cur.version,
    p_idempotency_key
  );

  RETURN jsonb_build_object(
    'ok', true,
    'code', 'APPLIED',
    'version', v_cur.version,
    'state', v_to_state
  );

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Error in sm_apply_shift_op (shift=%, op=%): %', p_shift_id, p_op, SQLERRM;
  RETURN jsonb_build_object('ok', false, 'code', 'ERROR', 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."sm_apply_shift_op"("p_shift_id" "uuid", "p_expected_version" integer, "p_op" "text", "p_payload" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_approve_peer_swap"("p_requester_shift_id" "uuid", "p_offered_shift_id" "uuid", "p_requester_id" "uuid", "p_offerer_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_requester_shift shifts%ROWTYPE;
  v_offered_shift shifts%ROWTYPE;
  v_batch uuid := gen_random_uuid();
  v_performer_name text;
  v_performer_role text; 
BEGIN
  SELECT * INTO v_requester_shift FROM shifts WHERE id = p_requester_shift_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Requester shift not found';
  END IF;

  IF p_offered_shift_id IS NOT NULL THEN
    SELECT * INTO v_offered_shift FROM shifts WHERE id = p_offered_shift_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Offered shift not found';
    END IF;
  END IF;

  SELECT 
    COALESCE(full_name, first_name || ' ' || last_name, 'Unknown User'),
    COALESCE(legacy_system_role::text, 'manager') 
  INTO v_performer_name, v_performer_role
  FROM profiles
  WHERE id = auth.uid();

  v_performer_name := COALESCE(v_performer_name, 'Unknown User');
  v_performer_role := COALESCE(v_performer_role, 'manager');
  
  IF v_performer_role NOT IN ('admin', 'manager', 'team_lead', 'team_member') THEN
      v_performer_role := 'manager';
  END IF;

  UPDATE shifts 
  SET assigned_employee_id = p_offerer_id,
      assignment_outcome = 'confirmed',
      updated_at = NOW(),
      trade_requested_at = NULL,
      trading_status = 'NoTrade'
  WHERE id = p_requester_shift_id;

  IF p_offered_shift_id IS NOT NULL THEN
    UPDATE shifts 
    SET assigned_employee_id = p_requester_id,
        assignment_outcome = 'confirmed',
        updated_at = NOW(),
        trade_requested_at = NULL,
        trading_status = 'NoTrade'
    WHERE id = p_offered_shift_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."sm_approve_peer_swap"("p_requester_shift_id" "uuid", "p_offered_shift_id" "uuid", "p_requester_id" "uuid", "p_offerer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_approve_trade"("p_shift_id" "uuid", "p_new_employee_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE 
    v_shift RECORD; 
    v_state TEXT; 
    v_compliance RECORD; 
    v_original UUID;
BEGIN
    SELECT * INTO v_shift FROM shifts WHERE id=p_shift_id AND deleted_at IS NULL FOR UPDATE;
    v_state := get_shift_state_id(p_shift_id);
    v_original := v_shift.assigned_employee_id;
    
    IF v_state != 'S10' THEN 
        RETURN jsonb_build_object('success', false, 'error', 'Not S10'); 
    END IF;
    
    SELECT * INTO v_compliance FROM check_shift_compliance(v_shift.roster_shift_id, p_new_employee_id);
    
    IF v_compliance.compliance_status = 'blocked' THEN
        UPDATE shifts 
        SET trading_status='NoTrade', 
            updated_at=NOW(), 
            last_modified_by=p_user_id 
        WHERE id=p_shift_id;
        
        RETURN jsonb_build_object('success', false, 'error', 'Compliance blocked', 'reverted_to', 'S4');
    END IF;
    
    UPDATE shifts 
    SET assigned_employee_id=p_new_employee_id, 
        assigned_at=NOW(), 
        confirmed_at=NOW(),
        trading_status='NoTrade', 
        eligibility_snapshot=v_compliance.eligibility_snapshot, 
        compliance_checked_at=NOW(),
        updated_at=NOW(), 
        last_modified_by=p_user_id 
    WHERE id=p_shift_id;
    
    RETURN jsonb_build_object('success', true, 'from_state', 'S10', 'to_state', 'S4');
END; 
$$;


ALTER FUNCTION "public"."sm_approve_trade"("p_shift_id" "uuid", "p_new_employee_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_assignment_run_finish"("p_run_id" "uuid", "p_status" "text", "p_summary" "jsonb" DEFAULT NULL::"jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_run    public.assignment_runs%ROWTYPE;
BEGIN
  IF p_status NOT IN ('COMPLETED','PARTIALLY_FAILED','ABORTED') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'BAD_STATUS');
  END IF;
  SELECT * INTO v_run FROM public.assignment_runs WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 'NO_RUN'); END IF;
  IF v_caller IS NOT NULL AND NOT public.aa_user_manages_org(v_caller, v_run.organization_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  UPDATE public.assignment_runs
     SET status = p_status, summary = COALESCE(p_summary, summary), error = p_error, finished_at = now()
   WHERE id = p_run_id;
  INSERT INTO public.assignment_events (run_id, event_type, actor_id, metadata)
  VALUES (p_run_id, 'RUN_FINISHED', v_caller,
          jsonb_build_object('status', p_status, 'summary', p_summary, 'error', p_error));
  RETURN jsonb_build_object('ok', true, 'run_id', p_run_id, 'status', p_status);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'sm_assignment_run_finish error: %', SQLERRM;
  RETURN jsonb_build_object('ok', false, 'code', 'ERROR', 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."sm_assignment_run_finish"("p_run_id" "uuid", "p_status" "text", "p_summary" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_assignment_run_rollback"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_run    public.assignment_runs%ROWTYPE;
  v_dec    RECORD;
  v_shift  public.shifts%ROWTYPE;
  v_state  text;
  v_reverted jsonb := '[]'::jsonb;
  v_skipped  jsonb := '[]'::jsonb;
  v_skip   text;
BEGIN
  SELECT * INTO v_run FROM public.assignment_runs WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 'NO_RUN'); END IF;
  IF v_caller IS NOT NULL AND NOT public.aa_user_manages_org(v_caller, v_run.organization_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF v_run.status NOT IN ('COMPLETED','PARTIALLY_FAILED') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_ROLLBACKABLE', 'status', v_run.status);
  END IF;
  IF v_run.dry_run THEN RETURN jsonb_build_object('ok', false, 'code', 'DRY_RUN_HAS_NO_EFFECT'); END IF;

  FOR v_dec IN
    SELECT * FROM public.assignment_decisions
    WHERE run_id = p_run_id AND outcome = 'ASSIGNED' AND committed = true AND version_after IS NOT NULL
    ORDER BY shift_id ASC
  LOOP
    v_skip := NULL;
    SELECT * INTO v_shift FROM public.shifts WHERE id = v_dec.shift_id FOR UPDATE;
    IF NOT FOUND OR v_shift.deleted_at IS NOT NULL OR v_shift.is_cancelled THEN v_skip := 'GONE';
    ELSIF v_shift.version <> v_dec.version_after THEN v_skip := 'EDITED_SINCE';
    ELSIF v_shift.trading_status <> 'NoTrade' THEN v_skip := 'TRADED_SINCE';
    ELSIF EXTRACT(EPOCH FROM (v_shift.scheduled_start - now())) < 4 * 3600 THEN v_skip := 'TTS_LOCKED';
    END IF;
    IF v_skip IS NOT NULL THEN
      v_skipped := v_skipped || jsonb_build_object('shift_id', v_dec.shift_id, 'reason', v_skip);
      CONTINUE;
    END IF;
    v_state := public.get_shift_fsm_state(
      v_shift.lifecycle_status, v_shift.assignment_status, v_shift.assignment_outcome,
      v_shift.trading_status, v_shift.is_cancelled, v_shift.bidding_status);
    IF v_state <> 'S4' THEN
      v_skipped := v_skipped || jsonb_build_object('shift_id', v_dec.shift_id, 'reason', 'STATE_' || v_state);
      CONTINUE;
    END IF;
    UPDATE public.shift_bids SET status = 'pending', updated_at = now()
     WHERE shift_id = v_dec.shift_id AND employee_id = v_dec.winner_employee_id AND status = 'accepted';
    UPDATE public.shifts SET
      assigned_employee_id = NULL, assigned_at = NULL,
      assignment_status = 'unassigned'::public.shift_assignment_status,
      assignment_outcome = NULL, confirmed_at = NULL,
      bidding_status = 'on_bidding'::public.shift_bidding_status,
      is_on_bidding = TRUE, bidding_enabled = TRUE,
      fulfillment_status = 'bidding'::public.shift_fulfillment_status,
      last_modified_by = v_caller,
      last_modified_reason = 'Auto-assign run rollback ' || p_run_id::text,
      updated_at = now()
    WHERE id = v_dec.shift_id;
    INSERT INTO public.shift_events (shift_id, employee_id, actor_id, event_type, metadata)
    VALUES (v_dec.shift_id, v_dec.winner_employee_id, v_caller, 'UNASSIGNED',
      jsonb_build_object('op', 'run_rollback', 'run_id', p_run_id, 'from_version', v_dec.version_after,
        'idem', extensions.uuid_generate_v5('00000000-0000-0000-0000-0000000000aa'::uuid,
                  p_run_id::text || ':rb:' || v_dec.shift_id::text)));
    INSERT INTO public.assignment_events (run_id, shift_id, event_type, actor_id, metadata)
    VALUES (p_run_id, v_dec.shift_id, 'SHIFT_ROLLBACK', v_caller,
            jsonb_build_object('version_before', v_dec.version_after));
    v_reverted := v_reverted || jsonb_build_object('shift_id', v_dec.shift_id);
  END LOOP;

  UPDATE public.assignment_runs SET status = 'ROLLED_BACK', finished_at = now() WHERE id = p_run_id;
  INSERT INTO public.assignment_events (run_id, event_type, actor_id, metadata)
  VALUES (p_run_id, 'RUN_ROLLED_BACK', v_caller,
          jsonb_build_object('reverted', v_reverted, 'skipped', v_skipped));
  RETURN jsonb_build_object('ok', true, 'run_id', p_run_id, 'status', 'ROLLED_BACK',
                            'reverted', v_reverted, 'skipped', v_skipped);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'sm_assignment_run_rollback error: %', SQLERRM;
  RETURN jsonb_build_object('ok', false, 'code', 'ERROR', 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."sm_assignment_run_rollback"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_assignment_run_start"("p_scope" "jsonb", "p_engine_version" "text", "p_policy_version" integer DEFAULT 1, "p_options" "jsonb" DEFAULT '{}'::"jsonb", "p_dry_run" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_org    uuid := NULLIF(p_scope->>'organization_id','')::uuid;
  v_run    public.assignment_runs%ROWTYPE;
BEGIN
  IF v_org IS NULL THEN RETURN jsonb_build_object('ok', false, 'code', 'MISSING_ORG'); END IF;
  IF v_caller IS NOT NULL AND NOT public.aa_user_manages_org(v_caller, v_org) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  INSERT INTO public.assignment_runs (
    organization_id, department_id, sub_department_id, actor_id, scope,
    dry_run, status, engine_version, policy_version, options, started_at
  ) VALUES (
    v_org, NULLIF(p_scope->>'department_id','')::uuid, NULLIF(p_scope->>'sub_department_id','')::uuid,
    COALESCE(v_caller, '00000000-0000-0000-0000-000000000000'::uuid),
    p_scope, p_dry_run, 'RUNNING', p_engine_version, p_policy_version, p_options, now()
  ) RETURNING * INTO v_run;
  INSERT INTO public.assignment_events (run_id, event_type, actor_id, metadata)
  VALUES (v_run.id, 'RUN_STARTED', v_caller,
          jsonb_build_object('scope', p_scope, 'dry_run', p_dry_run, 'options', p_options));
  RETURN jsonb_build_object('ok', true, 'run_id', v_run.id, 'status', 'RUNNING');
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'sm_assignment_run_start error: %', SQLERRM;
  RETURN jsonb_build_object('ok', false, 'code', 'ERROR', 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."sm_assignment_run_start"("p_scope" "jsonb", "p_engine_version" "text", "p_policy_version" integer, "p_options" "jsonb", "p_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_bulk_assign"("p_shift_ids" "uuid"[], "p_employee_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total_count   int;
  v_success_count int;
  v_user_name     text;
  v_user_role     text;
  v_caller        uuid := auth.uid();
BEGIN
  v_total_count := array_length(p_shift_ids, 1);

  -- ── Authorization (audit fix C1) ─────────────────────────────────────────
  IF v_caller IS NOT NULL AND NOT (
       (EXISTS (
            SELECT 1 FROM public.app_access_certificates c
            WHERE c.user_id = v_caller
              AND c.is_active = true
              AND c.access_level IN ('gamma', 'delta', 'epsilon', 'zeta')
          )
       -- scope guard (20261011 access matrix): every shift in the batch must
       -- be one the caller may assign in its own place.
       AND NOT EXISTS (
            SELECT 1 FROM public.shifts s
             WHERE s.id = ANY (COALESCE(p_shift_ids, '{}'))
               AND NOT public.user_has_action_in_scope('shift.assign', s.organization_id, s.department_id, s.sub_department_id)))
     ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Not authorized to assign shifts',
      'total_requested', COALESCE(v_total_count, 0),
      'success_count', 0,
      'failure_count', COALESCE(v_total_count, 0)
    );
  END IF;

  IF p_user_id IS NOT NULL THEN
    SELECT COALESCE(first_name || ' ' || COALESCE(last_name, ''), email),
           left(lower(legacy_system_role::text), 50)
    INTO v_user_name, v_user_role FROM public.profiles WHERE id = p_user_id;
  ELSE
    v_user_name := 'System'; v_user_role := 'system_automation';
  END IF;

  WITH updated_rows AS (
    UPDATE public.shifts s SET
      assigned_employee_id = p_employee_id,
      assignment_status    = 'assigned'::public.shift_assignment_status,
      assignment_outcome   = CASE WHEN s.lifecycle_status = 'Published'
                                THEN 'confirmed'::public.shift_assignment_outcome
                                ELSE s.assignment_outcome END,
      confirmed_at         = CASE WHEN s.lifecycle_status = 'Published' THEN NOW() ELSE s.confirmed_at END,
      updated_at           = NOW(),
      last_modified_by     = p_user_id
    WHERE s.id = ANY(p_shift_ids)
      AND s.deleted_at IS NULL
      -- Lost-update guard: never overwrite a shift already held by a different
      -- employee. Re-checked after row-lock under READ COMMITTED, so two
      -- concurrent callers cannot both claim the same open shift.
      AND (s.assigned_employee_id IS NULL OR s.assigned_employee_id = p_employee_id)
    RETURNING s.id, s.lifecycle_status
  )
  SELECT count(*) INTO v_success_count FROM updated_rows;

  RETURN jsonb_build_object('success', true, 'total_requested', v_total_count,
    'success_count', v_success_count, 'failure_count', v_total_count - v_success_count,
    'message', format('Successfully assigned %s of %s shifts', v_success_count, v_total_count));

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Error in sm_bulk_assign: %', SQLERRM;
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END; $$;


ALTER FUNCTION "public"."sm_bulk_assign"("p_shift_ids" "uuid"[], "p_employee_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_bulk_assign_atomic"("p_assignments" "jsonb", "p_user_id" "uuid" DEFAULT "auth"."uid"(), "p_idempotency_key" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_caller        uuid := auth.uid();
    v_user_name     text;
    v_user_role     text;
    v_pair          jsonb;
    v_employee_id   uuid;
    v_shift_ids     uuid[];
    v_pair_total    int;
    v_pair_success  int;
    v_pair_conflicts jsonb;
    v_total_requested   int := 0;
    v_total_success     int := 0;
    v_total_conflict    int := 0;
    v_per_employee      jsonb := '[]'::jsonb;
    v_all_conflicts     jsonb := '[]'::jsonb;
    v_updated_ids       uuid[];
    v_shift_id          uuid;
    v_final_result      jsonb;
    v_stored_result     jsonb;
BEGIN
    PERFORM set_config('app.audit.actor', 'autoscheduler', true);

    IF p_idempotency_key IS NOT NULL THEN
        SELECT result INTO v_stored_result
        FROM public.bulk_assign_idempotency
        WHERE key = p_idempotency_key;
        IF FOUND THEN
            RETURN v_stored_result;
        END IF;
    END IF;

    -- P0 fix: was "v_caller IS NOT NULL AND NOT (...)", which skipped
    -- this check entirely for any caller with no JWT subject --
    -- including an unauthenticated anon-key request. Trust only a
    -- genuine service_role JWT unconditionally; every other caller
    -- (including one with a null uid) must pass the role check.
    IF auth.role() IS DISTINCT FROM 'service_role' AND NOT (
           (EXISTS (
                SELECT 1 FROM public.app_access_certificates c
                WHERE c.user_id = v_caller
                  AND c.is_active = true
                  AND c.access_level IN ('gamma', 'delta', 'epsilon', 'zeta')
              )
           -- scope guard (20261011 access matrix): every shift in every pair
           -- must be one the caller may assign in its own place.
           AND NOT EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(COALESCE(p_assignments, '[]'::jsonb)) AS pr(v),
                       jsonb_array_elements_text(COALESCE(pr.v->'shift_ids', '[]'::jsonb)) AS e(id)
                  JOIN public.shifts s ON s.id = e.id::uuid
                 WHERE NOT public.user_has_action_in_scope('shift.assign', s.organization_id, s.department_id, s.sub_department_id)))
         ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Not authorized to assign shifts',
            'total_requested', 0,
            'success_count', 0,
            'conflict_count', 0,
            'conflicts', '[]'::jsonb,
            'per_employee', '[]'::jsonb
        );
    END IF;

    IF p_user_id IS NOT NULL THEN
        SELECT COALESCE(first_name || ' ' || COALESCE(last_name, ''), email),
               left(lower(legacy_system_role::text), 50)
        INTO v_user_name, v_user_role
        FROM public.profiles
        WHERE id = p_user_id;
    ELSE
        v_user_name := 'System';
        v_user_role := 'system_automation';
    END IF;

    FOR v_pair IN SELECT * FROM jsonb_array_elements(p_assignments)
    LOOP
        v_employee_id := (v_pair->>'employee_id')::uuid;
        v_shift_ids   := ARRAY(
            SELECT (elem::text)::uuid
            FROM jsonb_array_elements_text(v_pair->'shift_ids') AS elem
        );
        v_pair_total    := array_length(v_shift_ids, 1);
        v_pair_success  := 0;
        v_pair_conflicts := '[]'::jsonb;
        v_updated_ids   := '{}';

        IF v_pair_total IS NULL OR v_pair_total = 0 THEN
            CONTINUE;
        END IF;

        v_total_requested := v_total_requested + v_pair_total;

        WITH updated_rows AS (
            UPDATE public.shifts s SET
                assigned_employee_id = v_employee_id,
                assignment_status    = 'assigned'::public.shift_assignment_status,
                assignment_outcome   = CASE
                                         WHEN s.lifecycle_status = 'Published'
                                         THEN 'confirmed'::public.shift_assignment_outcome
                                         ELSE s.assignment_outcome
                                       END,
                confirmed_at         = CASE
                                         WHEN s.lifecycle_status = 'Published'
                                         THEN NOW()
                                         ELSE s.confirmed_at
                                       END,
                updated_at           = NOW(),
                last_modified_by     = p_user_id
            WHERE s.id = ANY(v_shift_ids)
              AND s.deleted_at IS NULL
              AND (s.assigned_employee_id IS NULL OR s.assigned_employee_id = v_employee_id)
            RETURNING s.id
        )
        SELECT array_agg(id) INTO v_updated_ids FROM updated_rows;

        IF v_updated_ids IS NULL THEN
            v_updated_ids := '{}';
        END IF;

        v_pair_success := array_length(v_updated_ids, 1);
        IF v_pair_success IS NULL THEN v_pair_success := 0; END IF;

        FOREACH v_shift_id IN ARRAY v_shift_ids LOOP
            IF NOT (v_shift_id = ANY(v_updated_ids)) THEN
                v_pair_conflicts := v_pair_conflicts || to_jsonb(v_shift_id::text);
                v_all_conflicts  := v_all_conflicts  || to_jsonb(v_shift_id::text);
            END IF;
        END LOOP;

        v_total_success  := v_total_success  + v_pair_success;
        v_total_conflict := v_total_conflict + (v_pair_total - v_pair_success);

        v_per_employee := v_per_employee || jsonb_build_object(
            'employee_id', v_employee_id,
            'committed',   v_pair_success,
            'conflicts',   v_pair_conflicts
        );
    END LOOP;

    v_final_result := jsonb_build_object(
        'success',         true,
        'total_requested', v_total_requested,
        'success_count',   v_total_success,
        'conflict_count',  v_total_conflict,
        'conflicts',       v_all_conflicts,
        'per_employee',    v_per_employee
    );

    IF p_idempotency_key IS NOT NULL THEN
        INSERT INTO public.bulk_assign_idempotency (key, result)
        VALUES (p_idempotency_key, v_final_result)
        ON CONFLICT (key) DO NOTHING;
    END IF;

    RETURN v_final_result;

EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Error in sm_bulk_assign_atomic: %', SQLERRM;
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'total_requested', v_total_requested,
        'success_count', 0,
        'conflict_count', 0,
        'conflicts', '[]'::jsonb,
        'per_employee', '[]'::jsonb
    );
END;
$$;


ALTER FUNCTION "public"."sm_bulk_assign_atomic"("p_assignments" "jsonb", "p_user_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_bulk_close_bidding"("p_shift_ids" "uuid"[], "p_reason" "text", "p_actor_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_shift_id uuid;
  v_result jsonb;
  v_success int := 0;
  v_failure int := 0;
  v_results jsonb := '[]'::jsonb;
BEGIN
  FOREACH v_shift_id IN ARRAY p_shift_ids LOOP
    BEGIN
      v_result := sm_close_bidding(v_shift_id, p_reason, p_actor_id);

      IF (v_result->>'success')::boolean THEN
        v_success := v_success + 1;
        v_results := v_results || jsonb_build_object(
          'shift_id', v_shift_id,
          'success', true,
          'to_state', v_result->>'to_state'
        );
      ELSE
        v_failure := v_failure + 1;
        v_results := v_results || jsonb_build_object(
          'shift_id', v_shift_id,
          'success', false,
          'error', v_result->>'error'
        );
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_failure := v_failure + 1;
      v_results := v_results || jsonb_build_object(
        'shift_id', v_shift_id,
        'success', false,
        'error', SQLERRM
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success_count', v_success,
    'failure_count', v_failure,
    'results', v_results
  );
END;
$$;


ALTER FUNCTION "public"."sm_bulk_close_bidding"("p_shift_ids" "uuid"[], "p_reason" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_bulk_delete_shifts"("p_shift_ids" "uuid"[], "p_deleted_by" "uuid" DEFAULT "auth"."uid"(), "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_id uuid;
  v_shift public.shifts%ROWTYPE;
  v_refusal text;
  v_deleted uuid[] := '{}';
  v_failed jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.sm_request_is_system() AND (auth.uid() IS NULL OR EXISTS (
       -- scope guard (20261011 access matrix): every shift in the batch
       SELECT 1 FROM public.shifts s
        WHERE s.id = ANY (COALESCE(p_shift_ids, '{}'))
          AND NOT public.user_has_action_in_scope('shift.delete', s.organization_id, s.department_id, s.sub_department_id))) THEN
    RETURN jsonb_build_object('success', false, 'error', 'You are not allowed to delete shifts.',
      'total_requested', COALESCE(array_length(p_shift_ids, 1), 0), 'success_count', 0);
  END IF;

  FOREACH v_id IN ARRAY COALESCE(p_shift_ids, '{}') LOOP
    SELECT * INTO v_shift FROM public.shifts WHERE id = v_id FOR UPDATE;
    IF NOT FOUND THEN
      v_failed := v_failed || jsonb_build_object('id', v_id, 'reason', 'Shift not found');
      CONTINUE;
    END IF;
    v_refusal := public._shift_delete_refusal(v_shift);
    IF v_refusal IS NOT NULL THEN
      v_failed := v_failed || jsonb_build_object('id', v_id, 'reason',
        CASE v_refusal WHEN 'SHIFT_WORKED' THEN 'Already worked' ELSE 'Already started' END);
      CONTINUE;
    END IF;
    DELETE FROM public.shifts WHERE id = v_id;
    v_deleted := v_deleted || v_id;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'total_requested', COALESCE(array_length(p_shift_ids, 1), 0),
    'success_count', COALESCE(array_length(v_deleted, 1), 0),
    'failure_count', jsonb_array_length(v_failed),
    'deleted_ids', to_jsonb(v_deleted),
    'failed', v_failed
  );
END;
$$;


ALTER FUNCTION "public"."sm_bulk_delete_shifts"("p_shift_ids" "uuid"[], "p_deleted_by" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_bulk_emergency_assign"("p_assignments" "jsonb", "p_actor_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_item jsonb;
  v_result jsonb;
  v_success int := 0;
  v_failure int := 0;
  v_results jsonb := '[]'::jsonb;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_assignments) LOOP
    BEGIN
      v_result := sm_emergency_assign(
        (v_item->>'shift_id')::uuid,
        (v_item->>'employee_id')::uuid,
        COALESCE(v_item->>'reason', 'Bulk emergency assign'),
        p_actor_id
      );

      IF (v_result->>'success')::boolean THEN
        v_success := v_success + 1;
        v_results := v_results || jsonb_build_object(
          'shift_id', v_item->>'shift_id',
          'success', true,
          'to_state', v_result->>'to_state'
        );
      ELSE
        v_failure := v_failure + 1;
        v_results := v_results || jsonb_build_object(
          'shift_id', v_item->>'shift_id',
          'success', false,
          'error', v_result->>'error'
        );
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_failure := v_failure + 1;
      v_results := v_results || jsonb_build_object(
        'shift_id', v_item->>'shift_id',
        'success', false,
        'error', SQLERRM
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success_count', v_success,
    'failure_count', v_failure,
    'results', v_results
  );
END;
$$;


