CREATE OR REPLACE FUNCTION "public"."sm_cert_at_least"("p_min" "public"."access_level", "p_user" "uuid" DEFAULT "auth"."uid"(), "p_org" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.app_access_certificates ac
     WHERE ac.user_id = p_user AND ac.is_active = true
       AND ac.access_level >= p_min
       AND (p_org IS NULL OR ac.organization_id = p_org OR ac.organization_id IS NULL)
  );
$$;


ALTER FUNCTION "public"."sm_cert_at_least"("p_min" "public"."access_level", "p_user" "uuid", "p_org" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sm_cert_at_least"("p_min" "public"."access_level", "p_user" "uuid", "p_org" "uuid") IS 'Does this user hold an ACTIVE certificate at or above a level, optionally within an organization? The single definition behind is_admin, is_manager_or_above, user_has_delta_access and aa_user_manages_org. Uses >= on the access_level enum, whose declaration order IS the ladder.';



CREATE OR REPLACE FUNCTION "public"."sm_clear_template_application"("p_roster_id" "uuid", "p_template_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_deleted_count INTEGER := 0;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_roster_action(p_roster_id, 'roster.edit');
    -- 1. Delete shifts associated with this template in this roster
    -- ONLY those marked as from template to safe-guard manual edits (though template_id should usually be enough)
    DELETE FROM public.shifts
    WHERE roster_id = p_roster_id
      AND template_id = p_template_id
      AND is_from_template = true
      AND deleted_at IS NULL;
    
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

    -- 2. Remove the tracking record
    DELETE FROM public.roster_template_applications
    WHERE roster_id = p_roster_id
      AND template_id = p_template_id;

    -- 3. Log the action (Optional but good practice)
    -- We could add an audit event here if desired.

    RETURN jsonb_build_object(
        'success', true,
        'shifts_deleted', v_deleted_count
    );
END;
$$;


ALTER FUNCTION "public"."sm_clear_template_application"("p_roster_id" "uuid", "p_template_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_clock_in"("p_shift_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_shift RECORD; v_state text; v_name text; v_role text;
BEGIN
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted'); END IF;

  -- P0 fix: bind to the authenticated caller (or a manager acting on
  -- an employee's behalf), and require the target employee to
  -- actually be the one assigned to this shift.
  IF p_user_id IS DISTINCT FROM auth.uid() AND NOT public.is_manager_or_above() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized to clock in on behalf of this employee');
  END IF;
  IF v_shift.assigned_employee_id IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Shift is not assigned to this employee');
  END IF;

  SELECT COALESCE(first_name||' '||COALESCE(last_name,''), email), COALESCE(left(lower(legacy_system_role::text),50),'employee')
    INTO v_name, v_role FROM public.profiles WHERE id = p_user_id;
  v_name := COALESCE(v_name, 'System'); v_role := COALESCE(v_role, 'employee');
  v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status, v_shift.assignment_outcome, v_shift.trading_status, v_shift.is_cancelled);
  IF v_state NOT IN ('S4', 'S9', 'S10') THEN RETURN jsonb_build_object('success', false, 'error', format('sm_clock_in requires state S4, S9 or S10, current state is %s', v_state)); END IF;
  UPDATE public.shifts SET
    lifecycle_status = 'InProgress'::public.shift_lifecycle, trading_status = 'NoTrade'::public.shift_trading,
    last_modified_by = p_user_id, updated_at = NOW()
  WHERE id = p_shift_id;
  -- shift_audit_events insert removed
  RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S11');
END; $$;


ALTER FUNCTION "public"."sm_clock_in"("p_shift_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_clock_out_shift"("p_shift_id" "uuid", "p_user_id" "uuid", "p_lat" double precision DEFAULT NULL::double precision, "p_lon" double precision DEFAULT NULL::double precision) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_shift         shifts%ROWTYPE;
  v_org           organizations%ROWTYPE;
  v_now           TIMESTAMPTZ := clock_timestamp();
  v_distance_m    DOUBLE PRECISION;
  v_net_minutes   NUMERIC;
  v_early_out     BOOLEAN;
  v_earth_radius  CONSTANT DOUBLE PRECISION := 6371000;
  v_lat1_rad      DOUBLE PRECISION;
  v_lat2_rad      DOUBLE PRECISION;
  v_dlat          DOUBLE PRECISION;
  v_dlon          DOUBLE PRECISION;
  v_a             DOUBLE PRECISION;
  v_from_state    TEXT;
  v_to_state      TEXT;
BEGIN
  SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Shift not found');
  END IF;

  -- P0 fix: see sm_clock_in for rationale.
  IF p_user_id IS DISTINCT FROM auth.uid() AND NOT public.is_manager_or_above() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized to clock out on behalf of this employee');
  END IF;
  IF v_shift.assigned_employee_id IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Shift is not assigned to this employee');
  END IF;

  IF v_shift.attendance_status NOT IN ('checked_in', 'late') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Must clock in before clocking out');
  END IF;

  IF v_shift.actual_end IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Already clocked out');
  END IF;

  IF p_lat IS NULL OR p_lon IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Location required to clock out');
  END IF;

  SELECT * INTO v_org FROM organizations WHERE id = v_shift.organization_id;
  IF FOUND AND v_org.venue_lat IS NOT NULL AND v_org.venue_lon IS NOT NULL THEN
    v_lat1_rad := radians(v_org.venue_lat);
    v_lat2_rad := radians(p_lat);
    v_dlat     := radians(p_lat - v_org.venue_lat);
    v_dlon     := radians(p_lon - v_org.venue_lon);
    v_a        := sin(v_dlat / 2)^2
                  + cos(v_lat1_rad) * cos(v_lat2_rad) * sin(v_dlon / 2)^2;
    v_distance_m := v_earth_radius * 2 * atan2(sqrt(v_a), sqrt(1 - v_a));
    IF v_distance_m > 100 THEN
      RETURN jsonb_build_object(
        'success',    false,
        'error',      'You are too far from the venue to clock out',
        'distance_m', round(v_distance_m::NUMERIC, 1)
      );
    END IF;
  ELSE
    v_distance_m := 0;
  END IF;

  v_net_minutes := EXTRACT(EPOCH FROM (v_now - v_shift.actual_start)) / 60.0;

  v_early_out := v_shift.end_at IS NOT NULL AND v_now < v_shift.end_at - INTERVAL '5 minutes';

  v_from_state := public.get_shift_fsm_state(
    v_shift.lifecycle_status, v_shift.assignment_status,
    v_shift.assignment_outcome, v_shift.trading_status,
    v_shift.is_cancelled, v_shift.bidding_status
  );

  UPDATE shifts SET
    actual_end         = v_now,
    actual_net_minutes = round(v_net_minutes::NUMERIC, 0),
    lifecycle_status   = 'Completed',
    updated_at         = v_now
  WHERE id = p_shift_id;

  v_to_state := public.get_shift_fsm_state(
    'Completed', v_shift.assignment_status,
    v_shift.assignment_outcome, v_shift.trading_status,
    v_shift.is_cancelled, v_shift.bidding_status
  );

  INSERT INTO public.shift_events (
    shift_id, employee_id, actor_id, event_type, event_time, metadata, actor_role, domain
  ) VALUES (
    p_shift_id,
    v_shift.assigned_employee_id,
    p_user_id,
    CASE WHEN v_early_out THEN 'EARLY_OUT' ELSE 'OP_APPLIED' END::public.shift_event_type,
    v_now,
    jsonb_build_object(
      'op', 'clock_out',
      'domain', 'attendance',
      'departure', CASE
                     WHEN v_early_out THEN 'early'
                     WHEN v_shift.end_at IS NOT NULL AND v_now > v_shift.end_at + INTERVAL '5 minutes' THEN 'late'
                     ELSE 'on_time'
                   END,
      'net_minutes', round(v_net_minutes::NUMERIC, 0),
      'from_state', v_from_state,
      'to_state',   v_to_state,
      'source', 'sm_clock_out_shift'
    ),
    'employee',
    'attendance'
  )
  ON CONFLICT (shift_id, employee_id, event_type, event_time) DO NOTHING;

  RETURN jsonb_build_object(
    'success',          true,
    'actual_end',       v_now,
    'actual_net_minutes', round(v_net_minutes::NUMERIC, 0),
    'early_out',        v_early_out,
    'distance_m',       round(v_distance_m::NUMERIC, 1)
  );
END;
$$;


ALTER FUNCTION "public"."sm_clock_out_shift"("p_shift_id" "uuid", "p_user_id" "uuid", "p_lat" double precision, "p_lon" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_close_bidding"("p_shift_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_state TEXT;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_shift_action(p_shift_id, 'bid.close');
    v_state := get_shift_state_id(p_shift_id);

    IF v_state NOT IN ('S5', 'S6') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error',   format('Cannot close bidding from state %s (must be S5 or S6)', v_state)
        );
    END IF;

    UPDATE public.shifts
    SET
        lifecycle_status     = 'Draft',
        bidding_status       = 'not_on_bidding',
        is_on_bidding        = FALSE,
        locked_at            = NULL,
        updated_at           = NOW(),
        last_modified_by     = p_user_id,
        last_modified_reason = COALESCE(p_reason, 'Bidding closed manually — reverted to draft')
    WHERE id = p_shift_id
      AND deleted_at IS NULL;

    RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S1');

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'code', SQLSTATE);
END;
$$;


ALTER FUNCTION "public"."sm_close_bidding"("p_shift_id" "uuid", "p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_complete_shift"("p_shift_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_shift RECORD; v_state text;
BEGIN
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted'); END IF;
  
  v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status, v_shift.assignment_outcome, v_shift.trading_status, v_shift.is_cancelled);
  IF v_state != 'S11' THEN
    RETURN jsonb_build_object('success', false, 'error', format('sm_complete_shift requires state S11 (InProgress), current state is %s', v_state));
  END IF;
  
  UPDATE public.shifts SET
    lifecycle_status = 'Completed'::public.shift_lifecycle,
    last_modified_by = p_user_id,
    updated_at       = NOW()
  WHERE id = p_shift_id;
  
  RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S13');
END; $$;


ALTER FUNCTION "public"."sm_complete_shift"("p_shift_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_create_shift"("p_shift_data" "jsonb", "p_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_shift_id uuid;
    v_roster_id uuid;
    v_roster_subgroup_id uuid;
    v_shift_group_id uuid;
    v_sub_group_name text;
    v_creation_source text;
    v_assignment_source text;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_shift_data_action(p_shift_data, 'shift.create');
    v_roster_id          := (p_shift_data->>'roster_id')::uuid;
    v_roster_subgroup_id := (p_shift_data->>'roster_subgroup_id')::uuid;
    v_shift_group_id     := (p_shift_data->>'shift_group_id')::uuid;
    v_sub_group_name     := p_shift_data->>'sub_group_name';

    v_creation_source := COALESCE(
        p_shift_data->>'creation_source',
        CASE WHEN COALESCE((p_shift_data->>'is_from_template')::boolean, false) THEN 'template' ELSE 'manual' END
    );

    v_assignment_source := CASE
        WHEN (p_shift_data->>'assigned_employee_id') IS NOT NULL
        THEN COALESCE(p_shift_data->>'assignment_source', 'direct')
        ELSE NULL
    END;

    IF v_roster_id IS NULL THEN
        RAISE EXCEPTION 'Roster ID is required';
    END IF;

    IF v_roster_subgroup_id IS NULL AND v_shift_group_id IS NOT NULL AND v_sub_group_name IS NOT NULL THEN
        SELECT id INTO v_roster_subgroup_id
        FROM roster_subgroups
        WHERE roster_group_id = v_shift_group_id
          AND (LOWER(name) = LOWER(v_sub_group_name)
               OR LOWER(name) = LOWER(REPLACE(v_sub_group_name, '_', ' ')))
        LIMIT 1;

        IF v_roster_subgroup_id IS NULL THEN
            INSERT INTO public.roster_subgroups (
                roster_group_id,
                name,
                sort_order
            ) VALUES (
                v_shift_group_id,
                v_sub_group_name,
                999
            )
            RETURNING id INTO v_roster_subgroup_id;
        END IF;
    END IF;

    PERFORM set_config('app.audit.via_gateway', '1', true);

    INSERT INTO shifts (
        roster_id, department_id, shift_date, roster_date, start_time, end_time,
        organization_id, sub_department_id, group_type, sub_group_name, display_order,
        shift_group_id, roster_subgroup_id, role_id, remuneration_level,
        paid_break_minutes, unpaid_break_minutes, break_minutes, timezone,
        assigned_employee_id, required_skills, required_licenses, event_ids, tags, notes,
        template_id, template_group, template_sub_group, is_from_template, template_instance_id,
        lifecycle_status, created_by_user_id, creation_source, assignment_source,
        target_employment_type, target_requires_flexible, is_training,
        created_at, updated_at
    ) VALUES (
        v_roster_id,
        (p_shift_data->>'department_id')::uuid,
        (p_shift_data->>'shift_date')::date,
        (p_shift_data->>'roster_date')::date,
        (p_shift_data->>'start_time')::time,
        (p_shift_data->>'end_time')::time,
        (p_shift_data->>'organization_id')::uuid,
        (p_shift_data->>'sub_department_id')::uuid,
        (p_shift_data->>'group_type')::template_group_type,
        (p_shift_data->>'sub_group_name'),
        COALESCE((p_shift_data->>'display_order')::integer, 0),
        v_shift_group_id,
        v_roster_subgroup_id,
        (p_shift_data->>'role_id')::uuid,
        (p_shift_data->>'remuneration_level')::smallint,
        COALESCE((p_shift_data->>'paid_break_minutes')::integer, 0),
        COALESCE((p_shift_data->>'unpaid_break_minutes')::integer, 0),
        COALESCE((p_shift_data->>'break_minutes')::integer, 0),
        COALESCE(p_shift_data->>'timezone', 'Australia/Sydney'),
        (p_shift_data->>'assigned_employee_id')::uuid,
        COALESCE(p_shift_data->'required_skills', '[]'::jsonb),
        COALESCE(p_shift_data->'required_licenses', '[]'::jsonb),
        COALESCE(p_shift_data->'event_ids', '[]'::jsonb),
        COALESCE(p_shift_data->'tags', '[]'::jsonb),
        p_shift_data->>'notes',
        (p_shift_data->>'template_id')::uuid,
        (p_shift_data->>'template_group')::template_group_type,
        p_shift_data->>'template_sub_group',
        COALESCE((p_shift_data->>'is_from_template')::boolean, false),
        (p_shift_data->>'template_instance_id')::uuid,
        'Draft'::shift_lifecycle,
        p_user_id,
        v_creation_source,
        v_assignment_source,
        NULLIF(p_shift_data->>'target_employment_type', ''),
        COALESCE((p_shift_data->>'target_requires_flexible')::boolean, false),
        COALESCE((p_shift_data->>'is_training')::boolean, false),
        NOW(), NOW()
    )
    RETURNING id INTO v_shift_id;

    PERFORM set_config('app.audit.via_gateway', '0', true);

    INSERT INTO public.shift_events (
        shift_id, employee_id, actor_id, event_type, metadata, actor_role, domain
    ) VALUES (
        v_shift_id,
        (p_shift_data->>'assigned_employee_id')::uuid,
        p_user_id,
        'OP_APPLIED'::public.shift_event_type,
        jsonb_build_object(
            'op', 'create',
            'domain', 'lifecycle',
            'from_state', NULL,
            'to_state', CASE WHEN (p_shift_data->>'assigned_employee_id') IS NOT NULL THEN 'S2' ELSE 'S1' END,
            'source', 'sm_create_shift',
            'creation_source', v_creation_source,
            'assigned_employee_id', (p_shift_data->>'assigned_employee_id')::uuid,
            'assignment_source', v_assignment_source
        ),
        CASE WHEN p_user_id IS NULL THEN 'system' ELSE 'manager' END,
        'lifecycle'
    );

    RETURN v_shift_id;
END;
$$;


ALTER FUNCTION "public"."sm_create_shift"("p_shift_data" "jsonb", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_create_swap_request"("p_requester_shift_id" "uuid", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_shift   shifts%ROWTYPE;
  v_start   timestamptz;
  v_swap_id uuid;
BEGIN
  IF v_caller IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Not authenticated', 'code', 'UNAUTHENTICATED');
  END IF;

  SELECT * INTO v_shift FROM shifts WHERE id = p_requester_shift_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Shift not found', 'code', 'SHIFT_NOT_FOUND');
  END IF;

  IF v_shift.assigned_employee_id IS DISTINCT FROM v_caller AND NOT public.can_act_on_shift('swap.approve', v_shift.id) THEN
    RETURN json_build_object('success', false, 'error', 'You are not assigned to this shift', 'code', 'FORBIDDEN');
  END IF;

  v_start := COALESCE(
    v_shift.start_at,
    (v_shift.shift_date::text || ' ' || v_shift.start_time::text)::timestamp
      AT TIME ZONE COALESCE(v_shift.timezone, 'Australia/Sydney')
  );
  IF v_start IS NOT NULL AND v_start - now() < interval '4 hours' THEN
    RETURN json_build_object('success', false, 'error', 'Time locked: shift starts in < 4h', 'code', 'TIME_LOCKED');
  END IF;

  IF EXISTS (
    SELECT 1 FROM shift_swaps
    WHERE requester_shift_id = p_requester_shift_id
      AND status IN ('OPEN', 'MANAGER_PENDING')
  ) THEN
    RETURN json_build_object('success', false, 'error', 'An active swap already exists for this shift', 'code', 'SWAP_EXISTS');
  END IF;

  INSERT INTO shift_swaps (requester_id, requester_shift_id, target_id, reason, status)
  VALUES (v_caller, p_requester_shift_id, p_target_id, p_reason, 'OPEN')
  RETURNING id INTO v_swap_id;

  UPDATE shifts
  SET trading_status = 'TradeRequested', trade_requested_at = now()
  WHERE id = p_requester_shift_id;

  RETURN json_build_object('success', true, 'swap_id', v_swap_id);
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM, 'code', SQLSTATE);
END;
$$;


ALTER FUNCTION "public"."sm_create_swap_request"("p_requester_shift_id" "uuid", "p_target_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_decline_offer"("p_shift_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_shift RECORD;
    v_state_id TEXT;
    v_performer_name TEXT;
    v_new_iter INT;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_assignee_or(p_shift_id, p_user_id, 'shift.assign');
    SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Shift not found');
    END IF;

    v_state_id := get_shift_state_id(p_shift_id);

    IF v_state_id != 'S3' THEN
        RETURN jsonb_build_object('success', false, 'error', format('Cannot decline from state %s. Expected S3.', v_state_id));
    END IF;

    SELECT COALESCE(p.full_name, p.first_name || ' ' || p.last_name, au.email, 'System')
    INTO v_performer_name
    FROM auth.users au
    LEFT JOIN public.profiles p ON p.id = au.id
    WHERE au.id = p_user_id;

    IF v_performer_name IS NULL THEN
        v_performer_name := 'Unknown User';
    END IF;

    v_new_iter := COALESCE(v_shift.bidding_iteration, 1) + 1;

    UPDATE shifts
    SET
        assigned_employee_id = NULL,
        assignment_status = 'unassigned',
        assignment_outcome = NULL,
        bidding_status = 'on_bidding',
        is_on_bidding = true,
        bidding_open_at = NOW(),
        fulfillment_status = 'bidding',
        trading_status = 'NoTrade',
        bidding_iteration = v_new_iter,
        last_rejected_by = p_user_id,
        last_dropped_by = NULL,
        updated_at = NOW(),
        last_modified_by = p_user_id,
        last_modified_reason = 'Offer declined'
    WHERE id = p_shift_id;

    INSERT INTO public.shift_events (shift_id, employee_id, event_type, event_time, metadata)
    VALUES (p_shift_id, p_user_id, 'REJECTED', NOW(), jsonb_build_object('source', 'sm_decline_offer'));

    RETURN jsonb_build_object('success', true, 'from_state', 'S3', 'to_state', 'S5');
END;
$$;


ALTER FUNCTION "public"."sm_decline_offer"("p_shift_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_delete_shift"("p_shift_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text", "p_expected_version" integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_shift public.shifts%ROWTYPE;
  v_refusal text;
BEGIN
  IF NOT public.sm_request_is_system() AND (auth.uid() IS NULL OR EXISTS (
       -- scope guard (20261011 access matrix)
       SELECT 1 FROM public.shifts s
        WHERE s.id = p_shift_id
          AND NOT public.user_has_action_in_scope('shift.delete', s.organization_id, s.department_id, s.sub_department_id))) THEN
    RETURN json_build_object('success', false, 'shift_id', p_shift_id,
      'error', 'You are not allowed to delete shifts.', 'code', 'FORBIDDEN');
  END IF;

  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'shift_id', p_shift_id,
      'error', 'Shift not found', 'code', 'SHIFT_NOT_FOUND');
  END IF;

  IF p_expected_version IS NOT NULL AND v_shift.version <> p_expected_version THEN
    RETURN json_build_object('success', false, 'shift_id', p_shift_id,
      'error', 'This shift was changed by someone else. Refresh and try again.', 'code', 'VERSION_CONFLICT');
  END IF;

  v_refusal := public._shift_delete_refusal(v_shift);
  IF v_refusal = 'SHIFT_WORKED' THEN
    RETURN json_build_object('success', false, 'shift_id', p_shift_id,
      'error', 'This shift has been worked, so it cannot be deleted. Correct it through the timesheet instead.',
      'code', v_refusal);
  ELSIF v_refusal = 'SHIFT_STARTED' THEN
    RETURN json_build_object('success', false, 'shift_id', p_shift_id,
      'error', 'This shift has already started, so it cannot be deleted.', 'code', v_refusal);
  END IF;

  DELETE FROM public.shifts WHERE id = p_shift_id;

  RETURN json_build_object('success', true, 'shift_id', p_shift_id, 'message', 'Shift deleted');
END;
$$;


ALTER FUNCTION "public"."sm_delete_shift"("p_shift_id" "uuid", "p_user_id" "uuid", "p_reason" "text", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_emergency_assign"("p_shift_id" "uuid", "p_employee_id" "uuid", "p_reason" "text" DEFAULT 'Emergency assignment'::"text", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_shift RECORD; v_state text; v_name text; v_role text;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_shift_action(p_shift_id, 'shift.assign');
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted'); END IF;

  SELECT COALESCE(first_name||' '||COALESCE(last_name,''), email), COALESCE(left(lower(legacy_system_role::text),50),'manager')
    INTO v_name, v_role FROM public.profiles WHERE id = p_user_id;
  v_name := COALESCE(v_name, 'System'); v_role := COALESCE(v_role, 'system');

  v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status, v_shift.assignment_outcome, v_shift.trading_status, v_shift.is_cancelled);

  IF v_state NOT IN ('S4', 'S5') THEN
    RETURN jsonb_build_object('success', false, 'error', format('sm_emergency_assign requires state S4 or S5, current state is %s', v_state));
  END IF;

  UPDATE public.shifts SET
    assigned_employee_id = p_employee_id,
    assigned_at = NOW(),
    assignment_status = 'assigned'::public.shift_assignment_status,
    assignment_outcome = 'confirmed'::public.shift_assignment_outcome,
    assignment_source = 'direct',
    bidding_status = 'not_on_bidding'::public.shift_bidding_status,
    is_on_bidding = FALSE,
    fulfillment_status = 'scheduled'::public.shift_fulfillment_status,
    confirmed_at = NOW(),
    emergency_assigned_at = NOW(),
    compliance_checked_at = NOW(),
    last_modified_by = p_user_id,
    updated_at = NOW()
  WHERE id = p_shift_id;

  RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S4', 'assigned_to', p_employee_id);
END; $$;


ALTER FUNCTION "public"."sm_emergency_assign"("p_shift_id" "uuid", "p_employee_id" "uuid", "p_reason" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_employee_cancel"("p_shift_id" "uuid", "p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_shift RECORD;
    v_state TEXT;
    v_time TEXT;
    v_new TEXT;
    v_new_iter INT;
BEGIN
    SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;
    v_state := get_shift_state_id(p_shift_id);
    v_time := get_time_category(v_shift.scheduled_start);

    IF v_state != 'S4' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not S4');
    END IF;

    IF v_shift.assigned_employee_id != p_employee_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not your shift');
    END IF;

    IF v_time = 'PAST' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Already started');
    END IF;

    v_new_iter := COALESCE(v_shift.bidding_iteration, 1) + 1;

    IF v_time = 'EMERGENCY' THEN
        v_new := 'S15';
        UPDATE shifts
        SET lifecycle_status = 'Cancelled',
            is_cancelled = TRUE,
            cancelled_at = NOW(),
            assigned_employee_id = NULL,
            assignment_status = 'unassigned',
            assignment_outcome = NULL,
            last_dropped_by = p_employee_id,
            last_rejected_by = NULL,
            bidding_iteration = v_new_iter,
            updated_at = NOW(),
            last_modified_by = p_employee_id
        WHERE id = p_shift_id;
    ELSE
        v_new := 'S5';
        UPDATE shifts
        SET assigned_employee_id = NULL,
            assignment_status = 'unassigned',
            assignment_outcome = NULL,
            is_on_bidding = TRUE,
            bidding_status = 'on_bidding',
            bidding_open_at = NOW(),
            fulfillment_status = 'bidding',
            bidding_iteration = v_new_iter,
            last_dropped_by = p_employee_id,
            last_rejected_by = NULL,
            updated_at = NOW(),
            last_modified_by = p_employee_id
        WHERE id = p_shift_id;
    END IF;

    RETURN jsonb_build_object('success', true, 'from_state', 'S4', 'to_state', v_new, 'time_category', v_time);
END;
$$;


ALTER FUNCTION "public"."sm_employee_cancel"("p_shift_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_employee_cancel"("p_shift_id" "uuid", "p_employee_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_shift RECORD;
    v_state TEXT;
    v_time TEXT;
    v_new TEXT;
BEGIN
    SELECT * INTO v_shift FROM shifts WHERE id=p_shift_id AND deleted_at IS NULL FOR UPDATE;
    v_state := get_shift_state_id(p_shift_id);
    v_time := get_time_category(v_shift.scheduled_start);

    IF v_state != 'S4' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not S4');
    END IF;

    IF v_shift.assigned_employee_id != p_employee_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not your shift');
    END IF;

    IF v_time = 'PAST' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Already started');
    END IF;

    IF v_time = 'EMERGENCY' THEN
        v_new := 'S15';
        UPDATE shifts
        SET lifecycle_status='Cancelled',
            is_cancelled=TRUE,
            cancelled_at=NOW(),
            assigned_employee_id=NULL,
            assignment_status='unassigned',
            assignment_outcome=NULL,
            updated_at=NOW(),
            last_modified_by=p_employee_id
        WHERE id=p_shift_id;
    ELSE
        v_new := 'S5';
        UPDATE shifts
        SET assigned_employee_id=NULL,
            assignment_status='unassigned',
            assignment_outcome=NULL,
            is_on_bidding=TRUE,
            bidding_status='on_bidding',
            bidding_open_at=NOW(),
            updated_at=NOW(),
            last_modified_by=p_employee_id
        WHERE id=p_shift_id;
    END IF;

    RETURN jsonb_build_object('success', true, 'from_state', 'S4', 'to_state', v_new, 'time_category', v_time);
END;
$$;


ALTER FUNCTION "public"."sm_employee_cancel"("p_shift_id" "uuid", "p_employee_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_employee_drop_shift"("p_shift_id" "uuid", "p_employee_id" "uuid" DEFAULT "auth"."uid"(), "p_reason" "text" DEFAULT NULL::"text", "p_reason_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_shift          RECORD;
    v_state          text;
    v_reason         public.cancellation_reasons%ROWTYPE;
    v_notice         interval;
    v_notice_hours   numeric;
    v_is_critical    boolean;
    v_urgency        text;
    v_event_type     public.shift_event_type;
    -- Standard vs critical. NOT the same line as the emergent lockout.
    v_cancel_cutoff  constant interval := interval '24 hours';
    -- Urgent vs emergent. Mirrors EMERGENT_WINDOW_MS in bidding-urgency.ts.
    v_emergent_cutoff constant interval := interval '4 hours';
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_assignee_or(p_shift_id, p_employee_id, 'shift.assign');
    SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted');
    END IF;

    IF v_shift.assigned_employee_id IS DISTINCT FROM p_employee_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'You are not assigned to this shift');
    END IF;

    v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status,
                                          v_shift.assignment_outcome, v_shift.trading_status,
                                          v_shift.is_cancelled);

    IF v_state NOT IN ('S3', 'S4') THEN
        RETURN jsonb_build_object('success', false,
            'error', format('sm_employee_drop_shift requires state S3 or S4, current state is %s', v_state));
    END IF;

    IF p_reason_code IS NOT NULL THEN
        SELECT * INTO v_reason
        FROM public.cancellation_reasons
        WHERE code = p_reason_code AND is_active;

        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false,
                'error', format('Unknown cancellation reason: %s', p_reason_code));
        END IF;

        IF v_reason.requires_note AND COALESCE(btrim(p_reason), '') = '' THEN
            RETURN jsonb_build_object('success', false,
                'error', format('Reason "%s" requires a note', v_reason.label));
        END IF;
    END IF;

    v_notice       := v_shift.start_at - now();
    v_notice_hours := ROUND(EXTRACT(epoch FROM v_notice)::numeric / 3600, 2);
    v_is_critical  := v_shift.start_at IS NOT NULL AND v_notice <= v_cancel_cutoff;
    v_urgency      := CASE
                          WHEN v_shift.start_at IS NULL             THEN 'normal'
                          WHEN v_notice <= v_emergent_cutoff        THEN 'emergent'
                          WHEN v_notice <= v_cancel_cutoff          THEN 'urgent'
                          ELSE 'normal'
                      END;
    v_event_type   := CASE WHEN v_is_critical THEN 'LATE_CANCELLED' ELSE 'CANCELLED' END::public.shift_event_type;

    PERFORM set_config('app.audit.employee_drop', '1', true);

    UPDATE public.shifts SET
        assigned_employee_id = NULL,
        assigned_at          = NULL,
        assignment_status    = 'unassigned'::public.shift_assignment_status,
        assignment_outcome   = NULL,
        bidding_status       = 'on_bidding'::public.shift_bidding_status,
        is_on_bidding        = TRUE,
        fulfillment_status   = 'bidding'::public.shift_fulfillment_status,
        confirmed_at         = NULL,
        last_dropped_by      = p_employee_id,
        last_rejected_by     = NULL,
        last_modified_by     = p_employee_id,
        updated_at           = NOW()
    WHERE id = p_shift_id;

    PERFORM set_config('app.audit.employee_drop', '0', true);

    INSERT INTO public.shift_events
        (shift_id, employee_id, actor_id, event_type, event_time, metadata, actor_role, domain)
    VALUES (
        p_shift_id,
        p_employee_id,
        p_employee_id,
        v_event_type,
        now(),
        jsonb_build_object(
            'op',           'employee_drop',
            'from_state',   v_state,
            'to_state',     'S5',
            'cancellation', CASE WHEN v_is_critical THEN 'critical' ELSE 'standard' END,
            'urgency',      v_urgency,
            'notice_hours', v_notice_hours,
            'source',       'sm_employee_drop_shift'
        )
        || CASE WHEN p_reason_code IS NOT NULL
                THEN jsonb_build_object('reason_code', p_reason_code) ELSE '{}'::jsonb END
        || CASE WHEN COALESCE(btrim(p_reason), '') <> ''
                THEN jsonb_build_object('reason_note', btrim(p_reason)) ELSE '{}'::jsonb END,
        'employee',
        'assignment'
    )
    ON CONFLICT ON CONSTRAINT uniq_shift_event DO NOTHING;

    RETURN jsonb_build_object(
        'success',      true,
        'from_state',   v_state,
        'to_state',     'S5',
        'cancellation', CASE WHEN v_is_critical THEN 'critical' ELSE 'standard' END,
        'urgency',      v_urgency,
        'notice_hours', v_notice_hours
    );
END;
$$;


ALTER FUNCTION "public"."sm_employee_drop_shift"("p_shift_id" "uuid", "p_employee_id" "uuid", "p_reason" "text", "p_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_expire_offer_now"("p_shift_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_shift shifts%ROWTYPE;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_assignee_or(p_shift_id, NULL, 'shift.assign');
  SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('success', false, 'error', 'Shift not found'); END IF;
  IF v_shift.assignment_outcome IS DISTINCT FROM 'offered' THEN RETURN json_build_object('success', false, 'error', 'Shift is not in offered state'); END IF;

  UPDATE shifts SET
    lifecycle_status      = 'Draft',
    assignment_outcome    = NULL,
    bidding_status        = 'not_on_bidding',
    last_modified_reason  = 'Offer expired manually - Reverted to Draft Assigned',
    updated_at            = now()
  WHERE id = p_shift_id;

  RETURN json_build_object('success', true, 'from_state', 'S3', 'to_state', 'S2');
END;
$$;


ALTER FUNCTION "public"."sm_expire_offer_now"("p_shift_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_expire_trade"("p_shift_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_shift RECORD; v_state text;
BEGIN
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted'); END IF;
  v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status, v_shift.assignment_outcome, v_shift.trading_status, v_shift.is_cancelled);
  IF v_state NOT IN ('S9', 'S10') THEN RETURN jsonb_build_object('success', false, 'error', format('sm_expire_trade requires state S9 or S10, current state is %s', v_state)); END IF;
  UPDATE public.shifts SET trading_status = 'NoTrade'::public.shift_trading, last_modified_by = p_user_id, updated_at = NOW() WHERE id = p_shift_id;
  RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S4');
END; $$;


ALTER FUNCTION "public"."sm_expire_trade"("p_shift_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_finalize_planning_request"("p_request_id" "uuid", "p_offer_id" "uuid", "p_manager_id" "uuid", "p_manager_notes" "text", "p_shift_updated_at" timestamp with time zone, "p_target_shift_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'hr'
    AS $$
DECLARE
  v_request       planning_requests%ROWTYPE;
  v_offer         planning_offers%ROWTYPE;
  v_shift_updated timestamptz;
  v_target_updated timestamptz;
BEGIN

  -- P0 security fix (2026-07-27): this function previously had zero
  -- authorization check and trusted p_manager_id verbatim, while
  -- also being anon-executable -- letting an unauthenticated caller
  -- approve shift swap/bid requests and forge the approving
  -- manager's identity in the audit trail.
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF NOT public.can_act_on_shift('shift.assign',
           (SELECT pr.shift_id FROM public.planning_requests pr WHERE pr.id = p_request_id)) THEN
      RAISE EXCEPTION 'NOT_AUTHORIZED: caller is not a manager or admin';
    END IF;
    IF p_manager_id IS DISTINCT FROM auth.uid() THEN
      RAISE EXCEPTION 'MANAGER_ID_MISMATCH: p_manager_id must match the authenticated caller';
    END IF;
  END IF;

  -- ===========================================================================
  -- STEP 1: Lock the planning_request row for the duration of this transaction.
  -- This prevents two concurrent approve calls from both proceeding.
  -- ===========================================================================

  SELECT *
    INTO v_request
    FROM planning_requests
   WHERE id = p_request_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Planning request % not found', p_request_id;
  END IF;


  -- ===========================================================================
  -- STEP 2: Validate request status.
  -- ===========================================================================

  IF v_request.status <> 'MANAGER_PENDING' THEN
    RAISE EXCEPTION 'WRONG_STATE: request % has status % (expected MANAGER_PENDING)',
      p_request_id, v_request.status;
  END IF;


  -- ===========================================================================
  -- STEP 3: Fetch and validate the selected offer.
  -- ===========================================================================

  SELECT *
    INTO v_offer
    FROM planning_offers
   WHERE id         = p_offer_id
     AND request_id = p_request_id
     AND status     = 'SELECTED';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NO_SELECTED_OFFER: no SELECTED offer % for request %',
      p_offer_id, p_request_id;
  END IF;


  -- ===========================================================================
  -- STEP 4: Optimistic lock check — initiator's shift.
  -- ===========================================================================

  SELECT updated_at
    INTO v_shift_updated
    FROM shifts
   WHERE id = v_request.shift_id;

  IF v_shift_updated IS DISTINCT FROM p_shift_updated_at THEN
    RAISE EXCEPTION 'SHIFT_MUTATED: shift_id=%', v_request.shift_id;
  END IF;


  -- ===========================================================================
  -- STEP 5: Optimistic lock check — offerer's shift (SWAP only).
  -- ===========================================================================

  IF v_request.type = 'SWAP' AND v_offer.offered_shift_id IS NOT NULL THEN

    IF p_target_shift_updated_at IS NULL THEN
      RAISE EXCEPTION 'MISSING_TARGET_SHIFT_TIMESTAMP: SWAP request requires p_target_shift_updated_at';
    END IF;

    SELECT updated_at
      INTO v_target_updated
      FROM shifts
     WHERE id = v_offer.offered_shift_id;

    IF v_target_updated IS DISTINCT FROM p_target_shift_updated_at THEN
      RAISE EXCEPTION 'SHIFT_MUTATED: target_shift_id=%', v_offer.offered_shift_id;
    END IF;

  END IF;


  -- ===========================================================================
  -- STEP 6 / 7: Perform the shift mutation.
  -- BID  → assign initiator to the shift.
  -- SWAP → atomic two-way assignment swap.
  -- ===========================================================================

  IF v_request.type = 'BID' THEN

    -- Assign the winning bidder (the offer submitter) to the open shift.
    UPDATE shifts
       SET assigned_employee_id = v_offer.offered_by,
           workflow_status      = 'IDLE',
           updated_at           = now()
     WHERE id = v_request.shift_id;

  ELSIF v_request.type = 'SWAP' THEN

    -- Two-way atomic swap: both employees exchange shifts simultaneously.
    -- We capture the existing owners first to avoid ordering issues.
    DECLARE
      v_initiator_current_owner uuid;
      v_offerer_current_owner   uuid;
    BEGIN
      SELECT assigned_employee_id INTO v_initiator_current_owner
        FROM shifts WHERE id = v_request.shift_id;

      SELECT assigned_employee_id INTO v_offerer_current_owner
        FROM shifts WHERE id = v_offer.offered_shift_id;

      -- Assign offerer to initiator's shift
      UPDATE shifts
         SET assigned_employee_id = v_offerer_current_owner,
             workflow_status      = 'IDLE',
             updated_at           = now()
       WHERE id = v_request.shift_id;

      -- Assign initiator to offerer's shift
      UPDATE shifts
         SET assigned_employee_id = v_initiator_current_owner,
             workflow_status      = 'IDLE',
             updated_at           = now()
       WHERE id = v_offer.offered_shift_id;
    END;

  END IF;


  -- ===========================================================================
  -- STEP 8: Mark the planning_request as APPROVED.
  -- ===========================================================================

  UPDATE planning_requests
     SET status       = 'APPROVED',
         manager_id   = p_manager_id,
         manager_notes = p_manager_notes,
         decided_at   = now(),
         updated_at   = now()
   WHERE id = p_request_id;

END;
$$;


ALTER FUNCTION "public"."sm_finalize_planning_request"("p_request_id" "uuid", "p_offer_id" "uuid", "p_manager_id" "uuid", "p_manager_notes" "text", "p_shift_updated_at" timestamp with time zone, "p_target_shift_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_handle_auto_clock_out"() RETURNS TABLE("affected_shift_id" "uuid", "previous_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH resolved AS (
    SELECT
      id,
      lifecycle_status::text AS prev_status,
      GREATEST(
        COALESCE(actual_start, start_at,
          (shift_date::text || ' ' || start_time::text || ' Australia/Sydney')::TIMESTAMPTZ),
        COALESCE(start_at,
          (shift_date::text || ' ' || start_time::text || ' Australia/Sydney')::TIMESTAMPTZ)
      ) AS anchor
    FROM shifts
    WHERE attendance_status IN ('checked_in', 'late')
      AND actual_end IS NULL
      AND lifecycle_status IN ('InProgress', 'Completed')
      AND deleted_at IS NULL
  ),
  eligible AS (
    SELECT r.id, r.prev_status
    FROM resolved r
    WHERE r.anchor + INTERVAL '12.5 hours' <= now()
  ),
  updated AS (
    UPDATE shifts s SET
      lifecycle_status   = 'Completed',
      attendance_status  = 'auto_clock_out',
      attendance_note    = 'Auto-completed by system (12.5hr limit)',
      updated_at         = now()
    FROM eligible e
    WHERE s.id = e.id
    RETURNING s.id, e.prev_status
  )
  SELECT u.id, u.prev_status FROM updated u;
END;
$$;


ALTER FUNCTION "public"."sm_handle_auto_clock_out"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_holds_active_contract_in"("p_profile_id" "uuid", "p_sub_department_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'hr', 'pg_catalog'
    AS $$
  SELECT p_sub_department_id IS NULL
      OR EXISTS (
           SELECT 1 FROM hr.user_contracts uc
            WHERE uc.user_id = p_profile_id AND uc.status = 'Active'
              AND ( uc.sub_department_id = p_sub_department_id
                 OR (uc.sub_department_id IS NULL AND uc.department_id IS NOT NULL
                     AND uc.department_id = (SELECT sd.department_id FROM public.sub_departments sd
                                              WHERE sd.id = p_sub_department_id))));
$$;


ALTER FUNCTION "public"."sm_holds_active_contract_in"("p_profile_id" "uuid", "p_sub_department_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sm_holds_active_contract_in"("p_profile_id" "uuid", "p_sub_department_id" "uuid") IS 'True when the profile holds an Active contract in that sub-department, or a department-wide one above it. NULL sub-department returns true (unscoped).';



CREATE OR REPLACE FUNCTION "public"."sm_holds_active_ft_contract"("p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'hr', 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM hr.user_contracts uc
     WHERE uc.user_id = p_profile_id
       AND uc.status = 'Active'
       AND LOWER(COALESCE(uc.employment_status::text, '')) LIKE '%full%'
  );
$$;


ALTER FUNCTION "public"."sm_holds_active_ft_contract"("p_profile_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sm_holds_active_ft_contract"("p_profile_id" "uuid") IS 'True when the profile holds ANY Active Full-Time contract. The single definition of "is Full-Time" shared by trg_prevent_ft_availability_rule and sm_materialize_contract_envelope, so the write guard and the slot generator can never disagree about one person.';



CREATE OR REPLACE FUNCTION "public"."sm_holds_active_ft_contract_in"("p_profile_id" "uuid", "p_sub_department_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'hr', 'pg_catalog'
    AS $$
  SELECT CASE
    -- Unscoped covers every job, so it must clear the strictest test. This is
    -- the pre-20260821 behaviour, unchanged, and what every client that has not
    -- yet learned about scopes keeps hitting.
    WHEN p_sub_department_id IS NULL
      THEN public.sm_holds_active_ft_contract(p_profile_id)
    ELSE EXISTS (
      SELECT 1 FROM hr.user_contracts uc
       WHERE uc.user_id = p_profile_id AND uc.status = 'Active'
         AND LOWER(COALESCE(uc.employment_status::text, '')) LIKE '%full%'
         AND ( uc.sub_department_id = p_sub_department_id
            OR (uc.sub_department_id IS NULL AND uc.department_id IS NOT NULL
                AND uc.department_id = (SELECT sd.department_id FROM public.sub_departments sd
                                         WHERE sd.id = p_sub_department_id))))
  END;
$$;


ALTER FUNCTION "public"."sm_holds_active_ft_contract_in"("p_profile_id" "uuid", "p_sub_department_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sm_holds_active_ft_contract_in"("p_profile_id" "uuid", "p_sub_department_id" "uuid") IS 'Is THIS JOB Full-Time? True when the profile holds an Active Full-Time contract in that sub-department, or a department-wide one above it. A NULL sub-department delegates to the person-wide sm_holds_active_ft_contract, because an unscoped declaration covers every job the person holds.';



CREATE OR REPLACE FUNCTION "public"."sm_legacy_manager"("p_user" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  -- Retired 20261011 (decision 12): the legacy profile flag grants nothing.
  -- Kept, answering false, so its remaining callers read certificates only.
  SELECT false;
$$;


ALTER FUNCTION "public"."sm_legacy_manager"("p_user" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sm_legacy_manager"("p_user" "uuid") IS 'The legacy_system_role escape hatch, stated once. Preserved rather than removed because removing it is a behaviour change. It remains the last place a role column beats a certificate.';



CREATE OR REPLACE FUNCTION "public"."sm_manager_cancel"("p_shift_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"(), "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE 
    v_shift RECORD;
    v_state TEXT;
    v_user_name TEXT;
    v_user_role TEXT;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_shift_action(p_shift_id, 'shift.edit');
    SELECT * INTO v_shift FROM shifts 
    WHERE id = p_shift_id AND deleted_at IS NULL
    FOR UPDATE;
    
    IF NOT FOUND THEN 
        RETURN jsonb_build_object('success', false, 'error', 'Not found'); 
    END IF;
    
    v_state := get_shift_state_id(p_shift_id);
    
    IF v_state IN ('S11', 'S12', 'S13', 'S14', 'S15') THEN 
        RETURN jsonb_build_object('success', false, 'error', format('Cannot cancel from %s', v_state)); 
    END IF;
    
    IF p_user_id IS NOT NULL THEN
        SELECT COALESCE(first_name || ' ' || last_name, email),
               COALESCE(legacy_system_role::text, 'manager')
        INTO v_user_name, v_user_role
        FROM profiles WHERE id = p_user_id;
    END IF;
    v_user_name := COALESCE(v_user_name, 'System');
    v_user_role := COALESCE(v_user_role, 'manager');
    
    UPDATE shifts 
    SET lifecycle_status = 'Cancelled', 
        is_cancelled = TRUE, 
        cancelled_at = NOW(), 
        cancelled_by_user_id = p_user_id,
        cancellation_reason = p_reason, 
        is_on_bidding = FALSE, 
        bidding_status = 'not_on_bidding', 
        trading_status = 'NoTrade',
        assignment_outcome = NULL, 
        updated_at = NOW(), 
        last_modified_by = p_user_id 
    WHERE id = p_shift_id;
    
    RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S15');
END; 
$$;


ALTER FUNCTION "public"."sm_manager_cancel"("p_shift_id" "uuid", "p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_mark_no_show"("p_shift_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"(), "p_reason" "text" DEFAULT 'Employee no-show'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_shift RECORD; v_state text; v_name text; v_role text;
BEGIN
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted'); END IF;
  SELECT COALESCE(first_name||' '||COALESCE(last_name,''), email), COALESCE(left(lower(legacy_system_role::text),50),'manager')
    INTO v_name, v_role FROM public.profiles WHERE id = p_user_id;
  v_name := COALESCE(v_name, 'System'); v_role := COALESCE(v_role, 'system');
  v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status, v_shift.assignment_outcome, v_shift.trading_status, v_shift.is_cancelled);
  IF v_state != 'S11' THEN RETURN jsonb_build_object('success', false, 'error', format('sm_mark_no_show requires state S11, current state is %s', v_state)); END IF;
  UPDATE public.shifts SET
    assignment_outcome = 'no_show'::public.shift_assignment_outcome, lifecycle_status = 'Completed'::public.shift_lifecycle,
    last_modified_by = p_user_id, updated_at = NOW()
  WHERE id = p_shift_id;
  RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S13');
END; $$;


ALTER FUNCTION "public"."sm_mark_no_show"("p_shift_id" "uuid", "p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_materialize_contract_envelope"("p_from" "date" DEFAULT CURRENT_DATE, "p_to" "date" DEFAULT (CURRENT_DATE + 180), "p_profile_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("profiles_touched" integer, "slots_written" integer, "slots_removed" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'hr'
    AS $$
DECLARE
  v_written int := 0;
  v_removed int := 0;
  v_touched int := 0;
BEGIN
  IF p_to < p_from THEN
    RAISE EXCEPTION 'sm_materialize_contract_envelope: p_to (%) is before p_from (%)', p_to, p_from
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF (p_to - p_from) > 400 THEN
    RAISE EXCEPTION 'sm_materialize_contract_envelope: horizon of % days exceeds the 400-day maximum', (p_to - p_from)
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  DROP TABLE IF EXISTS _env_target;
  DROP TABLE IF EXISTS _env_scope;

  CREATE TEMP TABLE _env_target ON COMMIT DROP AS
  WITH basis AS (
    SELECT DISTINCT ON (uc.user_id)
           uc.user_id, uc.ordinary_span_start, uc.ordinary_span_end,
           COALESCE(uc.ordinary_days, ARRAY[1,2,3,4,5,6,7]::smallint[]) AS ordinary_days,
           uc.start_date, uc.end_date
      FROM hr.user_contracts uc
     WHERE uc.status = 'Active'
       AND uc.employment_status <> 'Casual'
       AND NOT public.sm_holds_active_ft_contract(uc.user_id)
       AND uc.ordinary_span_start IS NOT NULL
       AND uc.ordinary_span_end   IS NOT NULL
       AND (p_profile_ids IS NULL OR uc.user_id = ANY (p_profile_ids))
     ORDER BY uc.user_id, (uc.employment_status = 'Casual'),
              uc.contracted_weekly_hours DESC NULLS LAST,
              uc.start_date DESC NULLS LAST, uc.id
  )
  SELECT b.user_id AS profile_id, d::date AS slot_date,
         b.ordinary_span_start AS start_time, b.ordinary_span_end AS end_time
    FROM basis b
    CROSS JOIN LATERAL generate_series(
      GREATEST(p_from, COALESCE(b.start_date, p_from)),
      LEAST   (p_to,   COALESCE(b.end_date,   p_to)),
      interval '1 day') AS d
   WHERE EXTRACT(isodow FROM d)::smallint = ANY (b.ordinary_days)
     AND NOT EXISTS (
       SELECT 1 FROM public.employee_leave_days eld
        WHERE eld.employee_id = b.user_id AND eld.leave_date = d::date);

  CREATE TEMP TABLE _env_scope ON COMMIT DROP AS
    SELECT DISTINCT profile_id FROM _env_target
    UNION
    SELECT DISTINCT s.profile_id FROM public.availability_slots s
     WHERE s.source = 'envelope'
       AND s.slot_date BETWEEN p_from AND p_to
       AND (p_profile_ids IS NULL OR s.profile_id = ANY (p_profile_ids));

  SELECT count(*) INTO v_touched FROM _env_scope;

  WITH removed AS (
    DELETE FROM public.availability_slots s
     USING _env_scope sc
     WHERE s.profile_id = sc.profile_id
       AND s.source = 'envelope'
       AND s.slot_date BETWEEN p_from AND p_to
       AND NOT EXISTS (
         SELECT 1 FROM _env_target t
          WHERE t.profile_id = s.profile_id AND t.slot_date = s.slot_date
            AND t.start_time = s.start_time AND t.end_time = s.end_time)
     RETURNING 1)
  SELECT count(*) INTO v_removed FROM removed;

  WITH written AS (
    INSERT INTO public.availability_slots (profile_id, slot_date, start_time, end_time, source)
    SELECT t.profile_id, t.slot_date, t.start_time, t.end_time, 'envelope'
      FROM _env_target t
    ON CONFLICT (profile_id, slot_date, start_time, end_time, source,
                 COALESCE(sub_department_id, '00000000-0000-0000-0000-000000000000'::uuid))
    DO NOTHING
    RETURNING 1)
  SELECT count(*) INTO v_written FROM written;

  RAISE LOG '[envelope] % profile(s) in scope, % slot(s) written, % removed, range % .. %',
    v_touched, v_written, v_removed, p_from, p_to;

  profiles_touched := v_touched;
  slots_written    := v_written;
  slots_removed    := v_removed;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."sm_materialize_contract_envelope"("p_from" "date", "p_to" "date", "p_profile_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sm_materialize_contract_envelope"("p_from" "date", "p_to" "date", "p_profile_ids" "uuid"[]) IS 'Regenerates source=''envelope'' availability_slots for Active contracts that are neither Casual nor Full-Time and have an ordinary-hours span configured, over [p_from, p_to]. Full-Time is excluded because their availability is implicit (see sm_holds_active_ft_contract); Casual because a generated slot is not an offer they made. Idempotent: deletes envelope rows in range that no longer belong — including every row of a person who has just become Full-Time — and inserts the ones that do, never touching source=''rule'' rows. Skips dates covered by approved leave. Writes nothing for contracts with a NULL span, which is every contract until one is explicitly opted in.';



CREATE OR REPLACE FUNCTION "public"."sm_move_shift"("p_shift_id" "uuid", "p_group_type" "text" DEFAULT NULL::"text", "p_sub_group_name" "text" DEFAULT NULL::"text", "p_shift_group_id" "uuid" DEFAULT NULL::"uuid", "p_roster_subgroup_id" "uuid" DEFAULT NULL::"uuid", "p_shift_date" "date" DEFAULT NULL::"date", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_found BOOLEAN;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_shift_action(p_shift_id, 'shift.edit');
    UPDATE shifts SET
        -- Cast TEXT parameter to the ENUM type required by the table
        group_type         = CASE 
                                WHEN p_group_type IS NULL THEN group_type 
                                ELSE p_group_type::template_group_type 
                             END,
        sub_group_name     = COALESCE(p_sub_group_name, sub_group_name),
        shift_group_id     = p_shift_group_id,
        roster_subgroup_id = p_roster_subgroup_id,
        shift_date         = COALESCE(p_shift_date, shift_date),
        roster_date        = COALESCE(p_shift_date, roster_date),
        updated_at         = NOW(),
        last_modified_by   = p_user_id
    WHERE id = p_shift_id
      AND deleted_at IS NULL;

    v_found := FOUND;

    IF NOT v_found THEN
        RETURN jsonb_build_object('success', false, 'error', 'Shift not found or already deleted');
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."sm_move_shift"("p_shift_id" "uuid", "p_group_type" "text", "p_sub_group_name" "text", "p_shift_group_id" "uuid", "p_roster_subgroup_id" "uuid", "p_shift_date" "date", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_publish_shift"("p_shift_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_shift RECORD;
  v_state text;
  v_to_state text;
  v_name text;
  v_role text;
  v_is_ft boolean;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_shift_action(p_shift_id, 'shift.publish');
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted');
  END IF;

  SELECT COALESCE(first_name||' '||COALESCE(last_name,''), email), COALESCE(left(lower(legacy_system_role::text),50),'manager')
    INTO v_name, v_role FROM public.profiles WHERE id = p_user_id;
  v_name := COALESCE(v_name, 'System');
  v_role := COALESCE(v_role, 'system');

  v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status,
    v_shift.assignment_outcome, v_shift.trading_status, v_shift.is_cancelled);
  v_is_ft := v_shift.target_employment_type = 'FT';

  IF v_state IN ('S3', 'S4', 'S5') THEN
    RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', v_state, 'message', 'Already published');
  END IF;
  IF v_state NOT IN ('S1', 'S2') THEN
    RETURN jsonb_build_object('success', false, 'error', format('sm_publish_shift requires state S1 or S2, current state is %s', v_state));
  END IF;

  IF v_state = 'S2' AND v_is_ft THEN
    v_to_state := 'S4';
    UPDATE public.shifts SET
      lifecycle_status = 'Published'::public.shift_lifecycle,
      published_at = NOW(),
      assignment_outcome = 'confirmed',
      confirmed_at = NOW(),
      bidding_status = 'not_on_bidding'::public.shift_bidding_status,
      is_on_bidding = FALSE,
      fulfillment_status = 'scheduled'::public.shift_fulfillment_status,
      last_modified_by = p_user_id,
      updated_at = NOW()
    WHERE id = p_shift_id;
  ELSIF v_state = 'S2' THEN
    v_to_state := 'S3';
    UPDATE public.shifts SET
      lifecycle_status = 'Published'::public.shift_lifecycle,
      assignment_outcome = NULL,
      bidding_status = 'not_on_bidding'::public.shift_bidding_status,
      is_on_bidding = FALSE,
      fulfillment_status = 'offered'::public.shift_fulfillment_status,
      last_modified_by = p_user_id,
      updated_at = NOW()
    WHERE id = p_shift_id;
  ELSIF v_is_ft THEN
    RETURN jsonb_build_object('success', false, 'code', 'FT_UNASSIGNED',
      'error', 'A full-time shift must be assigned before it is published — it can never go to bidding.');
  ELSE
    v_to_state := 'S5';
    UPDATE public.shifts SET
      lifecycle_status = 'Published'::public.shift_lifecycle,
      assignment_status = 'unassigned'::public.shift_assignment_status,
      assignment_outcome = NULL,
      bidding_status = 'on_bidding'::public.shift_bidding_status,
      is_on_bidding = TRUE,
      fulfillment_status = 'bidding'::public.shift_fulfillment_status,
      last_modified_by = p_user_id,
      updated_at = NOW()
    WHERE id = p_shift_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', v_to_state);
END;
$$;


ALTER FUNCTION "public"."sm_publish_shift"("p_shift_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_refresh_shift_snapshots"("p_shift_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF p_shift_id IS NULL THEN
        RETURN;
    END IF;

    DELETE FROM public.assignment_snapshots WHERE shift_id = p_shift_id;

    INSERT INTO public.assignment_snapshots (
        shift_id, episode_seq, employee_id, source,
        became_active_at, ended_at, end_reason,
        attended, late_in, early_out, is_current,
        organization_id, department_id, sub_department_id,
        shift_date, scheduled_start, refreshed_at,
        early_in, late_out, on_time_in, on_time_out, auto_clock_out
    )
    WITH
    late_cancel_threshold AS (
        SELECT interval '4 hours' AS val
    ),
    ordered_events AS (
        SELECT
            se.id           AS event_id,
            se.shift_id,
            se.employee_id,
            se.event_type,
            se.event_time,
            se.metadata
        FROM public.shift_events se
        WHERE se.shift_id = p_shift_id          -- ← pushed to the lowest scan
          AND se.employee_id IS NOT NULL
    ),
    classified AS (
        SELECT
            oe.*,
            (oe.event_type IN ('ASSIGNED','OFFERED','EMERGENCY_ASSIGNED','SWAPPED_IN')) AS is_opening_type,
            (oe.event_type IN ('REJECTED','IGNORED','CANCELLED','LATE_CANCELLED',
                               'SWAPPED_OUT','NO_SHOW','UNASSIGNED'))                    AS is_closing_type
        FROM ordered_events oe
    ),
    boundary_events AS (
        SELECT
            c.shift_id,
            c.event_id,
            c.event_time,
            c.employee_id,
            c.is_opening_type,
            LAG(c.is_closing_type) OVER w AS prev_boundary_was_closing,
            LAG(c.employee_id)     OVER w AS prev_boundary_employee
        FROM classified c
        WHERE c.is_opening_type OR c.is_closing_type
        WINDOW w AS (PARTITION BY c.shift_id ORDER BY c.event_time, c.event_id)
    ),
    boundary_starts AS (
        SELECT
            be.shift_id,
            be.event_id,
            CASE
                WHEN be.is_opening_type AND (
                         be.prev_boundary_employee IS NULL
                      OR be.prev_boundary_was_closing
                      OR be.employee_id IS DISTINCT FROM be.prev_boundary_employee
                     )
                THEN 1 ELSE 0
            END AS starts_new_episode
        FROM boundary_events be
    ),
    episode_assigned AS (
        SELECT
            c.*,
            SUM(COALESCE(bs.starts_new_episode, 0))
                OVER (PARTITION BY c.shift_id ORDER BY c.event_time, c.event_id
                      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS episode_seq
        FROM classified c
        LEFT JOIN boundary_starts bs
               ON bs.shift_id = c.shift_id AND bs.event_id = c.event_id
    ),
    episode_agg AS (
        SELECT
            ea.shift_id,
            ea.episode_seq,
            (ARRAY_AGG(ea.employee_id ORDER BY ea.event_time, ea.event_id))[1] AS employee_id,
            MIN(ea.event_time) AS opened_at,
            MIN(ea.event_time) FILTER (
                WHERE ea.event_type IN ('ACCEPTED','EMERGENCY_ASSIGNED','SWAPPED_IN')
            ) AS became_active_at,
            BOOL_OR(ea.event_type = 'OFFERED')              AS had_offer,
            BOOL_OR(ea.event_type = 'ACCEPTED')             AS had_accept,
            BOOL_OR(ea.event_type = 'ASSIGNED')             AS had_assign,
            BOOL_OR(ea.event_type = 'EMERGENCY_ASSIGNED')    AS had_emergency,
            BOOL_OR(ea.event_type = 'SWAPPED_IN')            AS had_swap_in,
            BOOL_OR(ea.event_type = 'CHECKED_IN')            AS had_checked_in,
            BOOL_OR(ea.event_type = 'LATE_IN')               AS had_late_in_event,
            BOOL_OR(ea.event_type = 'EARLY_OUT')             AS had_early_out_event,
            (ARRAY_AGG(ea.event_type ORDER BY ea.event_time DESC, ea.event_id DESC)
                FILTER (WHERE ea.event_type IN ('REJECTED','IGNORED','CANCELLED','LATE_CANCELLED',
                                                 'SWAPPED_OUT','NO_SHOW','UNASSIGNED')))[1]
                AS closing_event_type,
            (ARRAY_AGG(ea.event_time ORDER BY ea.event_time DESC, ea.event_id DESC)
                FILTER (WHERE ea.event_type IN ('REJECTED','IGNORED','CANCELLED','LATE_CANCELLED',
                                                 'SWAPPED_OUT','NO_SHOW','UNASSIGNED')))[1]
                AS closing_event_time
        FROM episode_assigned ea
        WHERE ea.episode_seq > 0
        GROUP BY ea.shift_id, ea.episode_seq
    ),
    episode_with_shift AS (
        SELECT
            ep.*,
            MAX(ep.episode_seq) OVER (PARTITION BY ep.shift_id) AS max_episode_seq,
            s.shift_date,
            s.organization_id,
            s.department_id,
            s.sub_department_id,
            s.lifecycle_status,
            s.deleted_at,
            s.scheduled_start,
            s.scheduled_end,
            s.attendance_status,
            lct.val AS late_cancel_threshold
        FROM episode_agg ep
        JOIN public.shifts s ON s.id = ep.shift_id
        CROSS JOIN late_cancel_threshold lct
    ),
    episode_final AS (
        SELECT
            ews.shift_id,
            ews.episode_seq,
            ews.employee_id,
            ews.opened_at,
            ews.became_active_at,
            ews.closing_event_time AS closed_at,
            CASE
                WHEN ews.deleted_at IS NOT NULL THEN 'shift_deleted'
                WHEN ews.closing_event_type = 'REJECTED'       THEN 'rejected'
                WHEN ews.closing_event_type = 'IGNORED'        THEN 'ignored'
                WHEN ews.closing_event_type = 'SWAPPED_OUT'    THEN 'swapped_out'
                WHEN ews.closing_event_type = 'NO_SHOW'        THEN 'no_show'
                WHEN ews.closing_event_type = 'UNASSIGNED'     THEN 'unassigned'
                WHEN ews.closing_event_type IN ('CANCELLED', 'LATE_CANCELLED') THEN
                    CASE
                        WHEN ews.scheduled_start IS NOT NULL
                             AND ews.closing_event_time IS NOT NULL
                             AND (ews.scheduled_start - ews.closing_event_time) <= ews.late_cancel_threshold
                        THEN 'cancelled_late'
                        ELSE 'cancelled_standard'
                    END
                WHEN ews.closing_event_type IS NULL
                     AND ews.lifecycle_status = 'Completed'
                     AND ews.episode_seq = ews.max_episode_seq THEN 'fulfilled'
                ELSE 'open'
            END AS terminal_outcome,
            ews.had_accept,
            ews.had_emergency,
            ews.had_swap_in,
            COALESCE(ews.had_checked_in, FALSE) AS attended_from_events,
            COALESCE(ews.had_late_in_event, FALSE) AS late_in_from_events,
            COALESCE(ews.had_early_out_event, FALSE) AS early_out_from_events,
            ews.shift_date,
            ews.organization_id,
            ews.department_id,
            ews.sub_department_id,
            ews.scheduled_start,
            ews.scheduled_end,
            ews.attendance_status
        FROM episode_with_shift ews
    ),
    ts_agg AS (
        SELECT
            ts.shift_id,
            ts.employee_id,
            MIN(ts.clock_in)  AS clock_in,
            MAX(ts.clock_out) AS clock_out,
            MIN(
                -- Manager-adjusted billable start (timesheets.start_time is only
                -- ever persisted on a manual edit) OVERRIDES the raw clock-in —
                -- the `*` on the Live Rules badge flows into the metrics.
                COALESCE(
                    (ts.work_date + ts.start_time) AT TIME ZONE COALESCE(s.timezone, 'Australia/Sydney'),
                    ts.clock_in
                )
            ) AS effective_clock_in,
            MAX(
                -- Manager-adjusted billable end overrides the raw clock-out.
                COALESCE(
                    (CASE WHEN ts.end_time < ts.start_time THEN ts.work_date + interval '1 day' + ts.end_time ELSE ts.work_date + ts.end_time END) AT TIME ZONE COALESCE(s.timezone, 'Australia/Sydney'),
                    ts.clock_out
                )
            ) AS effective_clock_out
        FROM public.timesheets ts
        JOIN public.shifts s ON s.id = ts.shift_id
        WHERE ts.shift_id = p_shift_id          -- ← pushed to the lowest scan
        GROUP BY ts.shift_id, ts.employee_id
    ),
    episodes_for_shift AS (
        SELECT
            ef.shift_id,
            ef.episode_seq,
            ef.employee_id,
            ef.opened_at,
            ef.closed_at,
            ef.terminal_outcome,
            ef.had_accept,
            ef.had_emergency,
            ef.had_swap_in,
            (ef.attended_from_events OR t.clock_in IS NOT NULL) AS attended,
            (ef.late_in_from_events
                OR (t.effective_clock_in IS NOT NULL AND ef.scheduled_start IS NOT NULL
                    AND t.effective_clock_in > ef.scheduled_start + interval '7.5 minutes')
            ) AS late_in,
            (ef.early_out_from_events
                OR (t.effective_clock_out IS NOT NULL AND ef.scheduled_end IS NOT NULL
                    AND t.effective_clock_out < ef.scheduled_end - interval '7.5 minutes')
            ) AS early_out,
            ef.shift_date,
            ef.organization_id,
            ef.department_id,
            ef.sub_department_id,
            ef.became_active_at,
            ef.scheduled_start,
            -- Attendance additions
            (t.effective_clock_in IS NOT NULL AND ef.scheduled_start IS NOT NULL
             AND t.effective_clock_in < ef.scheduled_start - interval '7.5 minutes'
            ) AS early_in,
            (t.effective_clock_out IS NOT NULL AND ef.scheduled_end IS NOT NULL
             AND t.effective_clock_out > ef.scheduled_end + interval '7.5 minutes'
            ) AS late_out,
            (t.effective_clock_in IS NOT NULL AND ef.scheduled_start IS NOT NULL
             AND t.effective_clock_in >= ef.scheduled_start - interval '7.5 minutes'
             AND t.effective_clock_in <= ef.scheduled_start + interval '7.5 minutes'
            ) AS on_time_in,
            (t.effective_clock_out IS NOT NULL AND ef.scheduled_end IS NOT NULL
             AND t.effective_clock_out >= ef.scheduled_end - interval '7.5 minutes'
             AND t.effective_clock_out <= ef.scheduled_end + interval '7.5 minutes'
            ) AS on_time_out,
            ef.attendance_status
        FROM episode_final ef
        LEFT JOIN ts_agg t
            ON t.shift_id = ef.shift_id
            AND t.employee_id = ef.employee_id
            AND t.effective_clock_in >= ef.opened_at
            AND (ef.closed_at IS NULL OR t.effective_clock_in <= ef.closed_at)
    )
    SELECT
        ep.shift_id,
        ep.episode_seq,
        ep.employee_id,
        CASE
            WHEN ep.had_emergency THEN 'emergency'
            WHEN ep.had_swap_in   THEN 'trade_approve'
            WHEN EXISTS (
                SELECT 1
                FROM public.shift_events se
                WHERE se.shift_id = ep.shift_id
                  AND se.event_type = 'ASSIGNED'
                  AND se.metadata->>'op' = 'select_winner'
                  AND se.event_time >= ep.opened_at
                  AND (ep.closed_at IS NULL OR se.event_time <= ep.closed_at)
            ) THEN 'bid_win'
            ELSE 'publish_confirm'
        END AS source,
        COALESCE(ep.became_active_at, ep.opened_at) AS became_active_at,
        ep.closed_at AS ended_at,
        CASE
            WHEN ep.terminal_outcome = 'fulfilled'          THEN 'worked'
            WHEN ep.terminal_outcome = 'cancelled_standard' THEN 'dropped_std'
            WHEN ep.terminal_outcome = 'cancelled_late'     THEN 'dropped_late'
            WHEN ep.terminal_outcome = 'no_show'            THEN 'no_show'
            WHEN ep.terminal_outcome = 'swapped_out'        THEN 'traded_out'
            WHEN ep.terminal_outcome = 'unassigned'         THEN 'reassigned'
            WHEN ep.terminal_outcome = 'open'
                 AND ep.episode_seq < MAX(ep.episode_seq) OVER (PARTITION BY ep.shift_id)
                                                             THEN 'reassigned'
            WHEN ep.terminal_outcome = 'open'               THEN NULL
            ELSE NULL
        END AS end_reason,
        ep.attended,
        ep.late_in,
        ep.early_out,
        (ep.terminal_outcome = 'open'
            AND ep.episode_seq = MAX(ep.episode_seq) OVER (PARTITION BY ep.shift_id))
                                                            AS is_current,
        ep.organization_id,
        ep.department_id,
        ep.sub_department_id,
        ep.shift_date,
        ep.scheduled_start,
        now() AS refreshed_at,
        ep.early_in,
        ep.late_out,
        ep.on_time_in,
        ep.on_time_out,
        (ep.attendance_status = 'auto_clock_out') AS auto_clock_out
    FROM episodes_for_shift ep
    WHERE (ep.had_accept OR ep.had_emergency OR ep.had_swap_in)
      AND ep.terminal_outcome <> 'shift_deleted';
END;
$$;


ALTER FUNCTION "public"."sm_refresh_shift_snapshots"("p_shift_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sm_refresh_shift_snapshots"("p_shift_id" "uuid") IS 'Re-projects public.assignment_snapshots for one shift from v_shift_assignment_episodes (published-active episodes only). Idempotent DELETE-then-INSERT; called on every shift_events insert via trg_refresh_snapshots and once per shift in the backfill.';



CREATE OR REPLACE FUNCTION "public"."sm_reject_offer"("p_shift_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_shift RECORD; v_state text;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_assignee_or(p_shift_id, p_user_id, 'shift.assign');
  -- 1. Get shift and lock it
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;
  
  IF NOT FOUND THEN 
    RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted'); 
  END IF;
  
  -- 2. Authorization check: Only the assigned employee can reject their own offer
  IF v_shift.assigned_employee_id IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: You can only reject shifts offered to you');
  END IF;

  -- 3. State check: Must be in S3 (Published + Offered)
  v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status, v_shift.assignment_outcome, v_shift.trading_status, v_shift.is_cancelled);
  
  IF v_state != 'S3' THEN
    RETURN jsonb_build_object('success', false, 'error', format('sm_reject_offer requires state S3, current state is %s', v_state));
  END IF;
  
  -- 4. Transition S3 -> S5 (Bidding)
  UPDATE public.shifts SET
    assigned_employee_id = NULL,
    assigned_at          = NULL,
    assignment_status    = 'unassigned'::public.shift_assignment_status,
    assignment_outcome   = NULL,
    bidding_status       = 'on_bidding'::public.shift_bidding_status,
    is_on_bidding        = TRUE,
    fulfillment_status   = 'bidding'::public.shift_fulfillment_status,
    last_rejected_by     = p_user_id,
    last_dropped_by      = NULL,
    last_modified_by     = p_user_id,
    updated_at           = NOW()
  WHERE id = p_shift_id;

  -- 5. Log the event for permanent history
  INSERT INTO public.shift_events (shift_id, employee_id, event_type, event_time)
  VALUES (p_shift_id, p_user_id, 'REJECTED', NOW());
  
  RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S5');
END; 
$$;


ALTER FUNCTION "public"."sm_reject_offer"("p_shift_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_reject_offer"("p_shift_id" "uuid", "p_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_shift RECORD; v_state text;
BEGIN
  -- authz guard (20261005 rpc guards): reject callers without authority before any work
  PERFORM public.sm_require_assignee_or(p_shift_id, p_user_id, 'shift.assign');
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted');
  END IF;

  IF v_shift.assigned_employee_id IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: You can only reject shifts offered to you');
  END IF;

  v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status, v_shift.assignment_outcome, v_shift.trading_status, v_shift.is_cancelled);

  IF v_state != 'S3' THEN
    RETURN jsonb_build_object('success', false, 'error', format('sm_reject_offer requires state S3, current state is %s', v_state));
  END IF;

  UPDATE public.shifts SET
    assigned_employee_id = NULL,
    assigned_at          = NULL,
    assignment_status    = 'unassigned'::public.shift_assignment_status,
    assignment_outcome   = NULL,
    bidding_status       = 'on_bidding'::public.shift_bidding_status,
    is_on_bidding        = TRUE,
    fulfillment_status   = 'bidding'::public.shift_fulfillment_status,
    last_rejected_by     = p_user_id,
    last_dropped_by      = NULL,
    last_modified_by     = p_user_id,
    updated_at           = NOW()
  WHERE id = p_shift_id;

  INSERT INTO public.shift_events (shift_id, employee_id, event_type, event_time, metadata)
  VALUES (p_shift_id, p_user_id, 'REJECTED', NOW(), jsonb_build_object('source', 'sm_reject_offer', 'reason', p_reason));

  RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S5');
END;
$$;


ALTER FUNCTION "public"."sm_reject_offer"("p_shift_id" "uuid", "p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sm_reject_trade"("p_shift_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"(), "p_reason" "text" DEFAULT 'Trade rejected'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_shift RECORD; v_state text; v_name text; v_role text;
BEGIN
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Shift not found or deleted'); END IF;
  SELECT COALESCE(first_name||' '||COALESCE(last_name,''), email), COALESCE(left(lower(legacy_system_role::text),50),'manager')
    INTO v_name, v_role FROM public.profiles WHERE id = p_user_id;
  v_name := COALESCE(v_name, 'System'); v_role := COALESCE(v_role, 'system');
  v_state := public.get_shift_fsm_state(v_shift.lifecycle_status, v_shift.assignment_status, v_shift.assignment_outcome, v_shift.trading_status, v_shift.is_cancelled);
  IF v_state != 'S10' THEN RETURN jsonb_build_object('success', false, 'error', format('sm_reject_trade requires state S10, current state is %s', v_state)); END IF;
  UPDATE public.shifts SET trading_status = 'NoTrade'::public.shift_trading, last_modified_by = p_user_id, updated_at = NOW() WHERE id = p_shift_id;
  -- shift_audit_events insert removed
  RETURN jsonb_build_object('success', true, 'from_state', v_state, 'to_state', 'S4');
END; $$;


