CREATE OR REPLACE FUNCTION "public"."state_machine_regression_snapshot_v3"() RETURNS TABLE("section" "text", "key" "text", "value" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    r RECORD;
BEGIN
    -- ====================================================
    -- SECTION 1: INVARIANT SUMMARY
    -- ====================================================
    FOR r IN
        SELECT *
        FROM check_state_machine_invariants_v3()
        ORDER BY check_name
    LOOP
        RETURN QUERY SELECT
            'invariants',
            r.check_name,
            r.status || ':' || r.violations::TEXT;
    END LOOP;

    -- ====================================================
    -- SECTION 2: TRANSITION MATRIX SNAPSHOT
    -- ====================================================
    FOR r IN
        SELECT
            from_state,
            action,
            success,
            COALESCE(to_state, 'NULL') AS to_state
        FROM test_transition_matrix_v3()
        ORDER BY from_state, action, success, to_state
    LOOP
        RETURN QUERY SELECT
            'transitions',
            r.from_state || '->' || r.action,
            (CASE WHEN r.success THEN 'ALLOW' ELSE 'BLOCK' END)
                || ':' || r.to_state;
    END LOOP;

    -- ====================================================
    -- SECTION 3: CONCURRENCY SNAPSHOT
    -- ====================================================
    FOR r IN
        SELECT
            test_name,
            actor,
            success,
            resulting_state
        FROM test_concurrency_races_v3()
        ORDER BY test_name, actor
    LOOP
        RETURN QUERY SELECT
            'concurrency',
            r.test_name || ':' || r.actor,
            (CASE WHEN r.success THEN 'ALLOW' ELSE 'BLOCK' END)
                || ':' || r.resulting_state;
    END LOOP;

END;
$$;


ALTER FUNCTION "public"."state_machine_regression_snapshot_v3"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_live_state_to_roster"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_roster_shift_id UUID;
    v_old_employee_id UUID;
    v_new_employee_id UUID;
BEGIN
    -- Only sync if this shift came from a roster_shift
    IF NEW.roster_shift_id IS NULL THEN
        RETURN NEW;
    END IF;
    
    v_roster_shift_id := NEW.roster_shift_id;
    
    -- ========================================
    -- SYNC STATE COLUMNS
    -- ========================================
    
    -- Map shifts.lifecycle_status (shift_lifecycle) to roster_shifts.lifecycle (shift_lifecycle_status)
    -- shifts uses: 'Draft', 'Published', 'InProgress', 'Completed', 'Cancelled'
    -- roster_shifts uses: 'draft', 'published', 'in_progress', 'completed', 'cancelled'
    UPDATE roster_shifts
    SET 
        -- Lifecycle: Map from shift_lifecycle to shift_lifecycle_status (handle case)
        lifecycle = CASE NEW.lifecycle_status::TEXT
            WHEN 'Draft' THEN 'draft'::shift_lifecycle_status
            WHEN 'Published' THEN 'published'::shift_lifecycle_status
            WHEN 'InProgress' THEN 'in_progress'::shift_lifecycle_status
            WHEN 'Completed' THEN 'completed'::shift_lifecycle_status
            WHEN 'Cancelled' THEN 'cancelled'::shift_lifecycle_status
            -- Handle lowercase just in case
            WHEN 'draft' THEN 'draft'::shift_lifecycle_status
            WHEN 'published' THEN 'published'::shift_lifecycle_status
            WHEN 'in_progress' THEN 'in_progress'::shift_lifecycle_status
            WHEN 'completed' THEN 'completed'::shift_lifecycle_status
            WHEN 'cancelled' THEN 'cancelled'::shift_lifecycle_status
            ELSE lifecycle  -- Keep existing if unknown
        END,
        
        -- Bidding status (same enum values, direct copy)
        bidding_status = NEW.bidding_status,
        
        -- Trading state (same enum values, direct copy)
        trading_state = NEW.trading_status,
        
        -- Attendance (same enum values, direct copy)
        attendance = NEW.attendance_status,
        
        -- Assignment outcome (same enum values, direct copy)
        assignment_outcome = NEW.assignment_outcome,
        
        -- Timestamp
        updated_at = NOW()
    WHERE id = v_roster_shift_id;
    
    -- ========================================
    -- SYNC ASSIGNMENT CHANGES
    -- ========================================
    
    -- Track old vs new employee
    v_old_employee_id := OLD.assigned_employee_id;
    v_new_employee_id := NEW.assigned_employee_id;
    
    -- If assignment changed (someone assigned, or assignment cleared)
    IF v_old_employee_id IS DISTINCT FROM v_new_employee_id THEN
        
        IF v_new_employee_id IS NOT NULL THEN
            -- Employee was assigned (bid won, offer accepted, emergency assign)
            -- Upsert into roster_shift_assignments
            INSERT INTO roster_shift_assignments (
                roster_shift_id,
                employee_id,
                status,
                assigned_by,
                assigned_at,
                confirmed_at,
                notes
            )
            VALUES (
                v_roster_shift_id,
                v_new_employee_id,
                CASE 
                    WHEN NEW.assignment_outcome = 'confirmed' THEN 'confirmed'::assignment_status
                    WHEN NEW.assignment_outcome = 'emergency_assigned' THEN 'confirmed'::assignment_status
                    WHEN NEW.assignment_outcome = 'offered' THEN 'assigned'::assignment_status
                    ELSE 'assigned'::assignment_status
                END,
                NEW.last_modified_by,
                NOW(),
                CASE 
                    WHEN NEW.assignment_outcome IN ('confirmed', 'emergency_assigned') 
                    THEN NOW() 
                    ELSE NULL 
                END,
                CASE 
                    WHEN NEW.assignment_outcome = 'emergency_assigned' 
                    THEN 'Emergency assigned from live shift'
                    ELSE 'Synced from live shift'
                END
            )
            ON CONFLICT (roster_shift_id, employee_id) 
            DO UPDATE SET
                status = EXCLUDED.status,
                confirmed_at = EXCLUDED.confirmed_at,
                notes = EXCLUDED.notes;
                
        ELSE
            -- Assignment was cleared (shift went back to bidding, etc.)
            -- Remove the assignment record
            DELETE FROM roster_shift_assignments
            WHERE roster_shift_id = v_roster_shift_id;
        END IF;
    
    -- If same employee but outcome changed (offered → confirmed)
    ELSIF v_new_employee_id IS NOT NULL 
          AND OLD.assignment_outcome IS DISTINCT FROM NEW.assignment_outcome THEN
        
        UPDATE roster_shift_assignments
        SET 
            status = CASE 
                WHEN NEW.assignment_outcome IN ('confirmed', 'emergency_assigned') 
                THEN 'confirmed'::assignment_status
                ELSE status
            END,
            confirmed_at = CASE 
                WHEN NEW.assignment_outcome IN ('confirmed', 'emergency_assigned') 
                     AND confirmed_at IS NULL
                THEN NOW()
                ELSE confirmed_at
            END
        WHERE roster_shift_id = v_roster_shift_id
        AND employee_id = v_new_employee_id;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_live_state_to_roster"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_roster_lock_for_range"("p_org_id" "uuid", "p_dept_id" "uuid", "p_sub_dept_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_lock_status" boolean) RETURNS TABLE("updated_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_count int;
BEGIN
    -- Update rosters in range matching scope
    WITH updated AS (
        UPDATE rosters r
        SET 
            is_locked = p_lock_status,
            updated_at = now()
        WHERE 
            r.organization_id = p_org_id
            AND r.department_id = p_dept_id
            AND (p_sub_dept_id IS NULL OR r.sub_department_id = p_sub_dept_id)
            AND r.date >= p_start_date
            AND r.date <= p_end_date
        RETURNING r.id
    )
    SELECT count(*) INTO v_count FROM updated;

    -- Return count of updated rosters
    RETURN QUERY SELECT v_count;
END;
$$;


ALTER FUNCTION "public"."toggle_roster_lock_for_range"("p_org_id" "uuid", "p_dept_id" "uuid", "p_sub_dept_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_lock_status" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toil_adjust"("p_employee" "uuid", "p_minutes" integer, "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'internal'
    AS $$
DECLARE
    v_today    date := internal.toil_today();
    v_balance  integer;
    v_contract uuid;
    v_id       uuid;
BEGIN
    IF NOT internal.toil_can_manage(p_employee) THEN
        RAISE EXCEPTION 'Not authorised to adjust this person''s time in lieu' USING ERRCODE = '42501';
    END IF;
    IF p_minutes IS NULL OR p_minutes = 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'Enter the hours to add or remove.';
    END IF;
    IF length(btrim(coalesce(p_reason, ''))) = 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'Say why the balance is being adjusted.';
    END IF;

    PERFORM internal.toil_lock(p_employee);
    v_balance := internal.toil_balance(p_employee);
    IF v_balance + p_minutes < 0 THEN
        RAISE EXCEPTION USING
            ERRCODE = 'check_violation',
            MESSAGE = format('That would take the balance below zero (it is %s).', internal.toil_fmt(v_balance));
    END IF;

    v_contract := coalesce(internal.toil_active_eligible_contract(p_employee, v_today),
                           internal.toil_ledger_contract(p_employee));
    IF v_contract IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = 'check_violation',
            MESSAGE = 'Time in lieu applies only to a salaried full-time or part-time contract.';
    END IF;

    INSERT INTO public.toil_ledger (employee_id, user_contract_id, entry_type, minutes, effective_date, reason)
    VALUES (p_employee, v_contract, 'adjustment', p_minutes, v_today, btrim(p_reason))
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."toil_adjust"("p_employee" "uuid", "p_minutes" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toil_process_expiries"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'internal'
    AS $$
DECLARE
    v_today    date := internal.toil_today();
    v_written  integer := 0;
    v_balance  integer;
    v_expired  integer;
    v_contract uuid;
    e          uuid;
BEGIN
    FOR e IN SELECT DISTINCT tl.employee_id FROM public.toil_ledger tl LOOP
        PERFORM internal.toil_lock(e);
        v_balance := internal.toil_balance(e);
        CONTINUE WHEN v_balance <= 0;

        IF internal.toil_active_eligible_contract(e, v_today) IS NULL THEN
            v_contract := internal.toil_ledger_contract(e);
            INSERT INTO public.toil_ledger (employee_id, user_contract_id, entry_type, minutes, effective_date, reason)
            VALUES (e, v_contract, 'termination_payout', -v_balance, v_today,
                    'No current salaried contract — remaining balance paid out');
            v_written := v_written + 1;
            CONTINUE;
        END IF;

        SELECT coalesce(sum(l.remaining), 0)::integer INTO v_expired
          FROM internal.toil_lots(e) l
         WHERE l.expires_on <= v_today;
        IF v_expired > 0 THEN
            INSERT INTO public.toil_ledger (employee_id, user_contract_id, entry_type, minutes, effective_date, reason)
            VALUES (e, coalesce(internal.toil_active_eligible_contract(e, v_today), internal.toil_ledger_contract(e)),
                    'expiry_payout', -v_expired, v_today, 'Not taken within 6 months — paid out');
            v_written := v_written + 1;
        END IF;
    END LOOP;
    RETURN v_written;
END;
$$;


ALTER FUNCTION "public"."toil_process_expiries"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toil_request_payout"("p_employee" "uuid", "p_minutes" integer, "p_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'internal'
    AS $$
DECLARE
    v_self     boolean := (auth.uid() IS NOT NULL AND auth.uid() = p_employee);
    v_today    date := internal.toil_today();
    v_balance  integer;
    v_held     integer;
    v_contract uuid;
    v_id       uuid;
BEGIN
    IF NOT (v_self OR internal.toil_can_manage(p_employee)) THEN
        RAISE EXCEPTION 'Not authorised to pay out this person''s time in lieu' USING ERRCODE = '42501';
    END IF;
    IF p_minutes IS NULL OR p_minutes <= 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'Enter how many hours to pay out.';
    END IF;

    PERFORM internal.toil_lock(p_employee);
    v_balance := internal.toil_balance(p_employee);
    v_held := internal.toil_held(p_employee, NULL);
    IF p_minutes > v_balance - v_held THEN
        RAISE EXCEPTION USING
            ERRCODE = 'check_violation',
            MESSAGE = format('Only %s can be paid out (%s balance, %s held by pending requests).',
                             internal.toil_fmt(greatest(v_balance - v_held, 0)),
                             internal.toil_fmt(v_balance), internal.toil_fmt(v_held));
    END IF;

    v_contract := coalesce(internal.toil_active_eligible_contract(p_employee, v_today),
                           internal.toil_ledger_contract(p_employee));
    IF v_contract IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'check_violation', MESSAGE = 'There is no time in lieu on record to pay out.';
    END IF;

    INSERT INTO public.toil_ledger (employee_id, user_contract_id, entry_type, minutes, effective_date, reason)
    VALUES (p_employee, v_contract, 'payout', -p_minutes, v_today,
            coalesce(nullif(btrim(p_note), ''),
                     CASE WHEN v_self THEN 'Paid out at the employee''s request' ELSE 'Paid out by a manager' END))
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."toil_request_payout"("p_employee" "uuid", "p_minutes" integer, "p_note" "text") OWNER TO "postgres";


