    "last_name" "text",
    "full_name" "text" GENERATED ALWAYS AS (
CASE
    WHEN (("last_name" IS NOT NULL) AND ("last_name" <> ''::"text")) THEN (("first_name" || ' '::"text") || "last_name")
    ELSE "first_name"
END) STORED,
    "email" "text" NOT NULL,
    "phone" "text",
    "avatar_url" "text",
    "date_of_birth" "date",
    "emergency_contact_name" "text",
