    ( SELECT "count"(*) AS "count"
           FROM "public"."broadcasts" "b"
          WHERE (("b"."channel_id" = "c"."id") AND ("b"."is_archived" = false))) AS "active_broadcast_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."broadcasts" "b"
          WHERE ("b"."channel_id" = "c"."id")) AS "total_broadcast_count",
